package com.coinflow;

import java.util.Map;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;

/**
 * Pure classifiers for menu-option target strings and player animations.
 * Used to decide whether a menu click/animation indicates container
 * interaction, farming, firemaking, alchemy, or defensive stances.
 */
final class ActionClassifiers
{
	private ActionClassifiers() {}

	static boolean isContainerOrChargedItemTarget(String lowerTarget)
	{
		if (lowerTarget == null || isFarmingPatchAction(lowerTarget))
		{
			return false;
		}
		// Coin pouches (Thieving) turn into coins in place — "Open" is a real
		// gain, not a storage container, and must not trigger a re-baseline.
		if (lowerTarget.equals("coin pouch"))
		{
			return false;
		}
		return lowerTarget.contains("gem bag") || lowerTarget.contains("gem sack")
			|| lowerTarget.contains("gem pouch") || lowerTarget.contains("gem satchel") || lowerTarget.contains("gem tote")
			|| lowerTarget.contains("herb sack")
			|| lowerTarget.contains("fish barrel") || lowerTarget.contains("fish sack barrel")
			|| lowerTarget.contains("log basket") || lowerTarget.contains("forestry basket")
			|| lowerTarget.contains("seed box")
			|| lowerTarget.contains("ash sanctifier")
			|| lowerTarget.contains("bonecrusher")
			|| lowerTarget.contains("tackle box")
			|| lowerTarget.contains("plank sack")
			|| lowerTarget.contains("bottomless compost bucket")
			|| lowerTarget.contains("coal bag")
			// Essence pouches (small/medium/large/giant/colossal): Fill/Empty moves
			// essence between inventory and pouch without consuming it.
			|| lowerTarget.endsWith(" pouch") || lowerTarget.equals("pouch")
			// Charged weapons: Charge/Uncharge/Unload actions return stored resources to
			// inventory, so the diff must be rebaselined rather than treated as profit.
			|| lowerTarget.contains("toxic blowpipe")
			|| lowerTarget.contains("trident of the")
			|| lowerTarget.contains("sanguinesti")
			|| lowerTarget.contains("tumeken's shadow") || lowerTarget.contains("tumekens shadow")
			|| lowerTarget.contains("craw's bow") || lowerTarget.contains("webweaver bow")
			|| lowerTarget.contains("viggora's chainmace") || lowerTarget.contains("thammaron's sceptre")
			|| lowerTarget.contains("accursed sceptre") || lowerTarget.contains("ursine chainmace")
			|| lowerTarget.contains("serpentine helm") || lowerTarget.contains("toxic staff")
			|| lowerTarget.contains("bow of faerdhinen") || lowerTarget.contains("blade of saeldor")
			|| lowerTarget.contains("crystal helm") || lowerTarget.contains("crystal body")
			|| lowerTarget.contains("crystal legs")
			|| lowerTarget.contains("venator bow") || lowerTarget.contains("tonalztics")
			|| lowerTarget.contains("tome of fire") || lowerTarget.contains("tome of water")
			|| lowerTarget.contains("tome of earth")
			|| lowerTarget.contains("ring of suffering") || lowerTarget.contains("xeric's talisman")
			|| lowerTarget.contains("bryophyta's staff") || lowerTarget.contains("arclight")
			|| lowerTarget.contains("amulet of blood fury") || lowerTarget.contains("bracelet of ethereum");
	}

	static boolean isFarmingPatchAction(String lowerTarget)
	{
		if (lowerTarget == null)
		{
			return false;
		}
		if (lowerTarget.contains("->"))
		{
			String[] parts = lowerTarget.split("->");
			if (parts.length >= 2)
			{
				String dest = parts[1].trim();
				return dest.contains("patch") || dest.contains("allotment")
					|| dest.contains("plant pot") || dest.contains("compost bin")
					|| dest.contains("soil") || dest.contains("vine");
			}
		}
		return lowerTarget.contains("patch") || lowerTarget.contains("plant pot") || lowerTarget.contains("allotment")
			|| lowerTarget.contains("compost bin") || lowerTarget.contains("soil") || lowerTarget.contains("vine");
	}

	static boolean isBirdHouseAction(String lowerTarget)
	{
		if (lowerTarget == null)
		{
			return false;
		}
		return lowerTarget.contains("bird house") || lowerTarget.contains("birdhouse");
	}

	static boolean isFarmingAnimation(int anim)
	{
		return anim == AnimationID.FARMING_SEED_DIBBING
			|| anim == AnimationID.FARMING_SEED_DIBBING_NODIB
			|| anim == AnimationID.FARMING_POUR_WATER
			|| anim == AnimationID.FARMING_PLANT_CURE
			|| anim == AnimationID.FARMING_TROWEL_DIG
			|| anim == AnimationID.FARMING_TROWEL_DIGGING
			|| anim == AnimationID.FARMING_TROWEL_SHORTDIG
			|| anim == AnimationID.FARMING_FILLING_PLANTPOT
			|| anim == AnimationID.FARMING_POUR_WATER_BOTTOMLESSBUCKET;
	}

	static boolean isFiremakingAnimation(int anim)
	{
		return anim == AnimationID.HUMAN_CREATEFIRE_SINGLE
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_GENERIC_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_OAK_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_WILLOW_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_TEAK_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_ARCTIC_PINE_LOG_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_MAPLE_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_MAHOGANY_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_YEW_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_MAGIC_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_REDWOOD_LOGS_NOLOOP
			|| anim == AnimationID.FORESTRY_CAMPFIRE_BURNING_BLISTERWOOD_LOGS_NOLOOP;
	}

	static boolean isAlchemyAnimation(int anim)
	{
		return anim == AnimationID.HUMAN_CASTHIGHLVLALCHEMY
			|| anim == AnimationID.HUMAN_CASTLOWLVLALCHEMY
			|| anim == AnimationID.HUMAN_CASTHIGHLVLALCHEMY_FIRE
			|| anim == AnimationID.HUMAN_CASTLOWLVLALCHEMY_FIRE;
	}

	static boolean isDefensiveAnimation(int anim)
	{
		return anim == AnimationID.HUMAN_UNARMEDBLOCK
			|| anim == AnimationID.HUMAN_BLUNT_BLOCK
			|| anim == AnimationID.HUMAN_BLUNT_DEF
			|| anim == AnimationID.HUMAN_SWORD_DEF
			|| anim == AnimationID.HUMAN_STAFFORB_BLOCK
			|| anim == AnimationID.HUMAN_SHIELD_DEFENCE;
	}

	/**
	 * True when the diff is exactly "coins out, non-coin items in": the shape of
	 * an NPC dialogue purchase. Any other loss (noting fee, processing input,
	 * consumed supply) disqualifies it so those handlers keep ownership. Coins
	 * exchanged only for platinum tokens is a currency conversion, not a buy.
	 */
	static boolean isCoinsOnlyPurchase(Map<Integer, Integer> rawGains, Map<Integer, Integer> rawLosses)
	{
		if (rawLosses.size() != 1 || rawGains.isEmpty())
		{
			return false;
		}
		Integer coinsLost = rawLosses.get(ItemID.COINS);
		if (coinsLost == null || coinsLost <= 0)
		{
			return false;
		}
		for (int gainedId : rawGains.keySet())
		{
			if (gainedId != ItemID.COINS && gainedId != ItemID.PLATINUM)
			{
				return true;
			}
		}
		return false;
	}
}

package com.coinflow;

import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.StatChanged;

/**
 * Player-activity and skill-signal tracking: XP gains, player animations and
 * attack graphics, and the idle heuristic that drives {@code session.tick}.
 * Owns only its private state; the skill-XP maps and animation ticks remain
 * {@link CoinFlowPlugin} fields (visible to tests) and are mutated through
 * the plugin reference.
 */
final class ActivityMonitor
{
	private final CoinFlowPlugin plugin;
	private WorldPoint lastPlayerLocation;
	private int lastPlayerActivityTick = -100;

	ActivityMonitor(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int currentXp = event.getXp();
		Integer prevXp = plugin.previousSkillXp.get(skill);
		if (prevXp != null && currentXp > prevXp && plugin.client != null)
		{
			plugin.lastSkillXpTicks.put(skill, plugin.client.getTickCount());
			recordPlayerActivity();
		}
		plugin.previousSkillXp.put(skill, currentXp);
	}

	void onAnimationChanged(AnimationChanged event)
	{
		if (plugin.client != null && event.getActor() == plugin.client.getLocalPlayer())
		{
			int anim = plugin.client.getLocalPlayer().getAnimation();
			if (anim != -1 && !ActionClassifiers.isDefensiveAnimation(anim))
			{
				recordPlayerActivity();
			}
			if (ActionClassifiers.isFiremakingAnimation(anim))
			{
				plugin.lastFiremakingAnimTick = plugin.client.getTickCount();
			}
			else if (ActionClassifiers.isFarmingAnimation(anim))
			{
				plugin.lastFarmingAnimTick = plugin.client.getTickCount();
			}
			else if (ActionClassifiers.isAlchemyAnimation(anim))
			{
				plugin.lastAlchAnimTick = plugin.client.getTickCount();
			}
			plugin.weaponChargeTracker.onAttackAnimation(anim, plugin.equippedWeaponName(),
				plugin.client.getTickCount());
		}
	}

	void onGraphicChanged(GraphicChanged event)
	{
		if (plugin.client != null && event.getActor() != null && event.getActor() == plugin.client.getLocalPlayer())
		{
			plugin.weaponChargeTracker.onAttackGraphic(event.getActor().getGraphic(), plugin.equippedWeaponName(),
				plugin.client.getTickCount());
		}
	}

	void recordPlayerActivity()
	{
		if (plugin.client != null)
		{
			lastPlayerActivityTick = plugin.client.getTickCount();
		}
		if (plugin.session != null && plugin.session.isIdle())
		{
			plugin.session = plugin.session.withActivity();
		}
	}

	boolean isPlayerActive()
	{
		if (plugin.client == null || plugin.client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		Player localPlayer = plugin.client.getLocalPlayer();
		if (localPlayer == null)
		{
			return false;
		}

		// 1. Movement: World location changed since last tick
		WorldPoint currentLoc = localPlayer.getWorldLocation();
		boolean moved = false;
		if (currentLoc != null)
		{
			moved = lastPlayerLocation != null && !lastPlayerLocation.equals(currentLoc);
			lastPlayerLocation = currentLoc;
		}

		// 2. Action animation (woodcutting, mining, combat, casting, etc.)
		// NOTE: pose animation is deliberately not used — it stays in combat stance
		// for the whole fight, which would prevent AFK combat from ever going idle.
		boolean animating = localPlayer.getAnimation() != -1;

		// 3. Recent user-triggered action (menu click, item container change, XP drop within last 2 ticks)
		int currentTick = plugin.client.getTickCount();
		int diff = currentTick - lastPlayerActivityTick;
		boolean recentAction = diff >= 0 && diff <= 2;

		// 4. Direct input: mouse moved or key pressed recently (< 50 client cycles / ~1 sec)
		boolean activeInput = false;
		try
		{
			activeInput = plugin.client.getMouseIdleTicks() < 50 || plugin.client.getKeyboardIdleTicks() < 50;
		}
		catch (Throwable ignored)
		{
		}

		return moved || animating || recentAction || activeInput;
	}

	void reset()
	{
		plugin.lastSkillXpTicks.clear();
		plugin.previousSkillXp.clear();
		plugin.lastFiremakingAnimTick = -100;
		plugin.lastAlchAnimTick = -100;
		plugin.lastFarmingAnimTick = -100;
		lastPlayerLocation = null;
		lastPlayerActivityTick = -100;
	}
}

package com.coinflow;

import com.coinflow.reconciliation.BlastFurnaceHandler;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.gameval.ItemID;

/**
 * Blast Furnace bookkeeping. Two ledgers:
 *
 * <b>Coffer.</b> The coffer is a balance — deposits and withdrawals move
 * coins between the inventory and the furnace, so only the 12 gp/tick drain
 * is a real expense. Coin-only diffs are held aside and settled each tick
 * against the {@code BLAST_FURNACE_COFFER} varbit: an increase matched to a
 * held loss is a deposit (no expense), a decrease matched to a held gain is
 * a withdrawal (no profit), and any remaining decrease is drain — capped at
 * {@link #DRAIN_PER_TICK} per tick since the last observed change so a
 * withdrawal swallowed by a re-baseline can never book as thousands of gp of
 * "drain". A deposit racing a drain tick leaves a small held remainder
 * (the coffer rose by less than the coins lost) — attributed to drain up to
 * the same cap rather than expiring into a {@code Coins} spend. Drain
 * accrues and is charged to the synthetic
 * {@link #COFFER_ROW_NAME} row in batches of {@link #DRAIN_FLUSH_GP}, on
 * leaving the furnace, and on logout. Held coins that never match (e.g. the
 * 2,500 gp foreman fee) fall back to a {@code Coins} cash spend after
 * {@link #GRACE_TICKS} ticks.
 *
 * <b>Dispenser rescue.</b> Bar collections arriving inside a re-baseline
 * window are normally swallowed as baseline noise. Dispenser varbit
 * decreases are recorded so matching bar gains within
 * {@link #RESCUE_WINDOW_TICKS} ticks can be rescued with their recipe
 * expenses — bank-chest bar withdrawals produce no dispenser decrease and
 * are never rescued.
 */
@Slf4j
final class BlastFurnaceTracker
{
	/** Synthetic expense row id: a coin-pile icon distinct from GE Tax's COINS_10000. */
	static final int COFFER_ROW_ID = ItemID.COINS_1000;
	static final String COFFER_ROW_NAME = "Blast Furnace coffer";

	static final int DRAIN_PER_TICK = 12;
	static final int DRAIN_FLUSH_GP = 1_200;
	static final int GRACE_TICKS = 2;
	static final int RESCUE_WINDOW_TICKS = 3;

	private final CoinFlowPlugin plugin;

	/** True while the conveyor belt object is present in the loaded scene. */
	private boolean active;

	private int lastCofferValue = -1;
	private int lastCofferChangeTick = -1;
	private int pendingDrainGp = 0;

	/** Held coin-only diffs awaiting a coffer-varbit match. */
	private int heldCoinLoss = 0;
	private int heldCoinLossTick = -1;
	private int heldCoinGain = 0;
	private int heldCoinGainTick = -1;

	/** Last seen value per dispenser varbit (varbit id -> bar count). */
	private final Map<Integer, Integer> lastDispenserValues = new HashMap<>();

	/** Bar item id -> quantity the dispenser recently delivered. */
	private final Map<Integer, Integer> recentDispensed = new HashMap<>();
	private int recentDispensedTick = -1;

	BlastFurnaceTracker(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	boolean isActive()
	{
		return active;
	}

	/**
	 * Outcome of a per-tick coffer settle, applied by the caller.
	 */
	static final class Settlement
	{
		/** Expired held coin loss -> {@code Coins} cash spend at face value. */
		int cashSpendCoins;
		/** Expired held coin gain -> re-applied as a normal coin gain. */
		int coinGainQty;
		/** Accrued coffer drain to charge on {@link #COFFER_ROW_ID}. */
		int drainChargeGp;
	}

	// ── Presence detection ──────────────────────────────────────────────

	void onObjectSpawn(int objectId)
	{
		if (objectId == net.runelite.api.gameval.ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE && !active)
		{
			active = true;
			// The coffer varbit holds its value across scene loads; the first
			// read after arriving only re-baselines it.
			lastCofferValue = -1;
			lastCofferChangeTick = -1;
			lastDispenserValues.clear();
			log.debug("Blast Furnace entered");
		}
	}

	void onObjectDespawn(int objectId)
	{
		if (objectId == net.runelite.api.gameval.ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE)
		{
			active = false;
			log.debug("Blast Furnace left");
		}
	}

	void onGameStateChanged(GameState state)
	{
		if (state == GameState.LOADING)
		{
			active = false;
		}
	}

	/**
	 * One-shot scene lookup for a plugin enabled while already at the
	 * furnace (no spawn event fires for already-loaded objects).
	 */
	void checkSceneForConveyor()
	{
		if (plugin.client == null)
		{
			return;
		}
		net.runelite.api.WorldView worldView = plugin.client.getTopLevelWorldView();
		if (worldView == null || worldView.getScene() == null)
		{
			return;
		}
		net.runelite.api.Tile[][][] tiles = worldView.getScene().getTiles();
		if (tiles == null)
		{
			return;
		}
		int plane = worldView.getPlane();
		if (plane < 0 || plane >= tiles.length)
		{
			return;
		}
		for (net.runelite.api.Tile[] row : tiles[plane])
		{
			for (net.runelite.api.Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}
				for (net.runelite.api.GameObject obj : tile.getGameObjects())
				{
					if (obj != null && obj.getId() == net.runelite.api.gameval.ObjectID.BLAST_FURNACE_CONVEYER_BELT_CLICKABLE)
					{
						onObjectSpawn(obj.getId());
						return;
					}
				}
			}
		}
	}

	// ── Coin diff holding ───────────────────────────────────────────────

	/**
	 * Pulls a coin-only diff out of the raw maps while at the furnace so the
	 * coffer varbit can attribute it (deposit/withdrawal/drain) next tick.
	 * Diffs containing anything but coins stay untouched — purchases and
	 * mixed losses keep their normal accounting.
	 *
	 * @return true if coins were held (the diff was coin-only)
	 */
	boolean holdCoins(Map<Integer, Integer> rawGains, Map<Integer, Integer> rawLosses,
		int tick, boolean coinDropIntent)
	{
		if (!active || plugin.session == null)
		{
			return false;
		}
		if (rawLosses.size() == 1 && rawGains.isEmpty() && !coinDropIntent)
		{
			Map.Entry<Integer, Integer> entry = rawLosses.entrySet().iterator().next();
			int canonical = plugin.itemManager != null ? plugin.itemManager.canonicalize(entry.getKey()) : entry.getKey();
			if (canonical == ItemID.COINS)
			{
				heldCoinLoss += entry.getValue();
				heldCoinLossTick = tick;
				rawLosses.remove(entry.getKey());
				return true;
			}
		}
		if (rawGains.size() == 1 && rawLosses.isEmpty())
		{
			Map.Entry<Integer, Integer> entry = rawGains.entrySet().iterator().next();
			int canonical = plugin.itemManager != null ? plugin.itemManager.canonicalize(entry.getKey()) : entry.getKey();
			if (canonical == ItemID.COINS)
			{
				heldCoinGain += entry.getValue();
				heldCoinGainTick = tick;
				rawGains.remove(entry.getKey());
				return true;
			}
		}
		return false;
	}

	// ── Dispenser varbit / bar rescue ───────────────────────────────────

	/**
	 * Records dispenser bar-varbit decreases so a collection swallowed by a
	 * re-baseline can still be credited. Called for every varbit event while
	 * at the furnace; non-dispenser ids are ignored.
	 */
	void onDispenserVarbit(int varbitId, int value, int tick)
	{
		if (!active)
		{
			return;
		}
		Integer barId = BlastFurnaceHandler.DISPENSER_VARBIT_TO_BAR.get(varbitId);
		if (barId == null)
		{
			return;
		}
		int prev = lastDispenserValues.getOrDefault(varbitId, -1);
		lastDispenserValues.put(varbitId, value);
		if (prev >= 0 && value < prev)
		{
			recentDispensed.merge(barId, prev - value, Integer::sum);
			recentDispensedTick = tick;
		}
	}

	/**
	 * Rescues bar gains about to be swallowed by a re-baseline, crediting the
	 * bars and charging their recipe inputs. Only unnoted recipe-bar gains
	 * matching a dispenser decrease inside {@link #RESCUE_WINDOW_TICKS} are
	 * rescued — bank-chest bar withdrawals produce no decrease. Caller must
	 * only invoke this when the diff has no losses.
	 */
	void rescueBars(Map<Integer, Integer> rawGains, int tick)
	{
		if (!active || plugin.session == null || rawGains.isEmpty()
			|| recentDispensed.isEmpty() || tick - recentDispensedTick > RESCUE_WINDOW_TICKS)
		{
			return;
		}

		Map<Integer, Integer> rescued = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : rawGains.entrySet())
		{
			int gainedId = entry.getKey();
			int canonical = plugin.itemManager != null ? plugin.itemManager.canonicalize(gainedId) : gainedId;
			if (canonical != gainedId || !BlastFurnaceHandler.BAR_IDS.contains(canonical))
			{
				continue;
			}
			int avail = recentDispensed.getOrDefault(canonical, 0);
			int qty = Math.min(entry.getValue(), avail);
			if (qty <= 0)
			{
				continue;
			}
			rescued.merge(canonical, qty, Integer::sum);
			int remainingAvail = avail - qty;
			if (remainingAvail <= 0)
			{
				recentDispensed.remove(canonical);
			}
			else
			{
				recentDispensed.put(canonical, remainingAvail);
			}
		}
		if (rescued.isEmpty())
		{
			return;
		}

		for (Map.Entry<Integer, Integer> entry : rescued.entrySet())
		{
			if (rawGains.getOrDefault(entry.getKey(), 0) <= entry.getValue())
			{
				rawGains.remove(entry.getKey());
			}
			else
			{
				rawGains.put(entry.getKey(), rawGains.get(entry.getKey()) - entry.getValue());
			}
		}

		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : rescued.entrySet())
		{
			recipeExpenses(entry.getKey(), entry.getValue())
				.forEach((id, item) -> expenses.merge(id, item, (a, b) -> a.merge(b)));
		}
		log.debug("Blast Furnace bars rescued from re-baseline: {}", rescued);
		plugin.processGainsLossesAndExpenses(rescued, Collections.emptyMap(), expenses);
	}

	// ── Coffer settlement ───────────────────────────────────────────────

	/**
	 * Per-tick coffer settle. Matches held coins against the coffer balance
	 * delta, accrues the capped drain, and expires unmatched held coins into
	 * fallback accounting. Pass {@code cofferValue < 0} when the varbit could
	 * not be read this tick.
	 */
	Settlement onTick(int cofferValue, int tick)
	{
		Settlement s = new Settlement();
		if (!active)
		{
			s.drainChargeGp = flushDrain();
			return s;
		}
		if (cofferValue < 0)
		{
			return s;
		}
		if (lastCofferValue < 0)
		{
			lastCofferValue = cofferValue;
			lastCofferChangeTick = tick;
			return s;
		}

		// Expire held coins that never met a coffer change BEFORE matching —
		// a stale entry (e.g. ticks skipped on an unsupported world) must not
		// attach itself to a fresh coffer delta.
		if (heldCoinLoss > 0 && heldCoinLossTick >= 0 && tick - heldCoinLossTick > GRACE_TICKS)
		{
			s.cashSpendCoins = heldCoinLoss;
			heldCoinLoss = 0;
			heldCoinLossTick = -1;
		}
		if (heldCoinGain > 0 && heldCoinGainTick >= 0 && tick - heldCoinGainTick > GRACE_TICKS)
		{
			s.coinGainQty = heldCoinGain;
			heldCoinGain = 0;
			heldCoinGainTick = -1;
		}

		int delta = cofferValue - lastCofferValue;
		if (delta != 0)
		{
			int elapsed = lastCofferChangeTick >= 0 ? Math.max(1, tick - lastCofferChangeTick) : 1;
			lastCofferValue = cofferValue;
			lastCofferChangeTick = tick;

			if (delta > 0)
			{
				// Deposit: the held coin loss leaves inventory for the coffer —
				// a balance transfer, not a spend. An increase beyond the held
				// amount (held diff swallowed) is likewise a transfer.
				int leftover = heldCoinLoss - delta;
				if (leftover > 0)
				{
					// Deposit raced a drain tick: the coffer rose by less than
					// the coins lost because some drained the same tick.
					// Attribute the remainder to drain (capped) rather than
					// letting it expire into a Coins spend.
					int cap = DRAIN_PER_TICK * elapsed + DRAIN_PER_TICK;
					int drain = Math.min(leftover, cap);
					pendingDrainGp += drain;
					leftover -= drain;
				}
				heldCoinLoss = Math.max(0, leftover);
			}
			else
			{
				int decrease = -delta;
				int withdrawn = Math.min(decrease, heldCoinGain);
				heldCoinGain -= withdrawn;
				int remaining = decrease - withdrawn;
				if (remaining > 0)
				{
					// Drain is capped so a withdrawal whose coin gain was
					// swallowed by a re-baseline can never book as spend.
					int cap = DRAIN_PER_TICK * elapsed + DRAIN_PER_TICK;
					int drain = Math.min(remaining, cap);
					pendingDrainGp += drain;
					if (remaining - drain > 0)
					{
						log.debug("Blast Furnace coffer: {} gp decrease beyond drain cap treated as withdrawal",
							remaining - drain);
					}
				}
			}
		}

		if (pendingDrainGp >= DRAIN_FLUSH_GP)
		{
			s.drainChargeGp = flushDrain();
		}
		return s;
	}

	/**
	 * Charges the accrued drain to the coffer row now (logout boundary).
	 */
	void onLeftLoggedIn()
	{
		int gp = flushDrain();
		if (gp > 0)
		{
			applyDrain(gp);
		}
		lastCofferValue = -1;
		lastCofferChangeTick = -1;
		heldCoinLoss = 0;
		heldCoinLossTick = -1;
		heldCoinGain = 0;
		heldCoinGainTick = -1;
	}

	private int flushDrain()
	{
		int gp = pendingDrainGp;
		pendingDrainGp = 0;
		return gp;
	}

	private void applyDrain(int gp)
	{
		if (plugin.session == null)
		{
			return;
		}
		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		expenses.put(COFFER_ROW_ID,
			new CoinFlowSession.TrackedItem(COFFER_ROW_ID, COFFER_ROW_NAME, gp, 1L));
		log.debug("Blast Furnace coffer drain charged: {} gp", gp);
		plugin.processGainsLossesAndExpenses(Collections.emptyMap(), Collections.emptyMap(), expenses);
	}

	/** Shared recipe-expense builder for collections and rescues. */
	private Map<Integer, CoinFlowSession.TrackedItem> recipeExpenses(int barId, int barQty)
	{
		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		Map<Integer, Integer> recipe = BlastFurnaceHandler.RECIPES.get(barId);
		String barName = plugin.getItemName(barId);
		if (recipe == null
			|| ConsumableRegistry.isIgnoredName(barName, plugin.ignoredItemNames))
		{
			return expenses;
		}
		for (Map.Entry<Integer, Integer> input : recipe.entrySet())
		{
			int inputId = input.getKey();
			String inputName = plugin.getItemName(inputId);
			if (ConsumableRegistry.isIgnoredName(inputName, plugin.ignoredItemNames))
			{
				continue;
			}
			long price = ItemPricing.priceOf(inputId, plugin.itemManager);
			expenses.merge(inputId,
				new CoinFlowSession.TrackedItem(inputId, inputName, (long) input.getValue() * barQty, price),
				(a, b) -> a.merge(b));
		}
		return expenses;
	}

	// ── Resets ──────────────────────────────────────────────────────────

	/**
	 * Plugin startUp/shutDown: full reset including {@link #active} — the
	 * player may have walked away while the plugin was off, and the startup
	 * scene lookup re-detects the conveyor if still there.
	 */
	void reset()
	{
		active = false;
		resetSession();
	}

	/**
	 * Session/account reset: discards accrued drain (it belonged to the old
	 * session) and all bookkeeping. {@link #active} intentionally survives —
	 * no spawn event will re-fire for the already-loaded conveyor, and the
	 * next onTick re-baselines the coffer anyway.
	 */
	void resetSession()
	{
		lastCofferValue = -1;
		lastCofferChangeTick = -1;
		pendingDrainGp = 0;
		clearTransient();
	}

	/**
	 * Transient reset (logout, shutdown, resetSession): held coins and the
	 * rescue ledger never survive a boundary.
	 */
	void clearTransient()
	{
		heldCoinLoss = 0;
		heldCoinLossTick = -1;
		heldCoinGain = 0;
		heldCoinGainTick = -1;
		recentDispensed.clear();
		recentDispensedTick = -1;
		lastDispenserValues.clear();
	}
}

package com.coinflow;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;

/**
 * Dwarf multicannon bookkeeping. Setting a cannon up removes its four parts
 * (base/stand/barrels/furnace) and loaded cannonballs from the inventory for
 * as long as it stays deployed — far beyond the ~6-minute expiry of the
 * dropped-items bookkeeping — so a later pick-up (or reclaim from Nulodion
 * after logout/decay) would book the returned kit as fresh profit.
 *
 * Deployed parts are held in {@link #deployedParts} with no expiry — they
 * survive logout since the cannon itself does — and clear only on
 * startUp/shutDown/session reset. Loaded balls are still expensed as ammo at
 * load time (live GP/hr stays right); balls returned on pick-up or Empty
 * reverse that expense rather than booking loot.
 */
@Slf4j
final class CannonTracker
{
	/** The four kit parts (plus the Leagues ornament-kit variants). */
	private static final Set<Integer> CANNON_PART_IDS = new HashSet<>(java.util.Arrays.asList(
		ItemID.TWPART1, ItemID.TWPART2, ItemID.TWPART3, ItemID.TWPART4,
		ItemID.LEAGUE_3_MULTICANNON_BASE, ItemID.LEAGUE_3_MULTICANNON_STAND,
		ItemID.LEAGUE_3_MULTICANNON_BARRELS, ItemID.LEAGUE_3_MULTICANNON_FURNACE));

	/** Cannonball types the dwarf cannon can be loaded and fired with. */
	private static final Set<Integer> CANNONBALL_IDS = new HashSet<>(java.util.Arrays.asList(
		ItemID.MCANNONBALL, ItemID.GRANITE_CANNONBALL));

	private final CoinFlowPlugin plugin;

	/** Canonical id -> quantity of parts currently deployed as a cannon. */
	private final Map<Integer, Integer> deployedParts = new HashMap<>();

	/** Canonical id -> quantity of balls loaded into the deployed cannon. */
	private final Map<Integer, Integer> loadedBalls = new HashMap<>();

	CannonTracker(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	boolean isDeployed()
	{
		return !deployedParts.isEmpty();
	}

	/** Clears all cannon state (startUp/shutDown/session reset). */
	void reset()
	{
		deployedParts.clear();
		loadedBalls.clear();
	}

	/** Drops only the loaded-balls estimate (logout/session transient reset). */
	void clearLoadedBalls()
	{
		loadedBalls.clear();
	}

	static boolean isCannonPart(int canonicalItemId)
	{
		return CANNON_PART_IDS.contains(canonicalItemId);
	}

	static boolean isCannonball(int canonicalItemId)
	{
		return CANNONBALL_IDS.contains(canonicalItemId);
	}

	/**
	 * Nets deployed-cannon traffic out of an inventory diff. Must run on every
	 * inventory diff — including diffs that end up re-baselined, where a part
	 * gain would otherwise desync {@link #deployedParts} — but never while a
	 * shop is open (a shop purchase handled by ShopTracker is not a deploy).
	 *
	 * @param gains gained quantities, canonical ids, mutated in place
	 * @param losses lost quantities, canonical ids, mutated in place
	 * @param currentTick client tick, used to respect Drop-click intents
	 * @param shopOpen whether a shop interface is open — part/ball gains then
	 *        are purchases, never cannon returns, and must not net
	 * @return id -&gt; quantity of loaded balls returned to the inventory; the
	 *         caller applies these as expense reversals
	 */
	Map<Integer, Long> netDiff(Map<Integer, Integer> gains, Map<Integer, Integer> losses,
		int currentTick, boolean shopOpen)
	{
		Map<Integer, Long> reversals = new HashMap<>();
		boolean wasDeployed = isDeployed();

		if (losses != null)
		{
			Iterator<Map.Entry<Integer, Integer>> it = losses.entrySet().iterator();
			while (it.hasNext())
			{
				Map.Entry<Integer, Integer> entry = it.next();
				int id = plugin.itemManager != null ? plugin.itemManager.canonicalize(entry.getKey()) : entry.getKey();
				if (isCannonPart(id) && !plugin.isDropIntentActive(id, currentTick))
				{
					deployedParts.merge(id, entry.getValue(), Integer::sum);
					it.remove();
					log.debug("Cannon part deployed: {} x{}", id, entry.getValue());
				}
				else if (isCannonball(id) && wasDeployed && !plugin.isDropIntentActive(id, currentTick))
				{
					loadedBalls.merge(id, entry.getValue(), Integer::sum);
					log.debug("Loaded cannonball x{} (total {})", entry.getValue(), loadedBalls.get(id));
				}
			}
		}

		if (gains != null && !shopOpen)
		{
			Iterator<Map.Entry<Integer, Integer>> it = gains.entrySet().iterator();
			while (it.hasNext())
			{
				Map.Entry<Integer, Integer> entry = it.next();
				int id = plugin.itemManager != null ? plugin.itemManager.canonicalize(entry.getKey()) : entry.getKey();
				if (isCannonPart(id) && wasDeployed)
				{
					int returned = Math.min(entry.getValue(), deployedParts.getOrDefault(id, 0));
					if (returned > 0)
					{
						deployedParts.compute(id, (k, v) -> v - returned <= 0 ? null : v - returned);
						entry.setValue(entry.getValue() - returned);
						log.debug("Cannon part returned: {} x{}", id, returned);
					}
					if (entry.getValue() <= 0)
					{
						it.remove();
					}
				}
				else if (isCannonball(id) && wasDeployed)
				{
					int returned = Math.min(entry.getValue(), loadedBalls.getOrDefault(id, 0));
					if (returned > 0)
					{
						loadedBalls.compute(id, (k, v) -> v - returned <= 0 ? null : v - returned);
						reversals.merge(id, (long) returned, Long::sum);
						entry.setValue(entry.getValue() - returned);
						log.debug("Cannonball returned: {} x{}", id, returned);
					}
					if (entry.getValue() <= 0)
					{
						it.remove();
					}
				}
			}
		}

		if (deployedParts.isEmpty())
		{
			loadedBalls.clear();
		}
		return reversals;
	}
}

package com.coinflow;

import java.util.regex.Matcher;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.util.Text;

/**
 * Routes game chat messages into plugin signals: death reclaim fees and
 * gravestone retrievals, firemaking/farming chat ticks, container pickups
 * that bypass inventory diffs, re-baselining container notifications, and
 * skilling-gem correlation for gem-bag drops.
 */
final class ChatMessageHandler
{
	private final CoinFlowPlugin plugin;

	ChatMessageHandler(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.SPAM || event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			String msg = event.getMessage();
			String cleanMsg = Text.removeTags(msg);
			Matcher deathFee = ChatMessageParser.DEATH_FEE_MESSAGE.matcher(cleanMsg);
			if (deathFee.find())
			{
				plugin.deathTracker.noteChatFee(Long.parseLong(deathFee.group(1).replace(",", "")),
					plugin.client != null ? plugin.client.getTickCount() : 0);
			}
			else if (ChatMessageParser.GRAVE_RETRIEVAL_MESSAGE.matcher(cleanMsg).find())
			{
				plugin.deathTracker.noteGraveRetrieval(plugin.client != null ? plugin.client.getTickCount() : 0);
			}
			else if (msg.contains("fire catches") || msg.contains("light the logs") || msg.contains("burn the logs")
				|| msg.contains("burn some") || msg.contains("add a log to the fire"))
			{
				plugin.lastFiremakingChatTick = plugin.client != null ? plugin.client.getTickCount() : 0;
			}
			else if (msg.startsWith("You plant ") || msg.startsWith("You treat the ")
				|| (msg.startsWith("You put the ") && msg.contains("plant pot"))
				|| msg.startsWith("You cure the "))
			{
				int tick = plugin.client != null ? plugin.client.getTickCount() : 0;
				plugin.lastFarmingChatTick = tick;
				plugin.lastSkillXpTicks.put(Skill.FARMING, tick);
			}
			else if (msg.contains("into your open gem bag") || msg.contains("into your open gem sack")
				|| msg.contains("into your open gem pouch") || msg.contains("into your open gem satchel")
				|| msg.contains("into your open gem tote"))
			{
				int currentTick = plugin.client != null ? plugin.client.getTickCount() : 0;
				int gemId = CoinFlowPlugin.findUncutGemIdInMessage(msg);
				if (gemId <= 0 && plugin.lastSkillingGemId > 0 && currentTick - plugin.lastSkillingGemTick <= 3)
				{
					gemId = plugin.lastSkillingGemId;
				}
				if (gemId > 0)
				{
					plugin.containerPickupTracker.pendingGemBagPickups.add(new CoinFlowPlugin.LootPickup(gemId, 1));
					plugin.lastSkillingGemId = -1;
				}
			}
			else if (msg.contains("into your open herb sack") || msg.contains("into your herb sack")
				|| ChatMessageParser.HERBIBOAR_HERB_SACK_PATTERN.matcher(msg).matches())
			{
				int herbId = CoinFlowPlugin.findGrimyHerbIdInMessage(msg);
				if (herbId > 0)
				{
					plugin.containerPickupTracker.pendingHerbSackPickups.add(new CoinFlowPlugin.LootPickup(herbId, 1));
				}
			}
			else if (msg.contains("into your open seed box"))
			{
				int seedId = CoinFlowPlugin.findSeedIdInMessage(msg);
				int qty = CoinFlowPlugin.parseSeedQtyInMessage(msg);
				if (seedId > 0 && qty > 0)
				{
					plugin.containerPickupTracker.pendingSeedBoxPickups.add(new CoinFlowPlugin.LootPickup(seedId, qty));
				}
			}
			else if (msg.contains("You steal") && msg.contains("seed"))
			{
				ItemContainer inv = plugin.client != null ? plugin.client.getItemContainer(InventoryID.INV) : null;
				if (inv != null && plugin.hasOpenSeedBox(inv))
				{
					int seedId = CoinFlowPlugin.findSeedIdInMessage(msg);
					int qty = CoinFlowPlugin.parseSeedQtyInMessage(msg);
					if (seedId > 0 && qty > 0)
					{
						plugin.containerPickupTracker.pendingSeedBoxPickups.add(new CoinFlowPlugin.LootPickup(seedId, qty));
					}
				}
			}
			else if (ChatMessageParser.FISHING_CATCH_REGEX.matcher(msg).find())
			{
				ItemContainer inv = plugin.client != null ? plugin.client.getItemContainer(InventoryID.INV) : null;
				ItemContainer worn = plugin.client != null ? plugin.client.getItemContainer(InventoryID.WORN) : null;
				if (plugin.hasOpenFishBarrel(inv, worn))
				{
					int fishId = CoinFlowPlugin.findRawFishIdInMessage(msg);
					int qty = CoinFlowPlugin.parseFishQtyInMessage(msg);
					if (fishId > 0 && qty > 0)
					{
						plugin.containerPickupTracker.pendingFishBarrelPickups.add(new CoinFlowPlugin.LootPickup(fishId, qty));
					}
				}
			}
			else if (ChatMessageParser.WOODCUTTING_CHOP_REGEX.matcher(msg).find())
			{
				ItemContainer inv = plugin.client != null ? plugin.client.getItemContainer(InventoryID.INV) : null;
				ItemContainer worn = plugin.client != null ? plugin.client.getItemContainer(InventoryID.WORN) : null;
				if (plugin.hasOpenLogBasket(inv, worn))
				{
					int logId = CoinFlowPlugin.findLogIdInMessage(msg);
					int qty = CoinFlowPlugin.parseLogQtyInMessage(msg);
					if (logId > 0 && qty > 0)
					{
						plugin.containerPickupTracker.pendingLogBasketPickups.add(new CoinFlowPlugin.LootPickup(logId, qty));
					}
				}
			}
			else if (msg.contains("You add the gem") || msg.contains("to your gem bag")
				|| (msg.contains("gem") && (msg.contains("to your bag") || msg.contains("into your bag")))
				|| msg.contains("to your gem sack") || msg.contains("to your gem pouch")
				|| msg.contains("to your gem satchel") || msg.contains("to your gem tote")
				|| msg.contains("into your herb sack") || msg.contains("to your herb sack")
				|| msg.contains("into your seed box") || msg.contains("to your seed box")
				|| msg.contains("The fish barrel is now full") || msg.contains("The seed box is full")
				|| msg.contains("The herb sack is full")
				|| msg.contains("The basket is full")
				|| msg.contains("into the Forestry basket") || msg.contains("into the log basket")
				|| msg.contains("into your Forestry basket") || msg.contains("into your log basket")
				|| msg.contains("to your Forestry basket") || msg.contains("to your log basket")
				|| msg.contains("You empty your basket") || msg.contains("You empty as many logs as you can carry"))
			{
				plugin.interfaceTracker.setNeedsRebaseline(true);
				plugin.rebaselineGraceTicks = Math.max(plugin.rebaselineGraceTicks, 2);
			}
			else
			{
				int gemId = CoinFlowPlugin.findUncutGemIdInMessage(msg);
				if (gemId > 0 && (msg.contains("find") || msg.contains("found") || msg.contains("mine")
					|| msg.contains("steal") || msg.contains("stole") || msg.contains("manage to")))
				{
					plugin.lastSkillingGemId = gemId;
					plugin.lastSkillingGemTick = plugin.client != null ? plugin.client.getTickCount() : 0;
				}
			}
		}
	}
}

package com.coinflow;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Parses English chat messages into item ids and quantities for loot that
 * enters closed containers (gem bags, herb sacks, fish barrels, seed boxes,
 * log baskets) without an inventory diff. Pure functions — no game state.
 */
final class ChatMessageParser
{
	private ChatMessageParser() {}

	static final Pattern FISHING_CATCH_REGEX = Pattern.compile(
		"(?:You catch (?:a|an|some|\\d+)\\s+|Your cormorant returns with its catch|You catch .*Karambwanji)",
		Pattern.CASE_INSENSITIVE
	);
	static final Pattern HERBIBOAR_HERB_SACK_PATTERN = Pattern.compile(
		".+(Grimy .+?) herb.+",
		Pattern.CASE_INSENSITIVE
	);
	static final Pattern WOODCUTTING_CHOP_REGEX = Pattern.compile(
		"^(?:You get (?:a|an|some|\\d+)\\s+|You cut (?:a|an|some|\\d+)\\s+).*(?:logs?|bark)",
		Pattern.CASE_INSENSITIVE
	);
	// "Death charges you 8,915 coins." — the authoritative reclaim-fee signal;
	// bank/coffer payments and reclaim-to-bank items are invisible to diffs.
	static final Pattern DEATH_FEE_MESSAGE = Pattern.compile(
		"Death charges you ([\\d,]+) coins"
	);
	// "You successfully retrieved everything from your gravestone." — a
	// direct gravestone claim opens no retrieval interface and fires no
	// ground Take click; the message is the only signal that the arriving
	// items are death recovery rather than loot.
	static final Pattern GRAVE_RETRIEVAL_MESSAGE = Pattern.compile(
		"retriev\\w+ .*your gravestone",
		Pattern.CASE_INSENSITIVE
	);

	static int findUncutGemIdInMessage(String msg)
	{
		String lower = msg.toLowerCase(Locale.ROOT);
		if (!lower.contains("uncut") && !lower.contains("gem"))
		{
			return -1;
		}
		if (lower.contains("dragonstone"))
		{
			return ItemID.UNCUT_DRAGONSTONE;
		}
		if (lower.contains("diamond"))
		{
			return ItemID.UNCUT_DIAMOND;
		}
		if (lower.contains("ruby"))
		{
			return ItemID.UNCUT_RUBY;
		}
		if (lower.contains("emerald"))
		{
			return ItemID.UNCUT_EMERALD;
		}
		if (lower.contains("sapphire"))
		{
			return ItemID.UNCUT_SAPPHIRE;
		}
		if (lower.contains("topaz"))
		{
			return ItemID.UNCUT_RED_TOPAZ;
		}
		if (lower.contains("jade"))
		{
			return ItemID.UNCUT_JADE;
		}
		if (lower.contains("opal"))
		{
			return ItemID.UNCUT_OPAL;
		}
		return -1;
	}

	static int findGrimyHerbIdInMessage(String msg)
	{
		String lower = msg.toLowerCase(Locale.ROOT);
		if (!lower.contains("grimy") && !lower.contains("herb"))
		{
			return -1;
		}
		if (lower.contains("torstol"))
		{
			return ItemID.UNIDENTIFIED_TORSTOL;
		}
		if (lower.contains("dwarf weed"))
		{
			return ItemID.UNIDENTIFIED_DWARF_WEED;
		}
		if (lower.contains("lantadyme"))
		{
			return ItemID.UNIDENTIFIED_LANTADYME;
		}
		if (lower.contains("cadantine"))
		{
			return ItemID.UNIDENTIFIED_CADANTINE;
		}
		if (lower.contains("snapdragon"))
		{
			return ItemID.UNIDENTIFIED_SNAPDRAGON;
		}
		if (lower.contains("kwuarm"))
		{
			return ItemID.UNIDENTIFIED_KWUARM;
		}
		if (lower.contains("avantoe"))
		{
			return ItemID.UNIDENTIFIED_AVANTOE;
		}
		if (lower.contains("irit"))
		{
			return ItemID.UNIDENTIFIED_IRIT;
		}
		if (lower.contains("toadflax"))
		{
			return ItemID.UNIDENTIFIED_TOADFLAX;
		}
		if (lower.contains("ranarr"))
		{
			return ItemID.UNIDENTIFIED_RANARR;
		}
		if (lower.contains("harralander"))
		{
			return ItemID.UNIDENTIFIED_HARRALANDER;
		}
		if (lower.contains("tarromin"))
		{
			return ItemID.UNIDENTIFIED_TARROMIN;
		}
		if (lower.contains("marrentill"))
		{
			return ItemID.UNIDENTIFIED_MARENTILL;
		}
		if (lower.contains("guam"))
		{
			return ItemID.UNIDENTIFIED_GUAM;
		}
		return -1;
	}

	static int findRawFishIdInMessage(String msg)
	{
		String lower = msg.toLowerCase(Locale.ROOT);
		if (lower.contains("karambwanji"))
		{
			return ItemID.TBWT_RAW_KARAMBWANJI;
		}
		if (lower.contains("karambwan"))
		{
			return ItemID.TBWT_RAW_KARAMBWAN;
		}
		if (lower.contains("anglerfish"))
		{
			return ItemID.RAW_ANGLERFISH;
		}
		if (lower.contains("dark crab"))
		{
			return ItemID.RAW_DARK_CRAB;
		}
		if (lower.contains("monkfish"))
		{
			return ItemID.RAW_MONKFISH;
		}
		if (lower.contains("shark"))
		{
			return ItemID.RAW_SHARK;
		}
		if (lower.contains("swordfish"))
		{
