	// ── Goal Calculations ────────────────────────────────────────────────

	/**
	 * Parses user GP input with shorthand multipliers ('k', 'm', 'b').
	 * Hardened against special characters, invalid formats, negative numbers, and overflow.
	 */
	public static long parseGpText(String text) throws NumberFormatException
	{
		if (text == null)
		{
			throw new NumberFormatException("Input cannot be empty");
		}
		String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			throw new NumberFormatException("Input cannot be empty");
		}
		if (!GP_PATTERN.matcher(trimmed).matches())
		{
			throw new NumberFormatException("Special characters and invalid formats are not accepted. Use numbers with optional shorthand (e.g. 10m, 500k, 2.5m, 1,000,000).");
		}

		String clean = trimmed.toLowerCase().replace(",", "").replace(" ", "");

		double multiplier = 1.0;
		if (clean.endsWith("k"))
		{
			multiplier = 1_000.0;
			clean = clean.substring(0, clean.length() - 1);
		}
		else if (clean.endsWith("m"))
		{
			multiplier = 1_000_000.0;
			clean = clean.substring(0, clean.length() - 1);
		}
		else if (clean.endsWith("b"))
		{
			multiplier = 1_000_000_000.0;
			clean = clean.substring(0, clean.length() - 1);
		}

		double parsed;
		try
		{
			parsed = Double.parseDouble(clean);
		}
		catch (NumberFormatException e)
		{
			throw new NumberFormatException("Invalid numeric amount");
		}

		if (Double.isNaN(parsed) || Double.isInfinite(parsed))
		{
			throw new NumberFormatException("Invalid numeric amount");
		}

		double total = parsed * multiplier;
		if (total <= 0)
		{
			throw new NumberFormatException("Amount must be greater than zero");
		}
		if (total > MAX_ALLOWED_GP)
		{
			throw new NumberFormatException("Amount cannot exceed 2,000,000,000,000 gp");
		}

		return (long) total;
	}

	/**
	 * Sanitizes a goal label by stripping special characters, HTML tags, and clamping length.
	 * Allows standard alphanumeric characters, spaces, and safe punctuation used in RuneScape item names.
	 */
	public static String cleanGoalName(String text)
	{
		if (text == null)
		{
			return "";
		}
		// Strip all special characters not allowed in item names
		String clean = DISALLOWED_NAME_CHARS.matcher(text).replaceAll("");
		// Collapse multiple spaces into a single space and trim
		clean = clean.replaceAll("\\s+", " ").trim();
		// Clamp length to max 32 characters
		if (clean.length() > 32)
		{
			clean = clean.substring(0, 32).trim();
		}
		return clean;
	}

	/**
	 * Safely parses the goalAmount config string into a long.
	 * Returns 0 if empty, invalid, or zero.
	 */
	public static long parseGoalAmount(String goalStr)
	{
		if (goalStr == null || goalStr.trim().isEmpty())
		{
			return 0L;
		}
		try
		{
			return parseGpText(goalStr);
		}
		catch (Exception e)
		{
			return 0L;
		}
	}

	/**
	 * Returns the remaining GP to reach the target goal.
	 * Returns 0 if goal is achieved or no goal is set.
	 */
	public long getGoalRemaining(long goalAmount)
	{
		return getGoalRemaining(goalAmount, true);
	}

	/**
	 * Returns the remaining GP to reach the target goal based on net or gross tracking.
	 *
	 * @param goalAmount the target GP amount
	 * @param trackSpent whether to evaluate against net profit (true) or gross profit (false)
	 * @return remaining GP to target, or 0 if reached
	 */
	public long getGoalRemaining(long goalAmount, boolean trackSpent)
	{
		if (goalAmount <= 0)
		{
			return 0L;
		}
		long current = Math.max(0L, trackSpent ? totalProfit : grossProfit);
		return Math.max(0L, goalAmount - current);
	}

	/**
	 * Returns the goal completion progress as a ratio between 0.0 and 1.0.
	 */
	public double getGoalProgress(long goalAmount)
	{
		return getGoalProgress(goalAmount, true);
	}

	/**
	 * Returns the goal completion progress as a ratio between 0.0 and 1.0 based on net or gross tracking.
	 *
	 * @param goalAmount the target GP amount
	 * @param trackSpent whether to evaluate against net profit (true) or gross profit (false)
	 * @return progress ratio between 0.0 and 1.0
	 */
	public double getGoalProgress(long goalAmount, boolean trackSpent)
	{
		if (goalAmount <= 0)
		{
			return 0.0;
		}
		long current = Math.max(0L, trackSpent ? totalProfit : grossProfit);
		return Math.min(1.0, (double) current / goalAmount);
	}

	/**
	 * Returns the estimated seconds remaining until the goal is reached,
	 * or -1 if the ETA cannot be calculated (e.g. paused, zero GP/hr, or warming up).
	 * Returns 0 if the goal has already been achieved.
	 *
	 * @param goalAmount the target GP amount
	 * @param includeAfkTime whether to compute using AFK time
	 * @return estimated seconds remaining, 0 if achieved, or -1 if calculating/paused
	 */
	public long getGoalEtaSeconds(long goalAmount, boolean includeAfkTime)
	{
		return getGoalEtaSeconds(goalAmount, includeAfkTime, true);
	}

	/**
	 * Returns the estimated seconds remaining until the goal is reached,
	 * or -1 if the ETA cannot be calculated (e.g. paused, zero GP/hr, or warming up).
	 *
	 * @param goalAmount the target GP amount
	 * @param includeAfkTime whether to compute using AFK time
	 * @param trackSpent whether to evaluate against net profit and net GP/hr or gross tracking
	 * @return estimated seconds remaining, 0 if achieved, or -1 if calculating/paused
	 */
	public long getGoalEtaSeconds(long goalAmount, boolean includeAfkTime, boolean trackSpent)
	{
		if (goalAmount <= 0)
		{
			return -1;
		}

		long remaining = getGoalRemaining(goalAmount, trackSpent);
		if (remaining <= 0)
		{
			return 0; // Goal reached
		}

		Duration time = includeAfkTime ? totalInGameTime : activeTime;
		// Require at least 10 seconds of tracking before showing ETA to prevent wild single-drop spikes
		if (time.getSeconds() < 10)
		{
			return -1; // Warmup
		}

		long gpHr = trackSpent ? getGpPerHour(includeAfkTime) : getGrossGpPerHour(includeAfkTime);
		if (gpHr <= 0)
		{
			return -1; // Paused or no positive rate
		}

		return (remaining * 3600L) / gpHr;
	}

	/**
	 * Formats ETA seconds into a concise human-readable string.
	 * Examples: "Goal Reached!", "2h 15m", "45m", "< 1m", "> 99h", or "--:--".
	 */
	public static String formatGoalEta(long etaSeconds)
	{
		if (etaSeconds == 0)
		{
			return "Goal Reached!";
		}
		if (etaSeconds < 0)
		{
			return "--:--";
		}
		if (etaSeconds < 60)
		{
			return "< 1m";
		}

		long hours = etaSeconds / 3600;
		long minutes = (etaSeconds % 3600) / 60;

		if (hours > 99)
		{
			return "> 99h";
		}
		if (hours > 0)
		{
			return String.format("%dh %02dm", hours, minutes);
		}
		return String.format("%dm", minutes);
	}
}

package com.coinflow;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/**
 * Registry and classifier for consumable supplies (potions, food, runes, ammo, and teleports).
 * Used when "Track Supply Costs" is enabled to ensure only genuine consumable expenses
 * are deducted from net profit, while dropped resources, unequipped gear, or empty vials
 * are never falsely charged as expenses.
 */
public final class ConsumableRegistry
{
	private ConsumableRegistry() {}

	/**
	 * Suffixes used on fractional expense rows — "Prayer potion (dose)" is the
	 * expense side of "Prayer potion(4)". Stripped when adding to the
	 * ignored-items list so ignoring a dose/portion row ignores the underlying
	 * item, and matched in {@link #isIgnoredName} so ignoring the base item
	 * covers those rows.
	 */
	private static final String[] FRACTIONAL_SUFFIXES = {" (dose)", " (portion)"};

	/**
	 * Returns the item name used for the ignored-items filter: fractional
	 * expense rows like "Prayer potion (dose)" and "Summer pie (portion)"
	 * normalize to their base item name.
	 */
	public static String canonicalIgnoreName(String itemName)
	{
		if (itemName == null)
		{
			return "";
		}
		String name = itemName.trim();
		String lower = name.toLowerCase(Locale.ROOT);
		for (String suffix : FRACTIONAL_SUFFIXES)
		{
			if (lower.endsWith(suffix))
			{
				return name.substring(0, name.length() - suffix.length()).trim();
			}
		}
		return name;
	}

	/**
	 * Checks whether {@code itemName} is covered by the ignored-items set:
	 * matches the name directly, the base name of a fractional expense row
	 * (" (dose)" / " (portion)" suffixes), or a potion's base name (so
	 * ignoring "Prayer potion" covers "Prayer potion(1)"-"(4)" and vice versa).
	 * {@code ignoredItemNames} must contain lowercase names.
	 */
	public static boolean isIgnoredName(String itemName, Set<String> ignoredItemNames)
	{
		if (ignoredItemNames == null || ignoredItemNames.isEmpty() || itemName == null)
		{
			return false;
		}
		String lower = itemName.toLowerCase(Locale.ROOT);
		if (ignoredItemNames.contains(lower))
		{
			return true;
		}
		String stripped = canonicalIgnoreName(itemName).toLowerCase(Locale.ROOT);
		if (!stripped.equals(lower) && ignoredItemNames.contains(stripped))
		{
			return true;
		}
		PotionDose potion = parsePotion(itemName);
		return potion != null && ignoredItemNames.contains(potion.getBaseName().toLowerCase(Locale.ROOT));
	}

	// Matches potion names like "Stamina potion(4)", "Prayer potion (3)", "Saradomin brew(1)"
	private static final Pattern POTION_PATTERN = Pattern.compile("^(.*?)\\s*\\((\\d)\\)$");

	private static final Set<String> NON_POTION_KEYWORDS = new HashSet<>(Arrays.asList(
		"amulet", "ring", "necklace", "bracelet", "pendant", "sceptre",
		"crystal", "device", "waterskin", "bellows", "lockpick", "quiver",
		"compass", "chronicle", "pouch", "horn"
	));

	// Drinkables that persist after use and are never consumed (e.g. Waterskin(4) -> Waterskin(0))
	private static final Set<String> NON_CONSUMABLE_DRINKABLE_KEYWORDS = new HashSet<>(Collections.singletonList(
		"waterskin"
	));

	public static final class PotionDose
	{
		private final String baseName;
		private final int dose;

		public PotionDose(String baseName, int dose)
		{
			this.baseName = baseName.trim();
			this.dose = dose;
		}

		public String getBaseName()
		{
			return baseName;
		}

		public int getDose()
		{
			return dose;
		}
	}

	/**
	 * Parses a potion name into its base name and dose count.
	 * Returns null if the item name does not match a dose pattern.
	 */
	public static PotionDose parsePotion(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return null;
		}

		Matcher m = POTION_PATTERN.matcher(itemName);
		if (m.matches())
		{
			String base = m.group(1).trim();
			String lower = base.toLowerCase(Locale.ROOT);
			if (containsKeyword(lower, NON_POTION_KEYWORDS))
			{
				return null;
			}

			try
			{
				int dose = Integer.parseInt(m.group(2));
				if (dose >= 1 && dose <= 4)
				{
					return new PotionDose(base, dose);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Not a valid dose number
			}
		}

		return null;
	}

	private static final Set<String> BYPRODUCTS = new HashSet<>();
	static
	{
		BYPRODUCTS.add("vial");
		BYPRODUCTS.add("empty vial");
		BYPRODUCTS.add("pie dish");
		BYPRODUCTS.add("empty pie dish");
		BYPRODUCTS.add("bowl");
		BYPRODUCTS.add("empty bowl");
		BYPRODUCTS.add("cup");
		BYPRODUCTS.add("empty cup");
		BYPRODUCTS.add("pot");
		BYPRODUCTS.add("empty pot");
		BYPRODUCTS.add("beer glass");
		BYPRODUCTS.add("jug");
		BYPRODUCTS.add("empty jug");
		BYPRODUCTS.add("bucket");
		BYPRODUCTS.add("empty bucket");
		BYPRODUCTS.add("plant pot");
		BYPRODUCTS.add("empty plant pot");
		BYPRODUCTS.add("cocktail glass");
	}

	private static final Set<String> NON_CONSUMABLE_TELEPORT_SCROLLS = new HashSet<>();
	static
	{
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("teleport anchoring scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("twisted teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("trailblazer teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("trailblazer reloaded home teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("shattered teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("speedy teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("echo home teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("armageddon teleport scroll");
		NON_CONSUMABLE_TELEPORT_SCROLLS.add("annihilation teleport scroll");
	}

	// Charged teleport jewelry that crumbles to dust when its last charge is used
	// (e.g. "Ring of dueling(1)" -> nothing). These can be rubbed worn or from the
	// inventory. Jewelry that depletes to an uncharged variant instead (glory,
	// ring of wealth, combat bracelet, skills necklace, pharaoh's sceptre) is
	// excluded on purpose — those transitions are handled as degradation pairs.
	private static final Set<String> LAST_CHARGE_TELEPORT_BASES = new HashSet<>(Arrays.asList(
		"ring of dueling",
		"games necklace",
		"slayer ring",
		"necklace of passage",
		"burning amulet",
		"digsite pendant",
		"ring of returning"
	));

	// Charged worn items that crumble at (1) but are not teleport jewelry.
	private static final Set<String> LAST_CHARGE_WORN_BASES = new HashSet<>(Collections.singletonList(
		"castle wars bracelet"
	));

	// Single-life worn jewelry with no charge count in the item name — it simply
	// disappears from the equipment slot when consumed (e.g. Ring of recoil when
	// its 40 recoil hits are spent, Ring of life when it saves the wearer).
	private static final Set<String> CRUMBLING_WORN_JEWELRY = new HashSet<>(Arrays.asList(
		"ring of recoil",
		"ring of life",
		"binding necklace",
		"dodgy necklace",
		"bracelet of slaughter",
		"expeditious bracelet",
		"ring of forging",
		"bracelet of clay",
		"amulet of chemistry"
	));

	/**
	 * Returns true if the item name represents a zero-value byproduct container
	 * left over after consuming food or drink.
	 */
	public static boolean isByproduct(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		return BYPRODUCTS.contains(itemName.trim().toLowerCase(Locale.ROOT));
	}

	/**
	 * Returns true if gainedName represents a remaining portion of lostName (e.g. eating half a pie).
	 */
	public static boolean isFoodPortion(String gainedName, String lostName)
	{
		if (gainedName == null || lostName == null)
		{
			return false;
		}

		String g = gainedName.trim().toLowerCase(Locale.ROOT);
		String l = lostName.trim().toLowerCase(Locale.ROOT);

		// Pies: e.g. "summer pie" -> "half a summer pie" / "half an apple pie"
		if (g.startsWith("half a ") && g.substring(7).equals(l))
		{
			return true;
		}
		if (g.startsWith("half an ") && g.substring(8).equals(l))
		{
			return true;
		}

		// Pizzas: e.g. "plain pizza" -> "1/2 plain pizza"
		if (g.startsWith("1/2 ") && g.substring(4).equals(l))
		{
			return true;
		}

		// Cakes: e.g. "cake" -> "2/3 cake" -> "slice of cake"
		// or "chocolate cake" -> "2/3 chocolate cake" -> "chocolate slice"
		if (l.endsWith("cake"))
		{
			String prefix = l.substring(0, l.length() - 4).trim();
			if (prefix.startsWith("2/3"))
			{
				prefix = prefix.substring(3).trim();
			}
			if (g.equals(prefix.isEmpty() ? "2/3 cake" : "2/3 " + prefix + " cake"))
			{
				return true;
			}
			if (g.equals(prefix.isEmpty() ? "slice of cake" : prefix + " slice") || g.equals("slice of cake"))
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Returns true if rawFoodName represents the raw ingredient used to cook
	 * cookedOrBurntFoodName (e.g. "Raw manta ray" -> "Manta ray" or "Burnt manta ray").
	 */
	public static boolean isCookingPair(String rawFoodName, String cookedOrBurntFoodName)
	{
		if (rawFoodName == null || cookedOrBurntFoodName == null)
		{
			return false;
		}

		String raw = rawFoodName.trim().toLowerCase(Locale.ROOT);
		String cooked = cookedOrBurntFoodName.trim().toLowerCase(Locale.ROOT);

		// Special case: "potato" -> "baked potato" or "burnt potato"
		if (raw.equals("potato"))
		{
			return cooked.equals("baked potato") || cooked.equals("burnt potato");
		}

		// Most raw food items in OSRS start with "raw " or "uncooked "
		String base;
		if (raw.startsWith("raw "))
		{
			base = raw.substring(4).trim();
		}
		else if (raw.startsWith("uncooked "))
		{
			base = raw.substring(9).trim();
		}
		else
		{
			return false;
		}

		if (base.isEmpty())
		{
			return false;
		}

		// Direct name match: "Raw manta ray" -> "Manta ray", "Uncooked summer pie" -> "Summer pie"
		if (cooked.equals(base))
		{
			return true;
		}

		// Cooked prefix match: "Raw karambwan" -> "Cooked karambwan", "Raw chicken" -> "Cooked chicken", "Raw sweetcorn" -> "Cooked sweetcorn"
		if (cooked.equals("cooked " + base))
		{
			return true;
		}

		// Burnt prefix match: "Raw manta ray" -> "Burnt manta ray", "Raw shark" -> "Burnt shark"
		if (cooked.equals("burnt " + base))
		{
			return true;
		}

		// Generic burnt food: in OSRS many fish burn to "Burnt fish", meats burn to "Burnt meat", pies to "Burnt pie"
		if (cooked.equals("burnt fish") || cooked.equals("burnt meat") || (base.endsWith("pie") && cooked.equals("burnt pie"))
			|| (base.equals("pizza") && cooked.equals("burnt pizza")))
		{
			return true;
		}

		// Uncooked pizza cooks into plain pizza
		if (base.equals("pizza") && cooked.equals("plain pizza"))
		{
			return true;
		}

		// Karambwan poison variation: "Raw karambwan" -> "Poison karambwan"
		if (base.equals("karambwan") && cooked.equals("poison karambwan"))
		{
			return true;
		}

		// Meats: "Raw beef", "Raw bear meat", "Raw rat meat", "Raw yak meat" -> "Cooked meat"
		if (cooked.equals("cooked meat") && (base.contains("meat") || base.equals("beef")))
		{
			return true;
		}

		return false;
	}

	private static boolean containsKeyword(String lower, Set<String> keywords)
	{
		for (String keyword : keywords)
		{
			if (lower.contains(keyword))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Determines whether the item is a consumable supply (potion, food, rune, ammo, teleport).
	 * Food and drink are detected via the item's "Eat"/"Drink" inventory actions
	 * (from its {@link ItemComposition}); potions, runes, ammo, and teleports are
	 * detected by name patterns and also apply when the composition is unavailable.
	 */
	public static boolean isConsumable(int itemId, String itemName, ItemManager itemManager)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}

		String lower = itemName.trim().toLowerCase(Locale.ROOT);

		// Raw items, seeds, ores, bars, logs are never consumable supplies
		if (lower.startsWith("raw ") || lower.endsWith(" ore") || lower.endsWith(" logs")
			|| lower.endsWith(" log") || lower.endsWith(" bar") || lower.endsWith(" seed")
			|| lower.endsWith(" hide") || lower.endsWith(" leather"))
		{
			return false;
		}

		// Empty containers or currency
		if (lower.equals("vial") || lower.equals("empty vial") || lower.equals("vial of water")
			|| lower.equals("jug") || lower.equals("empty cup") || lower.equals("bowl")
			|| lower.equals("coins") || lower.equals("platinum token"))
		{
			return false;
		}

		// 1. Inventory actions: anything with an Eat or Drink option is a consumable supply,
		// except durable drinkables that persist after use (e.g. waterskins)
		if (itemManager != null)
		{
			ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp != null && comp.getInventoryActions() != null)
			{
				for (String action : comp.getInventoryActions())
				{
					if ("Eat".equalsIgnoreCase(action)
						|| ("Drink".equalsIgnoreCase(action) && !containsKeyword(lower, NON_CONSUMABLE_DRINKABLE_KEYWORDS)))
					{
						return true;
					}
				}
			}
		}

		// 2. Potions (e.g. Stamina potion(4))
		if (parsePotion(itemName) != null)
		{
			return true;
		}

		// 3. Runes (excluding essence)
		if (lower.endsWith(" rune") && !lower.contains("essence"))
		{
			return true;
		}

		// 4. Ammunition (arrows, bolts, darts, knives, thrownaxes, chinchompas, javelins, cannonballs)
		if (isAmmo(itemName))
		{
			return true;
		}

		// 5. Teleports (tablets and scrolls)
		if (lower.contains("teleport") || lower.endsWith(" tab") || lower.endsWith(" tabs")
			|| lower.endsWith("basalt") && !lower.equals("basalt"))
		{
			if (NON_CONSUMABLE_TELEPORT_SCROLLS.contains(lower)
				|| lower.contains("home teleport")
				|| lower.contains("anchoring")
				|| lower.contains("crystal")
				|| lower.contains("eternal")
				|| lower.contains("book")
				|| lower.contains("charm")
				|| lower.contains("card")
				|| lower.contains("trap")
				|| lower.contains("focus")
				|| lower.contains("teleporter"))
			{
				return false;
			}
			return true;
		}

		return false;
	}

	/**
	 * Returns true if the item is a last-charge variant of crumble-type teleport
	 * jewelry (e.g. "Ring of dueling(1)", "Games necklace(1)"). These crumble to
	 * dust whether rubbed from the equipment slot or the inventory.
	 *
	 * Uses POTION_PATTERN directly rather than {@link #parsePotion}: jewelry base
	 * names are deliberately excluded from potion parsing by NON_POTION_KEYWORDS.
	 */
	public static boolean isLastChargeTeleportJewelry(String itemName)
	{
		return isLastChargeVariant(itemName, LAST_CHARGE_TELEPORT_BASES);
	}

	/**
	 * Returns true if a worn item disappearing from the equipment slot means it
	 * was consumed (crumbled to dust) rather than unequipped. Covers last-charge
	 * teleport jewelry plus single-life charged jewelry with no charge count in
	 * the item name (e.g. Ring of recoil, Dodgy necklace).
	 */
	public static boolean isCrumblingJewelry(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		if (CRUMBLING_WORN_JEWELRY.contains(itemName.trim().toLowerCase(Locale.ROOT)))
		{
			return true;
		}
		return isLastChargeTeleportJewelry(itemName)
			|| isLastChargeVariant(itemName, LAST_CHARGE_WORN_BASES);
	}

	private static boolean isLastChargeVariant(String itemName, Set<String> bases)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		Matcher m = POTION_PATTERN.matcher(itemName.trim());
		if (!m.matches() || !"1".equals(m.group(2)))
		{
			return false;
		}
		return bases.contains(m.group(1).trim().toLowerCase(Locale.ROOT));
	}

	/**
	 * Determines whether the item is ammunition or a thrown weapon.
	 */
	public static boolean isAmmo(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}

		String lower = itemName.trim().toLowerCase(Locale.ROOT);

		return lower.endsWith(" arrow") || lower.endsWith(" arrows") || lower.contains("arrow(")
			|| lower.endsWith(" bolt") || lower.endsWith(" bolts") || lower.contains("bolts (") || lower.contains("bolts(")
			|| lower.endsWith(" dart") || lower.endsWith(" darts") || lower.contains("dart(")
			|| lower.endsWith(" knife") || lower.endsWith(" knives") || lower.contains("knife(")
			|| lower.endsWith(" thrownaxe") || lower.endsWith(" thrownaxes") || lower.contains("thrownaxe(")
			|| lower.endsWith(" javelin") || lower.endsWith(" javelins") || lower.contains("javelin(")
			|| lower.contains("chinchompa")
			// "Cannonball" is the legacy name — since Sailing the dwarf-cannon
			// ball is "Steel cannonball" and ship cannons fire bronze–dragon,
			// chainshot and incendiary cannonballs.
			|| lower.equals("cannonball") || lower.endsWith(" cannonball")
			|| lower.contains("sunfire splinter");
	}

	/**
	 * Returns true if the item name represents a farming seed.
	 */
	public static boolean isSeed(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		String lower = itemName.trim().toLowerCase(Locale.ROOT);
		return lower.endsWith(" seed") || lower.endsWith(" seeds")
			|| lower.endsWith(" spore") || lower.endsWith(" spores")
			|| lower.equals("gout tuber");
	}

	/**
	 * Returns true if the lost item represents a skilling sink corresponding to an active skill
	 * that just gained XP or performed an action on this tick (e.g. Prayer bones/ashes,
	 * Firemaking logs, Farming seeds/saplings/compost, Construction planks/nails).
	 */
	public static boolean isSkillSink(Set<Skill> activeSkills, String itemName)
	{
		if (activeSkills == null || activeSkills.isEmpty() || itemName == null || itemName.isEmpty())
		{
			return false;
		}

		String lower = itemName.trim().toLowerCase(Locale.ROOT);

		if (activeSkills.contains(Skill.FIREMAKING))
		{
			if (isLog(lower))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.PRAYER) || activeSkills.contains(Skill.MAGIC))
		{
			if (lower.startsWith("ensouled "))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.PRAYER))
		{
			if (lower.equals("bones") || lower.endsWith(" bones")
				|| lower.equals("ashes") || lower.endsWith(" ashes"))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.FARMING))
		{
			if (isSeed(itemName) || lower.endsWith(" sapling") || lower.endsWith(" seedling")
				|| lower.equals("compost") || lower.equals("supercompost") || lower.equals("ultracompost")
				|| lower.equals("plant cure"))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.CONSTRUCTION))
		{
			if (lower.equals("plank") || lower.equals("planks")
				|| lower.endsWith(" plank") || lower.endsWith(" planks")
				|| lower.endsWith(" nails")
				|| lower.equals("marble block")
				|| lower.equals("gold leaf")
				|| lower.equals("magic stone")
				|| lower.equals("limestone brick")
				|| lower.equals("bolt of cloth")
				|| lower.equals("clockwork")
				|| lower.equals("steel bar")
				|| lower.startsWith("bagged "))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.RUNECRAFT))
		{
			if (lower.equals("pure essence") || lower.equals("daeyalt essence")
				|| lower.equals("rune essence") || lower.equals("binding necklace"))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.HERBLORE))
		{
			// Herbs fed into the Mastering Mixology refiner (or otherwise
			// consumed for XP) leave only an untradeable paste behind, which
			// stripNonEconomicItems removes — so the loss arrives one-sided.
			if (isHerbName(lower))
			{
				return true;
			}
		}

		if (activeSkills.contains(Skill.HUNTER))
		{
			if (isLog(lower) || isSeed(itemName)
				|| lower.equals("raw beef") || lower.equals("raw chicken")
				|| lower.equals("raw beast meat") || lower.equals("raw rat meat")
				|| lower.equals("fishing bait"))
			{
				return true;
			}
		}

		return false;
	}

	public static boolean isLog(String rawName)
	{
		if (rawName == null)
		{
			return false;
		}
		String lower = rawName.trim().toLowerCase(Locale.ROOT);
		if (lower.contains("collection log") || lower.contains("captain's log") || lower.contains("clue"))
		{
			return false;
		}
		return lower.equals("logs")
			|| lower.endsWith(" logs")
			|| lower.endsWith(" log")
			|| lower.contains("pyre logs")
			|| lower.equals("kindling");
	}

	private static final Set<String> HERB_NAMES = new HashSet<>(Arrays.asList(
		"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed",
		"toadflax", "irit leaf", "avantoe", "kwuarm", "snapdragon",
		"cadantine", "lantadyme", "dwarf weed", "torstol", "huasca",
		"snake weed", "rogue's purse", "ardrigal", "sito foil", "volencia moss"));

	private static boolean isHerbName(String lowerName)
	{
		if (HERB_NAMES.contains(lowerName))
		{
			return true;
		}
		return lowerName.startsWith("grimy ")
			&& HERB_NAMES.contains(lowerName.substring("grimy ".length()));
	}
}

package com.coinflow;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Ground-pickup bookkeeping for items routed into open secondary containers
 * (looting bag, gem bag, herb sack, fish barrel, seed box, log basket) where
 * the pickup produces no inventory diff: Take clicks are matched to tile
 * despawns, pending pickups are finalized on the next game tick against the
 * items that did reach inventory, and PvP loot-key chests are diffed for
 * gains on open.
 */
@Slf4j
final class ContainerPickupTracker
{
	private final CoinFlowPlugin plugin;

	private static final class TakeClick
	{
		final int itemId;
		final WorldPoint point;
		final int tick;

		TakeClick(int itemId, WorldPoint point, int tick)
		{
			this.itemId = itemId;
			this.point = point;
			this.tick = tick;
		}
	}

	final List<TakeClick> recentTakeClicks = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingLootingBagPickups = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingGemBagPickups = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingHerbSackPickups = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingFishBarrelPickups = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingSeedBoxPickups = new ArrayList<>();
	final List<CoinFlowPlugin.LootPickup> pendingLogBasketPickups = new ArrayList<>();
	final Map<Integer, Map<Integer, Integer>> previousPvpKeyContainers = new HashMap<>();

	private static final int[] PVP_LOOT_KEY_CONTAINERS = {
		InventoryID.DEADMAN_LOOT_INV0,
		InventoryID.DEADMAN_LOOT_INV1,
		InventoryID.DEADMAN_LOOT_INV2,
		InventoryID.DEADMAN_LOOT_INV3,
		InventoryID.DEADMAN_LOOT_INV4
	};

	ContainerPickupTracker(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	static boolean isPvpKeyContainer(int containerId)
	{
		for (int id : PVP_LOOT_KEY_CONTAINERS)
		{
			if (id == containerId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Records a Take menu click at its scene position so a matching despawn
	 * within 5 ticks can be attributed to a secondary-container pickup.
	 */
	void recordTakeClick(int itemId, int sceneX, int sceneY, int tick)
	{
		if (plugin.client != null && plugin.client.getLocalPlayer() != null)
		{
			try
			{
				WorldView worldView = plugin.client.getTopLevelWorldView();
				WorldPoint targetPoint = worldView != null
					? WorldPoint.fromScene(worldView, sceneX, sceneY, worldView.getPlane())
					: null;
				if (targetPoint != null)
				{
					recentTakeClicks.add(new TakeClick(itemId, targetPoint, tick));
				}
			}
			catch (Exception e)
			{
				log.debug("Failed to calculate WorldPoint from scene coords: {}", e.getMessage());
			}
		}
	}

	void ageTakeClicks(int currentTick)
	{
		recentTakeClicks.removeIf(click -> currentTick - click.tick > 5);
	}

	void onItemDespawned(ItemDespawned event)
	{
		if (plugin.client == null || plugin.client.getLocalPlayer() == null)
		{
			return;
		}

		ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
		if (invContainer == null)
		{
			return;
		}

		boolean canLootBag = plugin.hasOpenLootingBag(invContainer)
			&& plugin.client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1;
		boolean canGemBag = plugin.hasOpenGemBag(invContainer);
		boolean canHerbSack = plugin.hasOpenHerbSack(invContainer);
		boolean canSeedBox = plugin.hasOpenSeedBox(invContainer);
		ItemContainer wornContainer = plugin.client.getItemContainer(InventoryID.WORN);
		boolean canLogBasket = plugin.hasOpenLogBasket(invContainer, wornContainer);

		if (!canLootBag && !canGemBag && !canHerbSack && !canSeedBox && !canLogBasket)
		{
			return;
		}

		TileItem tileItem = event.getItem();
		Tile tile = event.getTile();
		if (tileItem == null || tile == null)
		{
			return;
		}

		WorldPoint itemPoint = tile.getWorldLocation();
		WorldPoint playerPoint = plugin.client.getLocalPlayer().getWorldLocation();
		if (playerPoint.distanceTo(itemPoint) > 1)
		{
			return;
		}

		int currentTick = plugin.client.getTickCount();
		TakeClick matchedClick = null;
		for (TakeClick click : recentTakeClicks)
		{
			if (click.itemId == tileItem.getId()
				&& click.point.distanceTo(itemPoint) <= 1
				&& currentTick - click.tick <= 5)
			{
				matchedClick = click;
				break;
			}
		}

		if (matchedClick == null)
		{
			return;
		}

		recentTakeClicks.remove(matchedClick);

		ItemComposition comp = plugin.itemManager != null ? plugin.itemManager.getItemComposition(tileItem.getId()) : null;
		if (comp != null && !comp.isTradeable())
		{
			return;
		}

		if (canGemBag && InventorySnapshotService.isUncutGem(tileItem.getId()))
		{
			pendingGemBagPickups.add(new CoinFlowPlugin.LootPickup(tileItem.getId(), tileItem.getQuantity()));
		}
		else if (canHerbSack && InventorySnapshotService.isGrimyHerb(tileItem.getId()))
		{
			pendingHerbSackPickups.add(new CoinFlowPlugin.LootPickup(tileItem.getId(), tileItem.getQuantity()));
		}
		else if (canSeedBox && comp != null && ConsumableRegistry.isSeed(comp.getName()))
		{
			pendingSeedBoxPickups.add(new CoinFlowPlugin.LootPickup(tileItem.getId(), tileItem.getQuantity()));
		}
		else if (canLogBasket && comp != null && (ConsumableRegistry.isLog(comp.getName()) || tileItem.getId() == ItemID.HOLLOW_BARK))
		{
			pendingLogBasketPickups.add(new CoinFlowPlugin.LootPickup(tileItem.getId(), tileItem.getQuantity()));
		}
		else if (canLootBag)
		{
			pendingLootingBagPickups.add(new CoinFlowPlugin.LootPickup(tileItem.getId(), tileItem.getQuantity()));
		}
	}

	/**
	 * Finalizes pending pickups on the game tick: items that reached a secondary
	 * container without an inventory diff are credited as gains. Returns false
	 * when tracking is uninitialized and the caller should bail out of the tick.
	 */
	boolean finalizePendingPickups()
	{
		if (plugin.session == null || !plugin.snapshotInitialized)
		{
			pendingLootingBagPickups.clear();
			pendingGemBagPickups.clear();
			pendingHerbSackPickups.clear();
			pendingFishBarrelPickups.clear();
			pendingSeedBoxPickups.clear();
			pendingLogBasketPickups.clear();
			plugin.invItemsGainedThisTick.clear();
			return false;
		}

		// Finalize pending looting bag pickups from ground
		if (!pendingLootingBagPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				if (invContainer != null && plugin.hasOpenLootingBag(invContainer))
				{
					boolean added = false;
					for (CoinFlowPlugin.LootPickup pickup : pendingLootingBagPickups)
					{
						int invGained = plugin.invItemsGainedThisTick.getOrDefault(pickup.itemId, 0);
						if (pickup.qty > invGained)
						{
							int containerQty = pickup.qty - invGained;
							plugin.getSnapshotService().addLootingBagPendingItem(pickup.itemId, containerQty);
							plugin.invItemsGainedThisTick.put(pickup.itemId, 0);
							added = true;
						}
						else
						{
							plugin.invItemsGainedThisTick.put(pickup.itemId, invGained - pickup.qty);
						}
					}
					if (added)
					{
						plugin.processInventoryChanges(invContainer);
					}
				}
			}
			pendingLootingBagPickups.clear();
		}

		// Finalize pending gem bag pickups (ground take or skilling into open gem bag)
		if (!pendingGemBagPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				if (invContainer != null && plugin.hasOpenGemBag(invContainer))
				{
					drainPendingContainerPickups(pendingGemBagPickups);
				}
			}
			pendingGemBagPickups.clear();
		}

		// Finalize pending herb sack pickups
		if (!pendingHerbSackPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				if (invContainer != null && plugin.hasOpenHerbSack(invContainer))
				{
					drainPendingContainerPickups(pendingHerbSackPickups);
				}
			}
			pendingHerbSackPickups.clear();
		}

		// Finalize pending fish barrel pickups
		if (!pendingFishBarrelPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				ItemContainer wornContainer = plugin.client.getItemContainer(InventoryID.WORN);
				if (plugin.hasOpenFishBarrel(invContainer, wornContainer))
				{
					drainPendingContainerPickups(pendingFishBarrelPickups);
				}
			}
			pendingFishBarrelPickups.clear();
		}

		// Finalize pending seed box pickups
		if (!pendingSeedBoxPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				if (invContainer != null && plugin.hasOpenSeedBox(invContainer))
				{
					drainPendingContainerPickups(pendingSeedBoxPickups);
				}
			}
			pendingSeedBoxPickups.clear();
		}

		// Finalize pending log basket pickups
		if (!pendingLogBasketPickups.isEmpty())
		{
			if (plugin.client != null)
			{
				ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
				ItemContainer wornContainer = plugin.client.getItemContainer(InventoryID.WORN);
				if (plugin.hasOpenLogBasket(invContainer, wornContainer))
				{
					drainPendingContainerPickups(pendingLogBasketPickups);
				}
			}
			pendingLogBasketPickups.clear();
		}
		plugin.invItemsGainedThisTick.clear();
		return true;
	}

	void checkPvpKeyContainers()
	{
		if (plugin.client == null || plugin.session == null)
		{
			return;
		}

		Map<Integer, Integer> pvpGains = new HashMap<>();
		for (int containerId : PVP_LOOT_KEY_CONTAINERS)
		{
			ItemContainer container = plugin.client.getItemContainer(containerId);
			Map<Integer, Integer> currentItems = new HashMap<>();
			if (container != null && container.getItems() != null)
			{
				for (Item item : container.getItems())
				{
					if (item != null && item.getId() > 0 && item.getQuantity() > 0)
					{
						currentItems.merge(item.getId(), item.getQuantity(), Integer::sum);
					}
				}
			}

			Map<Integer, Integer> prevItems = previousPvpKeyContainers.getOrDefault(containerId, Collections.emptyMap());
			for (Map.Entry<Integer, Integer> entry : currentItems.entrySet())
			{
				int id = entry.getKey();
				int qty = entry.getValue();
				int prevQty = prevItems.getOrDefault(id, 0);
				if (qty > prevQty)
				{
					pvpGains.merge(id, qty - prevQty, Integer::sum);
				}
			}

			previousPvpKeyContainers.put(containerId, currentItems);
		}

		if (!pvpGains.isEmpty())
		{
			log.debug("PvP Loot Chest opened/updated, crediting key loot: {}", pvpGains);
			plugin.processGains(pvpGains);
		}
	}

	/**
	 * Drains pending pickups into container gains, deducting any items already counted in inventory,
	 * applying profit gains, and clearing the pending pickups list.
	 *
	 * @param pickups list of pending item pickups for a secondary container (gem bag, herb sack, etc.)
	 */
	void drainPendingContainerPickups(List<CoinFlowPlugin.LootPickup> pickups)
	{
		if (pickups == null || pickups.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> containerGains = new HashMap<>();
		for (CoinFlowPlugin.LootPickup pickup : pickups)
		{
			int invGained = plugin.invItemsGainedThisTick.getOrDefault(pickup.itemId, 0);
			if (pickup.qty > invGained)
			{
				int containerQty = pickup.qty - invGained;
				containerGains.merge(pickup.itemId, containerQty, Integer::sum);
				plugin.invItemsGainedThisTick.put(pickup.itemId, 0);
			}
			else
			{
				plugin.invItemsGainedThisTick.put(pickup.itemId, invGained - pickup.qty);
			}
		}

		// Death-drop pickups into an open container still count as recovery —
		// this path bypasses the handler chain just like own-drop pickups.
		plugin.matchDeathPickupGains(containerGains);

		// Re-picking up the player's own dropped items into an open bag/box/sack
		// must not count as fresh profit — this path bypasses the handler chain.
		Map<Integer, Long> expenseReversals = new HashMap<>();
		com.coinflow.reconciliation.DroppedItemPickupHandler.applyDropReconciliation(
			containerGains, plugin.recentlyDroppedItems, plugin.recentlyDroppedOwnedItems, plugin.recentlyExpensedDrops,
			expenseReversals, plugin.itemManager);
		plugin.session = plugin.session.withExpenseReversal(expenseReversals);

		if (!containerGains.isEmpty())
		{
			plugin.processGains(containerGains);
		}
		pickups.clear();
	}

	/**
	 * Clears all transient pickup/click buffers and PvP-key baselines.
	 */
	void resetTransient()
	{
		recentTakeClicks.clear();
		pendingLootingBagPickups.clear();
		pendingGemBagPickups.clear();
		pendingHerbSackPickups.clear();
		pendingFishBarrelPickups.clear();
		pendingSeedBoxPickups.clear();
		pendingLogBasketPickups.clear();
		plugin.invItemsGainedThisTick.clear();
		previousPvpKeyContainers.clear();
	}
}

package com.coinflow;

import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.vars.AccountType;
import net.runelite.api.GameState;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.gameval.ItemID;

/**
 * Orchestrates the death flow: captures the pre-death snapshot on
 * {@link ActorDeath}, settles the pending loss once post-respawn containers
 * go quiet, settles reclaim-interface recoveries and deferred chat fees on
 * the game tick, and matches gained items against the recovery ledger.
 */
@Slf4j
final class DeathFlowCoordinator
{
	private final CoinFlowPlugin plugin;

	DeathFlowCoordinator(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onActorDeath(ActorDeath event)
	{
		if (plugin.client != null && event.getActor() == plugin.client.getLocalPlayer()
			// Deaths inside quarantine minigames (PvP tutorial arena, Tempoross,
			// Gauntlet HUD) are staged content — the loaner strip is already
			// suppressed, so booking them would only add noise. The exit-grace
			// windows count too: a death while the strip is still landing would
			// capture loaner items into the loss.
			&& !plugin.isTrackingSuppressed())
		{
			// Capture BEFORE resetTransientTrackingState clears the looting
			// bag/quiver caches — the pre-death state must reflect what was
			// actually carried. Tracking freezes until the death settles.
			if (plugin.session != null)
			{
				plugin.deathTracker.onDeath(plugin.combinedSnapshotItems(), plugin.client.getTickCount());
			}
			plugin.interfaceTracker.onActorDeath();
			plugin.lootingBagInitialized = false;
			plugin.resetTransientTrackingState();
		}
	}

	/**
	 * Per-tick death bookkeeping: reclaim-interface settles, deferred chat
	 * fees, and the pending-death settle heuristic.
	 */
	void onGameTick()
	{
		// Settle reclaim-interface recovery once no retrieval interface remains
		// open (WidgetClosed may be skipped when a scene load clears the
		// suppressed set — e.g. Death's Office teleporting the player out).
		if (plugin.deathTracker.hasRetrievalBaseline() && !plugin.interfaceTracker.isDeathRetrievalOpen())
		{
			applyDeathRecovery(plugin.deathTracker.settleRetrieval(plugin.combinedSnapshotItems(),
				plugin.client != null ? plugin.client.getTickCount() : 0, isIronmanAccount()));
		}

		// A "Death charges you" message can arrive after the reclaim interface
		// already closed and settled — apply an unconsumed chat fee once it has
		// aged past the settle window (skipped while a baseline is live so the
		// fee folds into the pending settle instead of applying twice).
		if (!plugin.deathTracker.hasRetrievalBaseline() && !plugin.interfaceTracker.isDeathRetrievalOpen())
		{
			applyDeathReclaimFee(plugin.deathTracker.consumeDeferredChatFee(plugin.client != null ? plugin.client.getTickCount() : 0));
		}

		// Settle a pending death once post-respawn containers have gone quiet.
		if (plugin.deathTracker.isPending() && plugin.client != null && plugin.client.getGameState() == GameState.LOGGED_IN
			&& plugin.deathTracker.shouldSettle(plugin.client.getTickCount()))
		{
			settlePendingDeath();
		}
	}

	/**
	 * Finalizes a pending death: re-baselines, diffs pre- vs post-death state,
	 * and charges the loss to the aggregated "Death" expense row. Runs on
	 * GameTick once post-respawn containers have gone quiet (or on timeout).
	 */
	void settlePendingDeath()
	{
		// takeBaseline() first: it refreshes the looting bag/quiver caches that
		// resetTransientTrackingState cleared, so the post-death snapshot can't
		// manufacture phantom container losses.
		plugin.takeBaseline();
		Map<Integer, Integer> post = new HashMap<>();
		if (plugin.previousInventorySnapshot != null)
		{
			plugin.previousInventorySnapshot.getItems()
				.forEach((id, qty) -> post.merge(plugin.canonicalize(id), qty, Integer::sum));
		}
		if (plugin.previousEquipmentSnapshot != null)
		{
			plugin.previousEquipmentSnapshot.getItems()
				.forEach((id, qty) -> post.merge(plugin.canonicalize(id), qty, Integer::sum));
		}
		Map<Integer, Integer> lost = plugin.deathTracker.computeLosses(post, plugin.itemManager);
		plugin.deathTracker.discardPending();
		plugin.interfaceTracker.setNeedsRebaseline(false);
		plugin.rebaselineGraceTicks = 0;
		plugin.minigameHudGraceTicks = 0;
		plugin.weaponChargeTracker.reset();
		plugin.pendingWornAmmoExpenses.clear();

		if (lost.isEmpty())
		{
			log.debug("Death settled: no item loss (safe death or all kept)");
			return;
		}
		if (!plugin.config.trackSpent())
		{
			log.debug("Death settled: {} item types lost, not recorded (trackSpent off)", lost.size());
			return;
		}

		Map<Integer, Integer> filteredLost = new HashMap<>();
		Map<Integer, Long> prices = new HashMap<>();
		long totalValue = 0L;
		for (Map.Entry<Integer, Integer> entry : lost.entrySet())
		{
			int itemId = plugin.canonicalize(entry.getKey());
			String name = plugin.getItemName(itemId);
			if (plugin.isIgnored(name))
			{
				continue;
			}
			long price;
			if (itemId == ItemID.COINS)
			{
				price = 1;
			}
			else if (itemId == ItemID.PLATINUM)
			{
				price = 1000;
			}
			else
			{
				// Only tradeables carry a value on death. Untradeables are kept,
				// converted, or reclaimed for a fee — none of which is a market
				// loss (and minigame loadout gear would otherwise add noise).
				price = plugin.itemManager != null ? plugin.itemManager.getItemPrice(itemId) : 0;
			}
			if (price <= 0)
			{
				continue;
			}
			filteredLost.merge(itemId, entry.getValue(), Integer::sum);
			prices.putIfAbsent(itemId, price);
			totalValue += price * (long) entry.getValue();
		}

		if (filteredLost.isEmpty())
		{
			log.debug("Death settled: only untradeable/ignored losses, no charge");
			return;
		}

		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		expenses.put(DeathTracker.DEATH_ROW_ID,
			new CoinFlowSession.TrackedItem(DeathTracker.DEATH_ROW_ID, DeathTracker.DEATH_ROW_NAME, totalValue, 1L));
		plugin.session = plugin.session.withGainsLossesAndExpenses(Collections.emptyMap(), Collections.emptyMap(), expenses);

		// Lost session gains can no longer be deducted a second time.
		Map<Integer, Long> consumed = new HashMap<>();
		filteredLost.forEach((id, qty) -> consumed.put(id, (long) qty));
		plugin.session = plugin.session.markConsumed(consumed);

		plugin.deathTracker.recordLost(filteredLost, prices);
		log.debug("Death settled: {} gp loss across {} item types", totalValue, filteredLost.size());
	}

	/**
	 * Matches gained items against the death ledger, limited to items carrying
	 * a live Take click — the signal that distinguishes picking up your own
	 * death drops from looting a coincidental item of the same id.
	 * Matched quantities are removed from {@code gains} in place.
	 */
	void matchDeathPickupGains(Map<Integer, Integer> gains)
	{
		if (gains == null || gains.isEmpty() || !plugin.deathTracker.hasLedger())
		{
			return;
		}
		int tick = plugin.client != null ? plugin.client.getTickCount() : 0;

		// Ledger keys are canonical; the gains map may carry raw ids (noted,
		// placeholders), so match on a canonicalized copy and subtract back.
		Map<Integer, Integer> canonicalGains = new HashMap<>();
		gains.forEach((id, qty) -> canonicalGains.merge(plugin.canonicalize(id), qty, Integer::sum));
		// Post-settle grace: a reclaim item that arrives after the interface
		// closed matches the ledger without needing a Take click.
		DeathTracker.RecoveryResult result = plugin.deathTracker.inRecoveryGrace(tick)
			? plugin.deathTracker.recover(canonicalGains)
			: plugin.deathTracker.recoverForTakeClicks(canonicalGains, tick);
		if (result.isEmpty())
		{
			return;
		}
		for (Map.Entry<Integer, Integer> matched : result.recoveredQuantities.entrySet())
		{
			int remaining = matched.getValue();
			for (Iterator<Map.Entry<Integer, Integer>> it = gains.entrySet().iterator();
				it.hasNext() && remaining > 0;)
			{
				Map.Entry<Integer, Integer> entry = it.next();
				if (plugin.canonicalize(entry.getKey()) != matched.getKey())
				{
					continue;
				}
				int take = Math.min(remaining, entry.getValue());
				remaining -= take;
				if (entry.getValue() <= take)
				{
					it.remove();
				}
				else
				{
					entry.setValue(entry.getValue() - take);
				}
			}
		}
		applyDeathRecovery(result);
	}

	/**
	 * Applies a death recovery to the session: reverses the matched value off
	 * the "Death" expense row, restores consumption on recovered session
	 * gains, and folds any reclaim fee back into the Death row.
	 */
	void applyDeathRecovery(DeathTracker.RecoveryResult result)
	{
		if (result == null || result.isEmpty() || plugin.session == null)
		{
			return;
		}
		if (result.value > 0)
		{
			Map<Integer, Long> reversal = new HashMap<>();
			reversal.put(DeathTracker.DEATH_ROW_ID, result.value);
			plugin.session = plugin.session.withExpenseReversal(reversal);

			Map<Integer, Long> restored = new HashMap<>();
			result.recoveredQuantities.forEach((id, qty) -> restored.put(id, (long) qty));
			plugin.session = plugin.session.withRestoredConsumption(restored);
			log.debug("Death recovery: {} gp reversed for {}", result.value, result.recoveredQuantities);
		}
		if (result.fee > 0)
		{
			applyDeathReclaimFee(result.fee);
		}
	}

	/**
	 * Adds a reclaim fee to the aggregated "Death" expense row. Skipped when
	 * spent tracking is off — a fee-only row has no matching loss to justify.
	 */
	void applyDeathReclaimFee(long fee)
	{
		if (fee <= 0 || plugin.session == null || plugin.config == null || !plugin.config.trackSpent())
		{
			return;
		}
		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		expenses.put(DeathTracker.DEATH_ROW_ID,
			new CoinFlowSession.TrackedItem(DeathTracker.DEATH_ROW_ID, DeathTracker.DEATH_ROW_NAME, fee, 1L));
		plugin.session = plugin.session.withGainsLossesAndExpenses(Collections.emptyMap(), Collections.emptyMap(), expenses);
		log.debug("Death reclaim fee: {} gp", fee);
	}

	/**
	 * Whether the local account gets the 50% ironman reclaim-fee discount.
	 * All iron types qualify except ultimate ironmen.
	 */
	boolean isIronmanAccount()
	{
		AccountType type = plugin.client != null ? plugin.client.getAccountType() : null;
		return type != null && type != AccountType.NORMAL && type != AccountType.ULTIMATE_IRONMAN;
	}
}

package com.coinflow;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Tracks items lost when the local player dies.
 * <p>
 * Lifecycle:
 * <ol>
 *   <li>{@link #onDeath} captures the combined inventory+equipment state. While
 *       a death is pending the plugin freezes diff tracking entirely, so the
 *       post-respawn container clear can never be misclassified as supplies,
 *       cash spends, or drops.</li>
 *   <li>{@link #shouldSettle} fires once the containers have gone quiet after
 *       respawn (or on timeout for safe deaths where nothing changes).
 *       {@link #computeLosses} diffs against the post-death state.</li>
 *   <li>{@link #recover} and {@link #recoverForTakeClicks} match later gains
 *       against the per-item ledger — reclaim interfaces diff against
 *       {@link #setRetrievalBaseline}, Wilderness ground pickups must carry a
 *       recorded Take click — producing a reversal value for the aggregated
 *       "Death" expense row.</li>
 * </ol>
 * The ledger survives logout and transient resets because reclaiming often
 * happens after a relog; it is cleared on startup, shutdown, and session reset.
 */
@Slf4j
@Singleton
public class DeathTracker
{
	/**
	 * Synthetic item id keying the aggregated "Death" expense row. SKULL is a
	 * real item id, but a Skull essentially never produces an expense row, so
	 * a collision is practically impossible and harmless.
	 */
	static final int DEATH_ROW_ID = ItemID.SKULL;
	static final String DEATH_ROW_NAME = "Death";

	/** Ticks after death before a settle is allowed (containers may lag respawn). */
	static final int MIN_SETTLE_TICKS = 3;
	/** Quiet ticks required after the last container change before settling. */
	static final int QUIET_TICKS = 2;
	/** Timeout: settle even when containers never changed (safe death). */
	static final int TIMEOUT_TICKS = 20;
	/** Take clicks older than this cannot confirm a Wilderness recovery. */
	static final int TAKE_CLICK_WINDOW_TICKS = 5;
	/**
	 * Ticks after a reclaim-interface settle during which ledger-matching
	 * gains still count as recovery without a Take click — reclaimed items
	 * can arrive after the interface closes (server lag, or delivery between
	 * a close and a re-open where the re-baseline would otherwise swallow
	 * them).
	 */
	static final int RECOVERY_GRACE_TICKS = 10;
	/**
	 * Ticks a chat-reported fee may sit unconsumed before being applied on
	 * its own — the "Death charges you" message can arrive after the reclaim
	 * interface has already closed and settled.
	 */
	static final int CHAT_FEE_DEFER_TICKS = 2;
	/**
	 * Sanity cap on the reclaim fee inferred from inventory coin movement —
	 * unrelated spends during the window can't fabricate an absurd fee. The
	 * <em>computed</em> fee is not capped by this value: a multi-hundred-mil
	 * office reclaim legitimately exceeds it.
	 */
	static final int MAX_RETRIEVAL_FEE = 5_000_000;

	/** Per-item value below which reclaims are free. */
	static final long FEE_FREE_THRESHOLD = 100_000L;
	/** Gravestone tiers: flat fee per unit by unit value. */
	static final long GRAVE_FEE_T1 = 1_000L;   // 100k - 1m
	static final long GRAVE_FEE_T2 = 10_000L;  // 1m - 10m
	static final long GRAVE_FEE_T3 = 100_000L; // >= 10m
	/** Combined gravestone fee cap per reclaim. */
	static final long GRAVE_FEE_CAP = 500_000L;

	/** A single item lost on death, pending possible recovery. */
	static final class DeathLot
	{
		int quantity;
		long priceEach;

		DeathLot(int quantity, long priceEach)
		{
			this.quantity = quantity;
			this.priceEach = priceEach;
		}
	}

	/** Result of matching a gain against the pending-death ledger. */
	static final class RecoveryResult
	{
		/** itemId -> quantity recovered (capped at ledger quantity). */
		final Map<Integer, Integer> recoveredQuantities = new HashMap<>();
		/** GP value to reverse off the Death expense row (death-time prices). */
		long value;
		/** GP fee observed/computed during a reclaim (added to the Death row). */
		long fee;
		/** itemId -> ledger priceEach for recovered items, for fee computation. */
		final Map<Integer, Long> recoveredPrices = new HashMap<>();

		boolean isEmpty()
		{
			return recoveredQuantities.isEmpty() && value <= 0 && fee <= 0;
		}
	}

	// ── Pending death state ────────────────────────────────────────────
	private Map<Integer, Integer> preDeathItems;
	private int deathTick;
	private int lastContainerChangeTick;

	// ── Recovery ledger ────────────────────────────────────────────────
	/** itemId (canonical) -> unrecovered lost quantity at death-time price. */
	private final Map<Integer, DeathLot> ledger = new HashMap<>();

	/**
	 * Combined inventory+equipment baseline captured when a reclaim interface
	 * (gravestone, Death's Office) opens. Settled on GameTick once no retrieval
	 * interface remains open — scene loads clear the suppressed set without a
	 * WidgetClosed event, so event-driven closing cannot be relied on.
	 */
	private Map<Integer, Integer> retrievalBaseline;
	/** Group id of the retrieval interface that produced the baseline. */
	private int retrievalGroupId = -1;
	/**
	 * Reclaim fee reported by the "Death charges you X coins." game message,
	 * pending consumption by the next {@link #settleRetrieval}. This is the
	 * only signal when the fee is paid from Death's coffer or the bank and
	 * the reclaimed item never appears in inv/worn (e.g. reclaim-to-bank on
	 * a full inventory).
	 */
	private long pendingChatFee;
	private int pendingChatFeeTick = -1;
	/** Tick of the last retrieval settle; gates the post-close recovery grace. */
	private int lastRetrievalSettleTick = -1;
	/**
	 * Tick of the last "You ... retrieved ... from your gravestone." message.
	 * A direct gravestone claim delivers items by script — no retrieval
	 * interface opens and no ground Take click fires — so the message itself
	 * opens the unconditional recovery window.
	 */
	private int graveRetrievalTick = -1;

	/** Canonical item ids whose Take clicks may confirm a Wilderness recovery. */
	private final List<TakeClickRecord> takeClicks = new ArrayList<>();

	private static final class TakeClickRecord
	{
		final int itemId;
		final int tick;

		TakeClickRecord(int itemId, int tick)
		{
			this.itemId = itemId;
			this.tick = tick;
		}
	}

	@Inject
	public DeathTracker() {}

	// ── Capture / freeze / settle ──────────────────────────────────────

	/**
	 * Records a local-player death with the combined pre-death inventory+equipment
	 * state (canonical ids). A second death while still settling keeps the
	 * original capture: nothing between the two deaths can be real player gain,
	 * so the merged window is the correct loss.
	 */
	void onDeath(Map<Integer, Integer> preDeath, int tick)
	{
		if (isPending())
		{
			log.debug("Death while pending; keeping earlier capture");
			return;
		}
		preDeathItems = new HashMap<>(preDeath);
		deathTick = tick;
		lastContainerChangeTick = -1;
		log.debug("Death pending: captured {} item types", preDeathItems.size());
	}

	boolean isPending()
	{
		return preDeathItems != null;
	}

	void onContainerChanged(int tick)
	{
		if (isPending())
		{
			lastContainerChangeTick = tick;
		}
	}

	/**
	 * Settle once the post-death containers have gone quiet, or on timeout
	 * (safe deaths where nothing changes). Settling early is what must be
	 * avoided: a staged clear arriving after settle would be swallowed by the
	 * frozen baseline and under-counted.
	 */
	boolean shouldSettle(int currentTick)
	{
		if (!isPending())
		{
			return false;
		}
		int since = currentTick - deathTick;
		if (since >= TIMEOUT_TICKS)
		{
			return true;
		}
		return since >= MIN_SETTLE_TICKS
			&& lastContainerChangeTick >= 0
			&& currentTick - lastContainerChangeTick >= QUIET_TICKS;
	}

	/**
	 * Finalizes the pending death against the post-death combined state.
	 * Charge-degradation transitions (charged -> degraded variant of the same
	 * item, including Wilderness "(broken)" forms) are cancelled from both
	 * sides so a keep-plus-degrade isn't counted as a loss.
	 *
	 * @return itemId (canonical) -> lost quantity; the caller filters/prices it
	 */
	Map<Integer, Integer> computeLosses(Map<Integer, Integer> postDeath, ItemManager itemManager)
	{
		Map<Integer, Integer> losses = new HashMap<>();
		if (preDeathItems == null)
		{
			return losses;
		}
		for (Map.Entry<Integer, Integer> entry : preDeathItems.entrySet())
		{
			int delta = entry.getValue() - postDeath.getOrDefault(entry.getKey(), 0);
			if (delta > 0)
			{
				losses.put(entry.getKey(), delta);
			}
		}

		Map<Integer, Integer> gains = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : postDeath.entrySet())
		{
			int delta = entry.getValue() - preDeathItems.getOrDefault(entry.getKey(), 0);
			if (delta > 0)
			{
				gains.put(entry.getKey(), delta);
			}
		}
		cancelDegradePairs(losses, gains, itemManager);
		return losses;
	}

	/**
	 * Cancels lost<->gained pairs that are charge/degradation transitions of
	 * the same item — e.g. "Amulet of glory(4)" -> "(3)", "Dharok's helm 100" ->
	 * 75, or "Torva platelegs" -> "Torva platelegs (broken)" on a wildy death.
	 */
	private void cancelDegradePairs(Map<Integer, Integer> losses, Map<Integer, Integer> gains,
		ItemManager itemManager)
	{
		for (Iterator<Map.Entry<Integer, Integer>> lostIt = losses.entrySet().iterator(); lostIt.hasNext();)
		{
			Map.Entry<Integer, Integer> lost = lostIt.next();
			String lostName = itemName(itemManager, lost.getKey());

			for (Iterator<Map.Entry<Integer, Integer>> gainedIt = gains.entrySet().iterator(); gainedIt.hasNext();)
			{
				Map.Entry<Integer, Integer> gained = gainedIt.next();
				String gainedName = itemName(itemManager, gained.getKey());

				if (!com.coinflow.reconciliation.ChargeDegradationHandler.isChargeDegradationPair(lostName, gainedName)
					&& !isBrokenPair(lostName, gainedName))
				{
					continue;
				}

				int match = Math.min(lost.getValue(), gained.getValue());
				if (gained.getValue() <= match)
				{
					gainedIt.remove();
				}
				else
				{
					gained.setValue(gained.getValue() - match);
				}
				if (lost.getValue() <= match)
				{
					lostIt.remove();
					break;
				}
				lost.setValue(lost.getValue() - match);
			}
		}
	}

	private static boolean isBrokenPair(String lostName, String gainedName)
	{
		return gainedName != null && lostName != null
			&& gainedName.equalsIgnoreCase(lostName + " (broken)");
	}

	private static String itemName(ItemManager itemManager, int itemId)
	{
		if (itemManager == null)
		{
			return "";
		}
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null && comp.getName() != null ? comp.getName() : "";
	}

	/**
	 * Discards the pending death (logout/hop before settle). Ledger kept.
	 */
	void discardPending()
	{
		preDeathItems = null;
		lastContainerChangeTick = -1;
	}

	/**
	 * Adds lost quantities to the recovery ledger at their death-time prices.
	 * Re-lost items re-price at the newer death's price; per-lot price history
	 * isn't worth tracking.
	 */
	void recordLost(Map<Integer, Integer> quantities, Map<Integer, Long> prices)
	{
		for (Map.Entry<Integer, Integer> entry : quantities.entrySet())
		{
			long price = prices.getOrDefault(entry.getKey(), 0L);
			DeathLot existing = ledger.get(entry.getKey());
			if (existing != null)
			{
				existing.quantity += entry.getValue();
				existing.priceEach = price;
			}
			else
			{
				ledger.put(entry.getKey(), new DeathLot(entry.getValue(), price));
			}
		}
	}

	Map<Integer, DeathLot> getLedger()
	{
		return ledger;
	}

	boolean hasLedger()
	{
		return !ledger.isEmpty();
	}

	int ledgerQuantity(int itemId)
	{
		DeathLot lot = ledger.get(itemId);
		return lot != null ? lot.quantity : 0;
	}

	// ── Recovery: reclaim interfaces ───────────────────────────────────

	/**
	 * Stores the combined inventory+equipment baseline when a reclaim
	 * interface opens. Ignored while the ledger is empty (nothing to recover).
	 */
	void setRetrievalBaseline(Map<Integer, Integer> combined, int groupId)
	{
		if (!hasLedger())
		{
			return;
		}
		retrievalBaseline = new HashMap<>(combined);
		retrievalGroupId = groupId;
	}

	boolean hasRetrievalBaseline()
	{
		return retrievalBaseline != null;
	}

	/**
	 * Diffs live containers against the retrieval baseline once no reclaim
	 * interface is open: gains are recoveries (matched into the ledger).
	 * The reclaim fee is the largest of three measures — coins that left
	 * inventory while the interface was open (cash-paid fees, capped as a
	 * sanity bound), the fee computed from the recovered items' ledger
	 * prices using the official reclaim schedules (which also sees fees paid
	 * from Death's coffer or the bank, invisible to the inventory diff), and
	 * any pending fee reported by the "Death charges you" chat message.
	 *
	 * @param current combined inventory+equipment map
	 * @param tick current tick, for the post-close recovery grace window
	 * @param ironman whether the account gets the 50% ironman fee discount
	 */
	RecoveryResult settleRetrieval(Map<Integer, Integer> current, int tick, boolean ironman)
	{
		RecoveryResult result = new RecoveryResult();
		if (retrievalBaseline == null)
		{
			return result;
		}
		Map<Integer, Integer> baseline = retrievalBaseline;
		retrievalBaseline = null;
		int groupId = retrievalGroupId;
		retrievalGroupId = -1;
		lastRetrievalSettleTick = tick;

		Map<Integer, Integer> gains = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : current.entrySet())
		{
			int delta = entry.getValue() - baseline.getOrDefault(entry.getKey(), 0);
			if (delta > 0)
			{
				gains.put(entry.getKey(), delta);
			}
		}
		matchIntoLedger(gains, result);

		// The chat-reported fee is folded in here rather than applied at parse
		// time so it can't double-count against the computed/observed fee for
		// the same reclaim. Accumulating pendingChatFee also lets it cover a
		// reclaim whose items never entered inv/worn (reclaim-to-bank).
		long chatFee = pendingChatFee;
		pendingChatFee = 0;
		pendingChatFeeTick = -1;

		long computedFee = computedReclaimFee(result, groupId, ironman);
		int coinsLost = baseline.getOrDefault(ItemID.COINS, 0) - current.getOrDefault(ItemID.COINS, 0);
		long observedFee = Math.min(Math.max(coinsLost, 0), MAX_RETRIEVAL_FEE);
		// The chat message is the exact charge, so it wins over the schedule
		// estimate — the game's reclaim valuation differs from our item
		// prices. Computed only fills in when no message was seen. Observed
		// coin losses still compete since they may be a real extra outflow.
		result.fee = Math.max(observedFee, chatFee > 0 ? chatFee : computedFee);
		return result;
	}

	/**
	 * Records a fee reported by the "Death charges you X coins." game
	 * message. Ignored with no reclaim context (empty ledger, no open
	 * retrieval baseline, no recent settle).
	 */
	void noteChatFee(long amount, int tick)
	{
		if (amount <= 0
			|| (!hasLedger() && !hasRetrievalBaseline() && !recentlySettled(tick)))
		{
			return;
		}
		pendingChatFee += amount;
		pendingChatFeeTick = tick;
	}

	/**
	 * Records a "retrieved ... from your gravestone." game message — the only
	 * signal for a direct gravestone claim, which delivers items by script
	 * without opening a retrieval interface. Ignored with no ledger: the
	 * window would match nothing anyway, and a stale marker could mislabel
	 * a later death's same-id gains as recovery.
	 */
	void noteGraveRetrieval(int tick)
	{
		if (hasLedger())
		{
			graveRetrievalTick = tick;
		}
	}

	/**
	 * Whether a reclaim settled or a gravestone claim was announced recently
	 * enough that ledger-matching gains should count as recovery even
	 * without a Take click.
	 */
	boolean inRecoveryGrace(int tick)
	{
		return hasLedger() && (recentlySettled(tick) || recentlyRetrievedFromGrave(tick));
	}

	private boolean recentlySettled(int tick)
	{
		return lastRetrievalSettleTick >= 0 && tick - lastRetrievalSettleTick <= RECOVERY_GRACE_TICKS;
	}

	private boolean recentlyRetrievedFromGrave(int tick)
	{
		return graveRetrievalTick >= 0 && tick - graveRetrievalTick <= RECOVERY_GRACE_TICKS;
	}

	/**
	 * Returns a chat-reported fee that outlived its settle window, once —
	 * a fee message that arrived after the reclaim interface already closed
	 * and settled would otherwise sit in {@link #pendingChatFee} forever.
	 * The caller skips this while a retrieval baseline is live so a pending
	 * fee always folds into the next settle instead of applying twice.
	 */
	long consumeDeferredChatFee(int tick)
	{
		if (pendingChatFee <= 0 || tick - pendingChatFeeTick < CHAT_FEE_DEFER_TICKS)
		{
			return 0;
		}
		long fee = pendingChatFee;
		pendingChatFee = 0;
		pendingChatFeeTick = -1;
		return fee;
	}

	/**
	 * Total reclaim fee for the recovered items under the schedule of the
	 * interface that was open: Death's Office charges 5% per unit over the
	 * free threshold, gravestones a flat per-unit tier with a combined cap.
	 * Prices are the death-time ledger prices — close enough to the game's
	 * current-GE-value basis.
	 */
	private long computedReclaimFee(RecoveryResult result, int groupId, boolean ironman)
	{
		long fee = 0;
		for (Map.Entry<Integer, Integer> entry : result.recoveredQuantities.entrySet())
		{
			long price = result.recoveredPrices.getOrDefault(entry.getKey(), 0L);
			fee += feePerUnit(price, groupId, ironman) * entry.getValue();
		}
		if (groupId != InterfaceID.DEATH_OFFICE)
		{
			fee = Math.min(fee, GRAVE_FEE_CAP);
		}
		return fee;
	}

	private static long feePerUnit(long priceEach, int groupId, boolean ironman)
	{
		if (priceEach < FEE_FREE_THRESHOLD)
		{
			return 0;
		}
		long fee;
		if (groupId == InterfaceID.DEATH_OFFICE)
		{
			fee = priceEach * 5 / 100;
		}
		else if (priceEach >= 10_000_000L)
		{
			fee = GRAVE_FEE_T3;
		}
		else if (priceEach >= 1_000_000L)
		{
			fee = GRAVE_FEE_T2;
		}
		else
		{
			fee = GRAVE_FEE_T1;
		}
		return ironman ? fee / 2 : fee;
	}

	// ── Recovery: ground pickups ───────────────────────────────────────

	/**
	 * Records a Take click that may later confirm a Wilderness ground pickup
	 * recovery. Only clicks with a non-empty ledger are recorded.
	 */
	void recordTakeClick(int itemId, int tick)
	{
		if (!hasLedger())
		{
			return;
		}
		takeClicks.add(new TakeClickRecord(itemId, tick));
	}

	/**
	 * Matches gained items against the ledger, but only for items carrying a
	 * live Take click — this is what separates picking up your own death drops
	 * from looting a coincidental new item (e.g. another monster's drop).
	 *
	 * @param gains map of canonical itemId -> gained quantity; matched amounts
	 *              are subtracted in place
	 */
	RecoveryResult recoverForTakeClicks(Map<Integer, Integer> gains, int currentTick)
	{
		RecoveryResult result = new RecoveryResult();
		if (gains == null || gains.isEmpty() || !hasLedger())
		{
			return result;
		}
		expireTakeClicks(currentTick);
		if (takeClicks.isEmpty())
		{
			return result;
		}

		for (Iterator<Map.Entry<Integer, Integer>> it = gains.entrySet().iterator(); it.hasNext();)
		{
			Map.Entry<Integer, Integer> entry = it.next();
			boolean clicked = false;
			for (TakeClickRecord click : takeClicks)
			{
				if (click.itemId == entry.getKey())
				{
					clicked = true;
					break;
				}
			}
			if (!clicked)
			{
				continue;
			}
			int matched = matchItem(entry.getKey(), entry.getValue(), result);
			int remaining = entry.getValue() - matched;
			if (remaining <= 0)
			{
				it.remove();
			}
			else
			{
				entry.setValue(remaining);
			}
		}
		return result;
	}

	/**
	 * Matches all gains against the ledger unconditionally — used by reclaim
	 * interfaces where anything returning is a recovery. Matched amounts are
	 * subtracted from {@code gains} in place.
	 */
	RecoveryResult recover(Map<Integer, Integer> gains)
	{
		RecoveryResult result = new RecoveryResult();
		if (gains == null || gains.isEmpty() || !hasLedger())
		{
			return result;
		}
		matchIntoLedger(gains, result);
		return result;
	}

	private void matchIntoLedger(Map<Integer, Integer> gains, RecoveryResult result)
	{
		for (Iterator<Map.Entry<Integer, Integer>> it = gains.entrySet().iterator(); it.hasNext();)
		{
			Map.Entry<Integer, Integer> entry = it.next();
			int matched = matchItem(entry.getKey(), entry.getValue(), result);
			int remaining = entry.getValue() - matched;
			if (remaining <= 0)
			{
				it.remove();
			}
			else
			{
				entry.setValue(remaining);
			}
		}
	}

	/** @return quantity matched into the ledger (also accumulated in result) */
	private int matchItem(int itemId, int gainedQty, RecoveryResult result)
	{
		DeathLot lot = ledger.get(itemId);
		if (lot == null || gainedQty <= 0)
		{
			return 0;
		}
		int matched = Math.min(gainedQty, lot.quantity);
		lot.quantity -= matched;
		if (lot.quantity <= 0)
		{
			ledger.remove(itemId);
		}
		result.recoveredQuantities.merge(itemId, matched, Integer::sum);
		result.recoveredPrices.putIfAbsent(itemId, lot.priceEach);
		result.value += matched * lot.priceEach;
		return matched;
	}

	private void expireTakeClicks(int currentTick)
	{
		takeClicks.removeIf(click -> currentTick - click.tick > TAKE_CLICK_WINDOW_TICKS);
	}

	int takeClickCount()
	{
		return takeClicks.size();
	}

	/**
	 * Full reset (startup, shutdown, session reset). The ledger is intentionally
	 * NOT cleared by {@link #discardPending} or transient tracking resets —
	 * reclaimed items must still reverse the Death row after a relog.
	 */
	void reset()
	{
		discardPending();
		ledger.clear();
		retrievalBaseline = null;
		retrievalGroupId = -1;
		lastRetrievalSettleTick = -1;
		graveRetrievalTick = -1;
		pendingChatFee = 0;
		pendingChatFeeTick = -1;
		takeClicks.clear();
	}
}

package com.coinflow;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Per-game-tick orchestration: ages grace windows and take-click records,
 * finalizes death recovery and pending pickup drains, settles consumed
 * worn ammo and weapon-charge resources, ticks session idle/time state,
 * and refreshes goal notification plus the sidebar panel. Ordering is
 * load-bearing — each stage depends on the one before.
 */
@Slf4j
final class GameTickProcessor
{
	private final CoinFlowPlugin plugin;

	GameTickProcessor(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onGameTick(GameTick event)
	{
		// Age the region grace window before re-evaluating so a same-tick
		// transition keeps its full window.
		plugin.interfaceTracker.onGameTick();

		// Age the HUD and re-baseline grace windows the same way — BEFORE
		// updateSuppressedRegion latches any fresh transition (so it keeps
		// its full window), and BEFORE the snapshot guard below: if the
		// login baseline never initialized (e.g. the inventory container
		// was null mid-load), an early return would freeze them open and
		// wedge tracking suppression on permanently.
		if (plugin.minigameHudGraceTicks > 0)
		{
			plugin.minigameHudGraceTicks--;
		}
		if (plugin.rebaselineGraceTicks > 0)
		{
			plugin.rebaselineGraceTicks--;
			if (plugin.rebaselineGraceTicks == 0 && plugin.interfaceTracker.isNeedsRebaseline())
			{
				plugin.interfaceTracker.setNeedsRebaseline(false);
				if (plugin.client != null && plugin.snapshotInitialized)
				{
					ItemContainer inv = plugin.client.getItemContainer(InventoryID.INV);
					if (inv != null)
					{
						plugin.previousInventorySnapshot = plugin.takeInventorySnapshot(inv);
					}
				}
			}
		}

		plugin.updateSuppressedRegion();

		// Unsupported worlds pause tracking entirely — Leagues/DMM time must
		// not dilute the main session's GP/hr. This latch runs before the
		// snapshot gate below: on an unsupported world no baseline is ever
		// taken (suppressed container events re-baseline without setting
		// snapshotInitialized), so a check placed after finalizePendingPickups
		// would be unreachable for the entire stay. On leaving, resume like a
		// relog (the paused gap never counts) and re-baseline the inventory.
		boolean unsupportedWorld = plugin.isUnsupportedWorld();
		if (unsupportedWorld)
		{
			if (!plugin.wasUnsupportedWorld)
			{
				// Pause transitions get no session event, so ping the panel
				// once to flip the "Paused" status on/off.
				if (plugin.panel != null && plugin.session != null)
				{
					plugin.panel.updateSession(plugin.session);
				}
				log.debug("Unsupported world ({}), pausing tracking",
					plugin.client.getWorldType());
			}
			plugin.wasUnsupportedWorld = true;
		}
		else if (plugin.wasUnsupportedWorld)
		{
			plugin.wasUnsupportedWorld = false;
			if (plugin.session != null)
			{
				plugin.session = plugin.session.withResumedState();
			}
			plugin.interfaceTracker.setNeedsRebaseline(true);
			if (plugin.panel != null && plugin.session != null)
			{
				plugin.panel.updateSession(plugin.session);
			}
			log.debug("Left unsupported world, resuming session");
		}

		if (!plugin.containerPickupTracker.finalizePendingPickups())
		{
			return;
		}
		plugin.matchedUnequipsThisTick.clear();

		plugin.deathFlowCoordinator.onGameTick();

		// Blast Furnace coffer settle: held coin diffs are attributed against
		// the coffer varbit (deposit/withdrawal transfer vs. drain), the drain
		// accrues to the synthetic "Blast Furnace coffer" row, and unmatched
		// held coins expire into fallback accounting. The drain keeps ticking
		// while the bank chest is open, so no bank-open gate; skipped on
		// unsupported worlds and mid-death-settle (held entries carry over).
		if (!unsupportedWorld && !plugin.deathTracker.isPending() && plugin.session != null)
		{
			settleBlastFurnaceCoffer();
		}

		// Finalize pending equipped ammo/thrown weapons and crumbled jewelry
		// consumed without inventory changes
		if (!plugin.pendingWornAmmoExpenses.isEmpty())
		{
			if (plugin.isTrackingSuppressed() || plugin.isBankOrContainerOpen() || plugin.interfaceTracker.isShopOpen() || plugin.interfaceTracker.isNeedsRebaseline() || plugin.rebaselineGraceTicks > 0 || plugin.deathTracker.isPending())
			{
				plugin.pendingWornAmmoExpenses.clear();
			}
			else
			{
				Map<Integer, CoinFlowSession.TrackedItem> wornAmmoExpenses = new HashMap<>();
				for (Map.Entry<Integer, Integer> entry : plugin.pendingWornAmmoExpenses.entrySet())
				{
					int itemId = entry.getKey();
					int quantity = entry.getValue();
					String itemName = plugin.getItemName(itemId);
					long price = ItemPricing.priceOf(itemId, plugin.itemManager);
					wornAmmoExpenses.put(itemId, new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price));
					log.debug("Consumed equipped ammo/jewelry on tick: {} x{} @ {} gp = {} gp", itemName, quantity, price, (long) quantity * price);
					plugin.removeRecentlyUnequipped(itemId, quantity);
				}
				plugin.pendingWornAmmoExpenses.clear();
				plugin.processGainsLossesAndExpenses(Collections.emptyMap(), Collections.emptyMap(), wornAmmoExpenses);
			}
		}

		// Finalize pending charge-based supply costs (runes/scales/shards stored inside weapons)
		boolean chargeTrackingAllowed = !plugin.isTrackingSuppressed() && !plugin.isBankOrContainerOpen()
			&& !plugin.interfaceTracker.isShopOpen()
			&& !plugin.interfaceTracker.isNeedsRebaseline() && plugin.rebaselineGraceTicks <= 0
			&& !plugin.deathTracker.isPending();
		if (plugin.client != null)
		{
			for (int varbitId : WeaponChargeTracker.trackedVarbitIds())
			{
				if (plugin.invalidVarbitIds.contains(varbitId))
				{
					continue;
				}
				int value;
				try
				{
					value = plugin.client.getVarbitValue(varbitId);
				}
				catch (IndexOutOfBoundsException e)
				{
					// Some tracked CHARGES_* varbits are not varp-backed / not present in this
					// client build; getVarbitValue throws for them. Skip them from now on.
					if (plugin.invalidVarbitIds.add(varbitId))
					{
						log.debug("Ignoring untracked varbit {} (not varp-backed)", varbitId);
					}
					continue;
				}
				plugin.weaponChargeTracker.onVarbitChanged(varbitId, value,
					chargeTrackingAllowed, plugin.client.getTickCount());
			}
		}
		plugin.weaponChargeTracker.setDartRecoveryRate(plugin.equippedAvasRecoveryRate());
		// When tracking is disallowed mid-window (rebaseline grace), keep the pending
		// spend so attack-triggered costs aren't silently dropped; when the feature is
		// disabled, drain anyway to discard accumulation.
		Map<Integer, Integer> consumedChargeResources = chargeTrackingAllowed || !plugin.config.trackWeaponCharges()
			? plugin.weaponChargeTracker.drain()
			: Collections.emptyMap();
		if (!consumedChargeResources.isEmpty() && plugin.config.trackWeaponCharges())
		{
			Map<Integer, CoinFlowSession.TrackedItem> chargeExpenses = new HashMap<>();
			for (Map.Entry<Integer, Integer> entry : consumedChargeResources.entrySet())
			{
				int itemId = entry.getKey();
				int quantity = entry.getValue();
				String itemName = plugin.getItemName(itemId);
				long price = ItemPricing.priceOf(itemId, plugin.itemManager);
				chargeExpenses.put(itemId, new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price));
				log.debug("Consumed weapon charge resource on tick: {} x{} @ {} gp", itemName, quantity, price);
			}
			plugin.processGainsLossesAndExpenses(Collections.emptyMap(), Collections.emptyMap(), chargeExpenses);
		}

		if (plugin.client != null)
		{
			int currentTick = plugin.client.getTickCount();
			plugin.containerPickupTracker.ageTakeClicks(currentTick);

			// Evict gear-swap records unmatched for >10 ticks (~6s). WORN<->INV
			// dispatch pairs resolve within 1-2 ticks, so anything older is stale
			// (e.g. ammo picked up directly into the ammo slot) and must not cancel
			// future legitimate inventory diffs.
			if (!plugin.gearSwapItemTicks.isEmpty())
			{
				plugin.gearSwapItemTicks.entrySet().removeIf(entry -> {
					if (currentTick - entry.getValue() > 10)
					{
						plugin.recentlyUnequippedItems.remove(entry.getKey());
						plugin.recentlyEquippedItems.remove(entry.getKey());
						return true;
					}
					return false;
				});
			}
		}

		// Update idle state and time tracking on each tick
		if (!unsupportedWorld)
		{
			CoinFlowSession prevSession = plugin.session;
			plugin.session = plugin.session.tick(plugin.config.idleTimeoutMinutes(), plugin.isPlayerActive());

			// Periodic session telemetry (~every 30s) for debugging GP/hr and timer behavior.
			// tickDelta should hover ~600ms; sustained near-0 values indicate clock corruption.
			if (log.isDebugEnabled() && plugin.client != null && plugin.client.getTickCount() % 50 == 0)
			{
				log.debug("Session: tickDelta={}ms active={}s total={}s gross={} spent={} gp/hr={} idle={}",
					plugin.session.getTotalInGameTime().minus(prevSession.getTotalInGameTime()).toMillis(),
					plugin.session.getActiveTime().getSeconds(), plugin.session.getTotalInGameTime().getSeconds(),
					plugin.session.getGrossProfit(), plugin.session.getTotalExpenses(),
					plugin.session.getGpPerHour(plugin.config.includeAfkTime()), plugin.session.isIdle());
			}
		}

		// Evict dropped item records older than 600 ticks (~6 minutes) to prevent memory leak and stale pickup matching
		if (plugin.client != null && plugin.client.getTickCount() % 50 == 0)
		{
			int currentTick = plugin.client.getTickCount();
			plugin.droppedItemTicks.entrySet().removeIf(entry -> {
				if (currentTick - entry.getValue() > 600)
				{
					plugin.recentlyDroppedItems.remove(entry.getKey());
					plugin.recentlyDroppedOwnedItems.remove(entry.getKey());
					plugin.recentlyExpensedDrops.remove(entry.getKey());
					return true;
				}
				return false;
			});
		}

		// Check goal completion notification (with latch to prevent tick spam)
		plugin.checkGoalNotification();

		// Update sidebar panel if visible
		if (plugin.panel != null)
		{
			plugin.panel.updateSession(plugin.session);
		}
	}

	/**
	 * Reads the coffer varbit (only while at the furnace), settles the held
	 * coin diffs and the accrued drain, and applies the outcome to the
	 * session. When the tracker reports inactive (conveyor despawned /
	 * LOADING), the settle flushes any remaining drain on the way out.
	 */
	private void settleBlastFurnaceCoffer()
	{
		int cofferValue = -1;
		if (plugin.blastFurnaceTracker.isActive()
			&& plugin.client != null
			&& !plugin.invalidVarbitIds.contains(VarbitID.BLAST_FURNACE_COFFER))
		{
			try
			{
				cofferValue = plugin.client.getVarbitValue(VarbitID.BLAST_FURNACE_COFFER);
			}
			catch (IndexOutOfBoundsException e)
			{
				plugin.invalidVarbitIds.add(VarbitID.BLAST_FURNACE_COFFER);
				log.debug("Ignoring untracked varbit {} (not varp-backed)", VarbitID.BLAST_FURNACE_COFFER);
			}
		}

		BlastFurnaceTracker.Settlement settle = plugin.blastFurnaceTracker.onTick(cofferValue,
			plugin.client != null ? plugin.client.getTickCount() : 0);

		Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		Map<Integer, Integer> gains = Collections.emptyMap();
		if (settle.drainChargeGp > 0)
		{
			expenses.put(BlastFurnaceTracker.COFFER_ROW_ID,
				new CoinFlowSession.TrackedItem(BlastFurnaceTracker.COFFER_ROW_ID,
					BlastFurnaceTracker.COFFER_ROW_NAME, settle.drainChargeGp, 1L));
			log.debug("Blast Furnace coffer drain charged: {} gp", settle.drainChargeGp);
		}
		if (settle.cashSpendCoins > 0)
		{
			String coinsName = plugin.getItemName(ItemID.COINS);
			expenses.put(ItemID.COINS,
				new CoinFlowSession.TrackedItem(ItemID.COINS, coinsName, settle.cashSpendCoins, 1L));
			// Like the cash-spend path in ConsumablesAndDropsHandler: retire
			// matching session coin gains so pre-session coins dropped later
			// cannot deduct the already-spent loot a second time.
			plugin.session = plugin.session.markConsumed(
				Collections.singletonMap(ItemID.COINS, (long) settle.cashSpendCoins));
			log.debug("Blast Furnace unmatched coin spend: {} gp", settle.cashSpendCoins);
		}
		if (settle.coinGainQty > 0)
		{
			gains = Collections.singletonMap(ItemID.COINS, settle.coinGainQty);
			log.debug("Blast Furnace unmatched coin gain re-applied: {} gp", settle.coinGainQty);
		}
		if (!expenses.isEmpty() || !gains.isEmpty())
		{
			plugin.processGainsLossesAndExpenses(gains, Collections.emptyMap(), expenses);
		}
	}
}

package com.coinflow;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * Grand Exchange sell tax. {@code GrandExchangeOffer.getSpent()} reports gross
 * coins before tax, so net proceeds must be derived: 2% per item, rounded down,
 * capped at 5,000,000 coins per item, with a set of exempt items.
 */
final class GrandExchangeTax
{
	static final double RATE = 0.02;
	static final long CAP_PER_ITEM = 5_000_000L;

	/**
	 * Sentinel key for the GE tax expense entry in the session breakdown. Uses a
	 * real coins-pile sprite id so the panel renders an icon; it never collides
	 * with actual inventory items or the generic "Coins" expense row.
	 */
	static final int TAX_ITEM_ID = ItemID.COINS_10000;
	static final String TAX_ITEM_NAME = "GE Tax";

	static final Set<Integer> EXEMPT_ITEMS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.CHISEL,
		ItemID.GARDENING_TROWEL,
		ItemID.HAMMER,
		ItemID.NEEDLE,
		ItemID.OSRS_BOND,
		ItemID.PESTLE_AND_MORTAR,
		ItemID.RAKE,
		ItemID.POH_SAW,
		ItemID.SECATEURS,
		ItemID.DIBBER,
		ItemID.SHEARS,
		ItemID.SPADE,
		ItemID.WATERING_CAN_0,
		ItemID.POH_TABLET_ARDOUGNETELEPORT,
		ItemID.BASS,
		ItemID.BREAD,
		ItemID.BRONZE_ARROW,
		ItemID.BRONZE_DART,
		ItemID.CAKE,
		ItemID.POH_TABLET_CAMELOTTELEPORT,
		ItemID.POH_TABLET_FORTISTELEPORT,
		ItemID.COOKED_CHICKEN,
		ItemID.COOKED_MEAT,
		ItemID._4DOSE1ENERGY,
		ItemID._3DOSE1ENERGY,
		ItemID._2DOSE1ENERGY,
		ItemID._1DOSE1ENERGY,
		ItemID.POH_TABLET_FALADORTELEPORT,
		ItemID.NECKLACE_OF_MINIGAMES_8,
		ItemID.HERRING,
		ItemID.IRON_ARROW,
		ItemID.IRON_DART,
		ItemID.POH_TABLET_KOURENDTELEPORT,
		ItemID.LOBSTER,
		ItemID.POH_TABLET_LUMBRIDGETELEPORT,
		ItemID.MACKEREL,
		ItemID.MEAT_PIE,
		ItemID.MINDRUNE,
		ItemID.PIKE,
		ItemID.RING_OF_DUELING_8,
		ItemID.SALMON,
		ItemID.SHRIMP,
		ItemID.STEEL_ARROW,
		ItemID.STEEL_DART,
		ItemID.POH_TABLET_TELEPORTTOHOUSE,
		ItemID.TUNA,
		ItemID.POH_TABLET_VARROCKTELEPORT
	)));

	private GrandExchangeTax() {}

	/**
	 * Tax charged on one item sold at the given price.
	 */
	static long taxPerItem(int itemId, long priceEach)
	{
		if (priceEach <= 0 || EXEMPT_ITEMS.contains(itemId))
		{
			return 0L;
		}
		return Math.min((long) Math.floor(priceEach * RATE), CAP_PER_ITEM);
	}

	/**
	 * Net coins received for a sell fill of {@code quantity} items with
	 * {@code grossProceeds} total pre-tax coins.
	 */
	static long netProceeds(int itemId, int quantity, long grossProceeds)
	{
		if (quantity <= 0 || grossProceeds <= 0)
		{
			return 0L;
		}
		long priceEach = grossProceeds / quantity;
		return grossProceeds - taxPerItem(itemId, priceEach) * quantity;
	}
}

package com.coinflow;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Tracks Grand Exchange offers and settles completed fills against the session's
 * carried values, independent of inventory diffing.
 *
 * GE activity never produces usable inventory diffs: items leave while the GE
 * interface suppresses tracking, and proceeds/items arrive via "Collect" which is
 * re-baselined away. This tracker therefore derives accounting purely from
 * {@link GrandExchangeOffer} state deltas (quantitySold and spent), which reflect
 * fills the moment they happen — including partial fills, fills while away from
 * the exchange, and collect-to-bank.
 *
 * Carried-value accounting model for a sold unit:
 *  - bought via GE this session: actual cost basis (FIFO lots)
 *  - gained this session (loot): the session's tracked gain price
 *  - anything else (banked/pre-session): the actual gross fill price, so the
 *    only residual is the GE tax
 *
 * {@link GrandExchangeOffer#getSpent()} is gross (pre-tax) for sells; net
 * proceeds are derived via {@link GrandExchangeTax}.
 *
 * Buy fills are not session entries; they are asset conversions. The coins spent
 * are stored as cost basis so a later sale realizes the true margin.
 *
 * The FIFO cost-basis pool and sell-settlement logic are shared with shop
 * trades ({@link ShopTracker}): shop purchases add basis lots here, and shop
 * sales decompose via {@link #settleShopSell}, so cross-venue flows
 * (buy shop → sell GE, buy GE → sell shop) realize the correct margin.
 */
@Slf4j
public final class GrandExchangeTracker
{
	/**
	 * An incremental fill observed on one GE slot between two offer snapshots.
	 */
	static final class GeDelta
	{
		final int itemId;
		final int quantityDelta;
		final long priceEach;
		final long coinsDelta;
		final boolean buy;

		GeDelta(int itemId, int quantityDelta, long priceEach, long coinsDelta, boolean buy)
		{
			this.itemId = itemId;
			this.quantityDelta = quantityDelta;
			this.priceEach = priceEach;
			this.coinsDelta = coinsDelta;
			this.buy = buy;
		}
	}

	/**
	 * Session entries produced by settling a sell delta, plus the net profit
	 * impact for display purposes.
	 */
	static final class GeLedger
	{
		final Map<Integer, CoinFlowSession.TrackedItem> gains = new HashMap<>();
		final Map<Integer, CoinFlowSession.TrackedItem> deductions = new HashMap<>();
		final Map<Integer, CoinFlowSession.TrackedItem> expenses = new HashMap<>();
		long netDelta;

		boolean isEmpty()
		{
			return gains.isEmpty() && deductions.isEmpty() && expenses.isEmpty();
		}
	}

	private static final class ObservedOffer
	{
		final int itemId;
		final int quantitySold;
		final long spent;

		ObservedOffer(int itemId, int quantitySold, long spent)
		{
			this.itemId = itemId;
			this.quantitySold = quantitySold;
			this.spent = spent;
		}
	}

	private static final class BasisLot
	{
		int quantity;
		long remainingCost;

		BasisLot(int quantity, long cost)
		{
			this.quantity = quantity;
			this.remainingCost = cost;
		}
	}

	private final Map<Integer, ObservedOffer> observedOffers = new HashMap<>();
	private final Map<Integer, Deque<BasisLot>> costBasis = new HashMap<>();

	/**
	 * Seeds slot observations from the client's current offers so the next fill
	 * deltas correctly instead of being treated as a baseline (plugin enabled or
	 * session reset while offers are already in progress).
	 */
	void seed(GrandExchangeOffer[] offers)
	{
		if (offers == null)
		{
			return;
		}
		for (int slot = 0; slot < offers.length; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null || offer.getState() == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				observedOffers.remove(slot);
				continue;
			}
			observedOffers.put(slot, new ObservedOffer(offer.getItemId(), offer.getQuantitySold(), offer.getSpent()));
		}
	}

	/**
	 * Processes an offer update for a slot and returns any newly filled deltas.
	 * The first observation of an offer is a baseline only — fills that completed
	 * before this plugin session observed the slot are not counted. A quantity
	 * decrease or item change also re-baselines (slot reuse / data reset).
	 *
	 * The client emits EMPTY for every slot while logging in or hopping; those are
	 * ignored so fills completed while logged out still delta against the
	 * pre-logout observation. An EMPTY while logged in is a genuine slot clear
	 * (offer collected) and drops the observation.
	 */
	List<GeDelta> onOfferChanged(int slot, GrandExchangeOffer offer, boolean loggedIn)
	{
		if (offer == null || offer.getState() == null)
		{
			return Collections.emptyList();
		}
		if (offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			if (loggedIn)
			{
				observedOffers.remove(slot);
			}
			return Collections.emptyList();
		}

		ObservedOffer current = new ObservedOffer(offer.getItemId(), offer.getQuantitySold(), offer.getSpent());
		ObservedOffer previous = observedOffers.get(slot);

		if (previous == null
			|| previous.itemId != current.itemId
			|| current.quantitySold < previous.quantitySold)
		{
			observedOffers.put(slot, current);
			return Collections.emptyList();
		}

		observedOffers.put(slot, current);

		int quantityDelta = current.quantitySold - previous.quantitySold;
		if (quantityDelta <= 0)
		{
			return Collections.emptyList();
		}

		GrandExchangeOfferState state = offer.getState();
		boolean buy = state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;

		GeDelta delta = new GeDelta(
			current.itemId,
			quantityDelta,
			offer.getPrice(),
			current.spent - previous.spent,
			buy);

		log.debug("GE {} fill on slot {}: item {} x{} for {} gp",
			buy ? "buy" : "sell", slot, current.itemId, quantityDelta, delta.coinsDelta);

		return Collections.singletonList(delta);
	}

	/**
	 * Records cost basis for items bought through the GE this session.
	 */
	void addBasis(int itemId, int quantity, long cost)
	{
		if (itemId <= 0 || quantity <= 0)
		{
			return;
		}
		costBasis.computeIfAbsent(itemId, k -> new ArrayDeque<>()).add(new BasisLot(quantity, cost));
	}

	/**
	 * Total basis quantity held for an item across all lots.
	 */
	int basisQuantity(int itemId)
	{
		Deque<BasisLot> lots = costBasis.get(itemId);
		if (lots == null)
		{
			return 0;
		}
		int total = 0;
		for (BasisLot lot : lots)
		{
			total += lot.quantity;
		}
		return total;
	}

	/**
	 * Decomposes a sell fill into session ledger entries using carried values.
	 * Consumption order: GE cost basis first, then session tracked gains, then
	 * untracked stock carried at its gross fill price (residual = GE tax only).
	 * Net proceeds are allocated pro-rata across portions; division remainders
	 * fall to the untracked portion so portions always sum to netProceeds.
	 *
	 * @param grossProceeds pre-tax coins for this fill ({@code getSpent()} delta)
	 */
	GeLedger settleSell(int itemId, int quantity, long grossProceeds, CoinFlowSession session)
	{
		return settleSell(itemId, quantity, grossProceeds, session, false);
	}

	/**
	 * Same as {@link #settleSell} with control over the untracked portion's
	 * carried value. When {@code untrackedAsIncome} is unset, untracked stock
	 * is carried at its gross proceeds share so the asset conversion nets to
	 * zero (residual = GE tax only). When set, untracked stock is carried at
	 * zero so the net proceeds share surfaces as income instead.
	 */
	GeLedger settleSell(int itemId, int quantity, long grossProceeds, CoinFlowSession session,
		boolean untrackedAsIncome)
	{
		return settle(itemId, quantity, grossProceeds,
			GrandExchangeTax.netProceeds(itemId, quantity, grossProceeds), session, untrackedAsIncome);
	}

	/**
	 * Settles a shop sale exactly like {@link #settleSell} but with no tax:
	 * net proceeds equal the coins received. When {@code untrackedAsIncome}
	 * is unset the untracked portion's residual is always zero, so selling
	 * pre-session (banked) stock to a shop records nothing — an asset
	 * conversion, matching the GE convention. When set, its share of the
	 * proceeds surfaces as income.
	 */
	GeLedger settleShopSell(int itemId, int quantity, long proceeds, CoinFlowSession session,
		boolean untrackedAsIncome)
	{
		return settle(itemId, quantity, proceeds, proceeds, session, untrackedAsIncome);
	}

	private GeLedger settle(int itemId, int quantity, long grossProceeds, long netProceeds,
		CoinFlowSession session, boolean untrackedAsIncome)
	{
		GeLedger ledger = new GeLedger();
		if (quantity <= 0)
		{
			return ledger;
		}

		long[] basis = consumeBasis(itemId, quantity);
		int basisQty = (int) basis[0];
		long basisCost = basis[1];

		CoinFlowSession.TrackedItem tracked = session != null ? session.getTrackedItems().get(itemId) : null;
		int trackedQty = tracked != null
			? (int) Math.min(quantity - basisQty, tracked.getRemainingQuantity())
			: 0;

		int untrackedQty = quantity - basisQty - trackedQty;

		long pBasis = netProceeds * basisQty / quantity;
		long pTracked = netProceeds * trackedQty / quantity;
		long pUntracked = netProceeds - pBasis - pTracked;
		if (untrackedQty == 0)
		{
			if (trackedQty > 0)
			{
				pTracked += pUntracked;
			}
			else
			{
				pBasis += pUntracked;
			}
			pUntracked = 0;
		}

		if (basisQty > 0)
		{
			long residual = pBasis - basisCost;
			ledger.netDelta += residual;
			if (residual > 0)
			{
				addCoinGain(ledger, residual);
			}
			else if (residual < 0)
			{
				addCoinExpense(ledger, -residual);
			}
		}

		if (trackedQty > 0)
		{
			addCoinGain(ledger, pTracked);
			ledger.deductions.put(itemId,
				new CoinFlowSession.TrackedItem(itemId, tracked.getName(), trackedQty, tracked.getPriceEach()));
			long carried = tracked.getRemainingQuantity() > 0
				? tracked.getRemainingValue() * trackedQty / tracked.getRemainingQuantity()
				: (long) trackedQty * tracked.getPriceEach();
			ledger.netDelta += pTracked - carried;
		}

		if (untrackedQty > 0)
		{
			long carried = untrackedAsIncome
				? 0
				: grossProceeds - (grossProceeds * basisQty / quantity) - (grossProceeds * trackedQty / quantity);
			long residual = pUntracked - carried;
			ledger.netDelta += residual;
			if (residual < 0)
			{
				ledger.expenses.merge(GrandExchangeTax.TAX_ITEM_ID,
					new CoinFlowSession.TrackedItem(GrandExchangeTax.TAX_ITEM_ID, GrandExchangeTax.TAX_ITEM_NAME, clampQty(-residual), 1L),
					(a, b) -> a.merge(b));
			}
			else if (residual > 0)
			{
				addCoinGain(ledger, residual);
			}
		}

		return ledger;
	}

	/**
	 * Reprices consumed supplies against held cost basis. Quantity covered by
	 * FIFO basis is charged at its actual purchase cost; any remainder keeps the
	 * expense's market price. Draining basis here keeps lots from being orphaned
	 * (and later mis-attributed to a sale) once the bought items are used up.
	 *
	 * <p>Because a {@link CoinFlowSession.TrackedItem} carries one price, a mix
	 * of basis-covered and market-priced units collapses to a rounded average.
	 *
	 * @param fractionalIds item ids whose expense quantity is in sub-units
	 *        (doses, portions) and therefore must not drain whole-item basis
	 */
	Map<Integer, CoinFlowSession.TrackedItem> repriceFromBasis(
		Map<Integer, CoinFlowSession.TrackedItem> expenses, Set<Integer> fractionalIds)
	{
		if (expenses == null || expenses.isEmpty() || costBasis.isEmpty())
		{
			return expenses;
		}

		Map<Integer, CoinFlowSession.TrackedItem> result = new HashMap<>(expenses);
		for (Map.Entry<Integer, CoinFlowSession.TrackedItem> entry : expenses.entrySet())
		{
			CoinFlowSession.TrackedItem item = entry.getValue();
			int qty = (int) Math.min(Integer.MAX_VALUE, item.getQuantity());
			if (qty <= 0 || !costBasis.containsKey(item.getItemId())
				|| (fractionalIds != null && fractionalIds.contains(entry.getKey())))
			{
				continue;
			}

			long[] basis = consumeBasis(item.getItemId(), qty);
			int basisQty = (int) basis[0];
			if (basisQty == 0)
			{
				continue;
			}

			long total = basis[1] + (long) (qty - basisQty) * item.getPriceEach();
			long priceEach = (total + qty / 2) / qty;
			result.put(entry.getKey(),
				new CoinFlowSession.TrackedItem(item.getItemId(), item.getName(), qty, priceEach));

			log.debug("Repriced supply from basis: {} x{} ({} from basis @ {} gp total) -> {} gp each",
				item.getName(), qty, basisQty, basis[1], priceEach);
		}
		return result;
	}

	/**
	 * Consumed-side cost basis waiting for the produced side of a set exchange
	 * that arrived split across container events, plus the mirror image:
	 * produced items seen before their consumed side. Basis is keyed by item
	 * id, so a late half can attach retroactively. Bounded by
	 * {@link #SET_BASIS_PENDING_TICKS} so a stalled stash cannot leak onto an
	 * unrelated later gain.
	 */
	private static final int SET_BASIS_PENDING_TICKS = 5;

	private long pendingSetExchangeCost = 0;
	private Map<Integer, Integer> pendingSetExchangeGains = null;
	private int pendingSetExchangeTick = -1;

	/**
	 * Moves cost basis across a clerk item-set exchange. Packing or unpacking a
	 * set is an asset recomposition, not a gain or loss, so basis held on the
	 * consumed side (the set when unpacking, the components when packing) is
	 * re-attached to the produced items — allocated pro-rata by market value so
	 * the totals still sum to the original cost and each piece later sells at
	 * its true margin. Only fires when the diff actually contains a set item
	 * (name check on either side) or completes a stashed half of a split
	 * conversion, leaving ordinary suppressed diffs alone.
	 */
	void transferSetExchangeBasis(Map<Integer, Integer> losses, Map<Integer, Integer> gains,
		ItemManager itemManager, int currentTick)
	{
		if (losses == null || gains == null)
		{
			return;
		}
		if (pendingSetExchangeTick >= 0 && currentTick - pendingSetExchangeTick > SET_BASIS_PENDING_TICKS)
		{
			clearPendingSetExchange();
		}
		if (losses.isEmpty() && gains.isEmpty())
		{
			// An empty diff is not conversion traffic — leave any stashed
			// split-conversion half alone.
			return;
		}

		// One-sided diffs may be halves of a conversion whose other half lands
		// in a separate container event. The call site is already scoped to
		// the itemsets window (interface open or just closed), so they
		// participate unconditionally: consumed-side basis is stashed for a
		// later produced side, and a produced side seen first is remembered so
		// a late consumed side can attach retroactively (basis is keyed by
		// item id, not inventory position).
		if (gains.isEmpty())
		{
			long cost = consumeConversionBasis(losses, itemManager);
			if (cost > 0)
			{
				pendingSetExchangeCost += cost;
				pendingSetExchangeTick = currentTick;
			}
			if (pendingSetExchangeCost > 0 && pendingSetExchangeGains != null)
			{
				allocateProducedBasis(pendingSetExchangeGains, pendingSetExchangeCost, itemManager);
				clearPendingSetExchange();
			}
			else if (cost <= 0 && pendingSetExchangeCost <= 0 && pendingSetExchangeGains != null)
			{
				// The produced side arrived earlier and the consumed side
				// carried no basis — conversion complete, nothing to move.
				clearPendingSetExchange();
			}
			return;
		}

		if (losses.isEmpty())
		{
			if (pendingSetExchangeCost > 0)
			{
				allocateProducedBasis(mergeGains(gains), pendingSetExchangeCost, itemManager);
				clearPendingSetExchange();
				return;
			}
			if (pendingSetExchangeGains == null)
			{
				pendingSetExchangeGains = new HashMap<>();
			}
			gains.forEach((id, qty) -> pendingSetExchangeGains.merge(id, qty, Integer::sum));
			pendingSetExchangeTick = currentTick;
			return;
		}

		// A full-diff (or pending-completing) conversion only counts when a
		// "... set" item actually participates — ordinary both-sides diffs in
		// the window keep their own accounting.
		boolean hasPending = pendingSetExchangeCost > 0 || pendingSetExchangeGains != null;
		if (!hasPending && !containsSetItem(losses, itemManager) && !containsSetItem(gains, itemManager))
		{
			return;
		}

		long totalCost = pendingSetExchangeCost + consumeConversionBasis(losses, itemManager);
		if (totalCost > 0)
		{
			allocateProducedBasis(mergeGains(gains), totalCost, itemManager);
		}
		clearPendingSetExchange();
	}

	/**
	 * Combines the diff's produced items with any stashed produced-side items
	 * from an earlier split event.
	 */
	private Map<Integer, Integer> mergeGains(Map<Integer, Integer> gains)
	{
		if (pendingSetExchangeGains == null)
		{
			return gains;
		}
		Map<Integer, Integer> merged = new HashMap<>(gains);
		pendingSetExchangeGains.forEach((id, qty) -> merged.merge(id, qty, Integer::sum));
		return merged;
	}

	private void clearPendingSetExchange()
	{
		pendingSetExchangeCost = 0;
		pendingSetExchangeGains = null;
		pendingSetExchangeTick = -1;
	}

	/**
	 * Drains cost basis from the consumed side of a conversion. When the
	 * losses contain a set item (unpacking), only the set's basis moves —
	 * unrelated losses sharing the diff keep theirs. When no set item is on
	 * the loss side (packing, or the consumed half of a split diff), every
	 * non-coin loss is a conversion input and its basis is consumed.
	 */
	private long consumeConversionBasis(Map<Integer, Integer> losses, ItemManager itemManager)
	{
		boolean lossHasSet = containsSetItem(losses, itemManager);
		long totalCost = 0;
		for (Map.Entry<Integer, Integer> e : losses.entrySet())
		{
			int id = itemManager != null ? itemManager.canonicalize(e.getKey()) : e.getKey();
			if (id == ItemID.COINS || (lossHasSet && !isSetItem(e.getKey(), itemManager)))
			{
				continue;
			}
			totalCost += consumeBasis(id, e.getValue())[1];
		}
		return totalCost;
	}

	/**
	 * Re-attaches consumed cost basis onto produced items, pro-rata by market
	 * value (equal shares when no market data). Coins are never a conversion
	 * product and must not absorb item cost basis.
	 */
	private void allocateProducedBasis(Map<Integer, Integer> gains, long totalCost, ItemManager itemManager)
	{
		List<Map.Entry<Integer, Integer>> entries = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : gains.entrySet())
		{
			int id = itemManager != null ? itemManager.canonicalize(e.getKey()) : e.getKey();
			if (id != ItemID.COINS)
			{
				entries.add(e);
			}
		}
		if (entries.isEmpty())
		{
			return;
		}

		long[] values = new long[entries.size()];
		long totalValue = 0;
		for (int i = 0; i < entries.size(); i++)
		{
			Map.Entry<Integer, Integer> e = entries.get(i);
			int id = itemManager != null ? itemManager.canonicalize(e.getKey()) : e.getKey();
			long price = itemManager != null ? Math.max(0L, itemManager.getItemPrice(id)) : 0L;
			values[i] = price * Math.max(0, e.getValue());
			totalValue += values[i];
		}

		long allocated = 0;
		for (int i = 0; i < entries.size(); i++)
		{
			Map.Entry<Integer, Integer> e = entries.get(i);
			int id = itemManager != null ? itemManager.canonicalize(e.getKey()) : e.getKey();
			long share = i == entries.size() - 1
				? totalCost - allocated
				: (totalValue > 0 ? totalCost * values[i] / totalValue : totalCost / entries.size());
			allocated += share;
			addBasis(id, Math.max(1, e.getValue()), share);
		}

		log.debug("Item-set exchange: moved {} gp of cost basis onto {} produced item(s)",
			totalCost, entries.size());
	}

	private static boolean containsSetItem(Map<Integer, Integer> diff, ItemManager itemManager)
	{
		for (int id : diff.keySet())
		{
			if (isSetItem(id, itemManager))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A Grand Exchange set item is named "... set", optionally with a variant
	 * suffix — "Rune armour set (lg)", "Dharok's armour set".
	 */
	private static boolean isSetItem(int rawId, ItemManager itemManager)
	{
		if (itemManager == null)
		{
			return false;
		}
		ItemComposition comp = itemManager.getItemComposition(itemManager.canonicalize(rawId));
		String name = comp != null ? comp.getName() : null;
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase(Locale.ROOT);
		return n.endsWith(" set") || (n.endsWith(")") && n.contains(" set ("));
	}

	void reset()
	{
		observedOffers.clear();
		costBasis.clear();
		clearPendingSetExchange();
	}

	/**
	 * A group of same-base potion bottles observed in an inventory diff.
	 * {@code doses} is the dose level of the bottle form (1-4); {@code quantity}
	 * is the number of bottles.
	 */
	public static final class PotionBottle
	{
		public final int itemId;
		public final int doses;
		public final int quantity;

		public PotionBottle(int itemId, int doses, int quantity)
		{
			this.itemId = itemId;
			this.doses = doses;
			this.quantity = quantity;
		}
	}

	/**
	 * Follows purchase cost basis as potions change dose level. Consumes basis
	 * for every lost bottle, redistributes the share still held in liquid to the
	 * gained bottle forms, and returns the cost attributable to the consumed
	 * doses.
	 *
	 * <p>This prevents a fully drunk bottle's basis from lingering and later
	 * being mis-attributed to the sale of an identical pre-session potion.
	 *
	 * @param lost lost bottle groups for one potion base
	 * @param gained gained bottle groups for the same potion base
	 * @param dosesConsumed net doses that left the player's possession
	 * @return {cost of basis-covered consumed doses, number of consumed doses covered by basis}
	 */
	public long[] reconcilePotionBasis(List<PotionBottle> lost, List<PotionBottle> gained, int dosesConsumed)
	{
		if (costBasis.isEmpty())
		{
			return new long[]{0, 0};
		}

		long totalBasisCost = 0;
		int totalLostDoses = 0;
		int basisDosesHeld = 0;
		for (PotionBottle p : lost)
		{
			totalLostDoses += p.doses * p.quantity;
			long[] basis = consumeBasis(p.itemId, p.quantity);
			totalBasisCost += basis[1];
			basisDosesHeld += p.doses * (int) basis[0];
		}
		if (totalBasisCost <= 0 || totalLostDoses <= 0)
		{
			return new long[]{0, 0};
		}

		int totalGainedDoses = 0;
		for (PotionBottle p : gained)
		{
			totalGainedDoses += p.doses * p.quantity;
		}

		// Cost follows the liquid: the share still held moves to the gained
		// dose forms, the rest belongs to the consumed doses.
		long retainedCost = totalBasisCost * Math.min(totalGainedDoses, totalLostDoses) / totalLostDoses;
		long allocated = 0;
		for (int i = 0; i < gained.size(); i++)
		{
			PotionBottle p = gained.get(i);
			long share = (i == gained.size() - 1 || totalGainedDoses <= 0)
				? retainedCost - allocated
				: retainedCost * p.doses * p.quantity / totalGainedDoses;
			if (share > 0)
			{
				addBasis(p.itemId, p.quantity, share);
			}
			allocated += share;
		}

		long consumedCost = totalBasisCost - allocated;
		int basisDosesConsumed = Math.min(dosesConsumed, basisDosesHeld);
		return new long[]{consumedCost, basisDosesConsumed};
	}

	/**
	 * Consumes up to maxQty of cost basis FIFO. Returns {consumedQty, cost}.
	 */
	private long[] consumeBasis(int itemId, int maxQty)
	{
		Deque<BasisLot> lots = costBasis.get(itemId);
		if (lots == null || maxQty <= 0)
		{
			return new long[]{0, 0};
		}

		int quantity = 0;
		long cost = 0;
		while (maxQty > 0 && !lots.isEmpty())
		{
			BasisLot lot = lots.peekFirst();
			int take = Math.min(maxQty, lot.quantity);
			long lotCost = take == lot.quantity
				? lot.remainingCost
				: lot.remainingCost * take / lot.quantity;
			lot.quantity -= take;
			lot.remainingCost -= lotCost;
			if (lot.quantity == 0)
			{
				lots.pollFirst();
			}
			quantity += take;
			cost += lotCost;
			maxQty -= take;
		}
		if (lots.isEmpty())
		{
			costBasis.remove(itemId);
		}
		return new long[]{quantity, cost};
	}

	private static int clampQty(long amount)
	{
		return (int) Math.min(Integer.MAX_VALUE, Math.max(0L, amount));
	}

	private static void addCoinGain(GeLedger ledger, long amount)
	{
		ledger.gains.merge(ItemID.COINS,
			new CoinFlowSession.TrackedItem(ItemID.COINS, "Coins", Math.max(0L, amount), 1L),
			(a, b) -> a.merge(b));
	}

	private static void addCoinExpense(GeLedger ledger, long amount)
	{
		ledger.expenses.merge(ItemID.COINS,
			new CoinFlowSession.TrackedItem(ItemID.COINS, "Coins", Math.max(0L, amount), 1L),
			(a, b) -> a.merge(b));
	}
}

package com.coinflow;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;

/**
 * Tracks open in-game interfaces (bank, GE, shops, etc.) to suppress inventory tracking
 * and signal re-baselines upon interface closures or scene transitions.
 */
@Slf4j
@Singleton
public class InterfaceTracker
{
	// ── Interface IDs that suppress tracking ─────────────────────────────
	static final Set<Integer> SUPPRESSED_INTERFACES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		// Bank & Deposit Boxes
		InterfaceID.BANKMAIN,
