			{
				return true;
			}
		}

		return false;
	}

	private final Map<Integer, Integer> cachedQuiverAmmoContents = new HashMap<>();

	/**
	 * Updates the cached Dizana's Quiver ammo contents.
	 */
	public synchronized void setQuiverAmmoContents(Map<Integer, Integer> items)
	{
		cachedQuiverAmmoContents.clear();
		if (items != null)
		{
			for (Map.Entry<Integer, Integer> entry : items.entrySet())
			{
				if (entry.getKey() != null && entry.getKey() > 0 && entry.getValue() != null && entry.getValue() > 0)
				{
					cachedQuiverAmmoContents.put(entry.getKey(), entry.getValue());
				}
			}
		}
	}

	/**
	 * Clears the cached Dizana's Quiver ammo contents (e.g. on death, session reset).
	 */
	public synchronized void clearQuiverAmmoContents()
	{
		cachedQuiverAmmoContents.clear();
	}

	/**
	 * Reads the current ammo and quantities stored inside Dizana's Quiver (container 879).
	 */
	public synchronized Map<Integer, Integer> getQuiverAmmoContents()
	{
		if (client != null)
		{
			ItemContainer container = client.getItemContainer(InventoryID.DIZANAS_QUIVER_AMMO);
			if (container != null && container.getItems() != null)
			{
				Map<Integer, Integer> map = new HashMap<>();
				for (Item item : container.getItems())
				{
					if (item != null && item.getId() > 0 && item.getQuantity() > 0)
					{
						map.merge(item.getId(), item.getQuantity(), Integer::sum);
					}
				}
				cachedQuiverAmmoContents.clear();
				cachedQuiverAmmoContents.putAll(map);
				return map;
			}
		}
		return new HashMap<>(cachedQuiverAmmoContents);
	}
}

package com.coinflow;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Shared item valuation: GE market price, then the fixed coin/platinum
 * values, then high alchemy as an estimate for untradeables.
 *
 * The HA fallback is skipped for {@link #UNALCHABLE_UNTRADEABLES}: every item
 * carries a nominal HA price in its composition even when it cannot be
 * alchemised, so untradeable items that also cannot be alched (or sold) have
 * no way to realize that value and must price at 0.
 */
public final class ItemPricing
{
	private ItemPricing() {}

	// Untradeable items that also cannot be alchemised — the HA fallback would
	// book phantom profit/spend. Canonical item ids only; only add entries
	// verified unalchable — wrongly listing an alchable item loses its real
	// value twice (0 at pickup, ~0 alch margin since the basis self-references).
	static final Set<Integer> UNALCHABLE_UNTRADEABLES = Collections.unmodifiableSet(new HashSet<>(java.util.Arrays.asList(
		// Blessed bone shards (Cam Torum calcified rocks / libation bowl) —
		// untradeable, unalchable; nominal HA price 10 gp is unrealizable.
		ItemID.BLESSED_BONE_SHARD,
		// Blessed bone statuettes (eagle/fox/buffalo, stealing valuables) —
		// untradeable, unalchable, nominal HA ~1,200 gp each.
		ItemID.VARLAMORE_BONE_STATUETTE01,
		ItemID.VARLAMORE_BONE_STATUETTE02,
		ItemID.VARLAMORE_BONE_STATUETTE03
	)));

	/**
	 * Whether the item can never carry value in any context — untradeable and
	 * unalchable. Such diffs are stripped before reconciliation (invisible to
	 * tracking, like minigame-only items).
	 */
	static boolean isValueless(int canonicalId)
	{
		return UNALCHABLE_UNTRADEABLES.contains(canonicalId);
	}

	/**
	 * Whether the item is untradeable and carries no market price — the
	 * population the HA fallback would otherwise value. Stripped from diffs
	 * when the Track Untradeable Items config is off; the value still surfaces
	 * if the item is later converted to cash (e.g. alched: the item loss is
	 * invisible, so the coins land as plain income).
	 */
	static boolean isUnpricedUntradeable(int canonicalId, ItemManager itemManager)
	{
		if (itemManager == null || itemManager.getItemPrice(canonicalId) > 0)
		{
			return false;
		}
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		return comp != null && !comp.isTradeable();
	}

	/**
	 * Realizable value of one item: GE price, fixed coin/platinum values, then
	 * high alchemy — or 0 for items that can never be converted to cash.
	 */
	public static long priceOf(int itemId, ItemManager itemManager)
	{
		if (itemId == ItemID.COINS)
		{
			return 1;
		}
		if (itemId == ItemID.PLATINUM)
		{
			return 1000;
		}
		if (itemManager == null)
		{
			return 0;
		}
		long price = itemManager.getItemPrice(itemId);
		if (price > 0)
		{
			return price;
		}
		if (UNALCHABLE_UNTRADEABLES.contains(itemManager.canonicalize(itemId)))
		{
			return 0;
		}
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null ? comp.getHaPrice() : 0;
	}
}

package com.coinflow;

import java.util.Locale;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

/**
 * Interprets menu clicks into cross-tick intents: drop intents, take clicks,
 * looting-bag deposits, container/charged-item interactions that need a
 * re-baseline, and skill-action ticks that bias diff attribution.
 */
@Slf4j
final class MenuIntentHandler
{
	private final CoinFlowPlugin plugin;

	MenuIntentHandler(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onMenuOptionClicked(MenuOptionClicked event)
	{
		plugin.recordPlayerActivity();
		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		String rawTarget = event.getMenuTarget();
		String target = rawTarget != null ? Text.removeTags(rawTarget).toLowerCase(Locale.ROOT) : "";
		int tick = plugin.client != null ? plugin.client.getTickCount() : 0;

		if ("Drop".equalsIgnoreCase(option) && event.getItemId() > 0)
		{
			int dropId = plugin.itemManager != null ? plugin.itemManager.canonicalize(event.getItemId()) : event.getItemId();
			plugin.recentDropIntents.put(dropId, tick);
		}

		if ("Take".equalsIgnoreCase(option))
		{
			int itemId = event.getId();
			int sceneX = event.getParam0();
			int sceneY = event.getParam1();
			plugin.deathTracker.recordTakeClick(
				plugin.itemManager != null ? plugin.itemManager.canonicalize(itemId) : itemId, tick);
			plugin.containerPickupTracker.recordTakeClick(itemId, sceneX, sceneY, tick);
		}
		else if ("Use".equalsIgnoreCase(option))
		{
			String lowerTarget = target.toLowerCase(Locale.ROOT);
			if (lowerTarget.contains("looting bag"))
			{
				int usedId = -1;
				if (plugin.client != null && plugin.client.getSelectedWidget() != null)
				{
					usedId = plugin.client.getSelectedWidget().getItemId();
				}
				String usedName = "";
				if (target.contains("->"))
				{
					String beforeArrow = target.split("->")[0].trim();
					if (beforeArrow.startsWith("use "))
					{
						beforeArrow = beforeArrow.substring(4).trim();
					}
					usedName = beforeArrow;
				}
				plugin.lastLootingBagDepositTick = tick;
				plugin.lastLootingBagDepositItemId = usedId;
				plugin.lastLootingBagDepositItemName = usedName;
				log.debug("Looting bag deposit intent via Use: name '{}', id {}", usedName, usedId);
			}
			else if (ActionClassifiers.isFarmingPatchAction(lowerTarget))
			{
				plugin.lastFarmingActionTick = tick;
				plugin.lastSkillXpTicks.put(Skill.FARMING, tick);
				log.debug("Farming patch action clicked ('{}' on '{}'), recording farming action tick", option, target);
			}
			else if (ActionClassifiers.isBirdHouseAction(lowerTarget))
			{
				plugin.lastSkillXpTicks.put(Skill.HUNTER, tick);
				log.debug("Birdhouse action clicked ('{}' on '{}'), recording hunter action tick", option, target);
			}
			else if (target.contains("tinderbox") || target.contains("bruma torch"))
			{
				plugin.lastTinderboxActionTick = tick;
			}
			else if (lowerTarget.contains("leprechaun") || lowerTarget.contains("phials")
				|| lowerTarget.contains("piles"))
			{
				plugin.lastNotingServiceTick = tick;
			}
			else if (lowerTarget.contains("->"))
			{
				String[] parts = lowerTarget.split("->");
				String dest = parts.length > 1 ? parts[1].trim() : "";
				if (ActionClassifiers.isContainerOrChargedItemTarget(dest)
					|| (ActionClassifiers.isContainerOrChargedItemTarget(parts[0].trim()) && (dest.contains("bank") || dest.contains("deposit"))))
				{
					plugin.weaponChargeTracker.recordUseSource(parts[0]);
					plugin.interfaceTracker.setNeedsRebaseline(true);
					plugin.rebaselineGraceTicks = 3;
					log.debug("Container/charged item Use action clicked ('{}'), scheduling rebaseline", target);
				}
			}
		}
		else if ("Fill".equalsIgnoreCase(option) || "Empty".equalsIgnoreCase(option)
			|| "Empty basket".equalsIgnoreCase(option)
			|| "Open".equalsIgnoreCase(option) || "Close".equalsIgnoreCase(option)
			|| "Charge".equalsIgnoreCase(option) || "Uncharge".equalsIgnoreCase(option)
			|| "Unload".equalsIgnoreCase(option)
			|| "Loot".equalsIgnoreCase(option) || "Search".equalsIgnoreCase(option))
		{
			String lowerTarget = target.toLowerCase(Locale.ROOT);
			if (ActionClassifiers.isContainerOrChargedItemTarget(lowerTarget))
			{
				if ("Unload".equalsIgnoreCase(option) && lowerTarget.contains("blowpipe"))
				{
					plugin.weaponChargeTracker.clearLoadedDarts();
				}
				plugin.interfaceTracker.setNeedsRebaseline(true);
				plugin.rebaselineGraceTicks = 3;
				log.debug("Container/charged item action clicked ('{}' on '{}'), scheduling rebaseline", option, target);
			}
			// "Open"/"Loot"/"Search" on an inventory pack item (casket, impling
			// jar, supply crate) consumes the item for its contents. CC_OP +
			// itemId restricts this to inventory clicks — object opens (STASH
			// units, chests) are GAME_OBJECT actions and must not mint intents.
			else if (("Open".equalsIgnoreCase(option) || "Loot".equalsIgnoreCase(option)
				|| "Search".equalsIgnoreCase(option))
				&& event.getMenuAction() == net.runelite.api.MenuAction.CC_OP
				&& event.getItemId() > 0)
			{
				int openId = plugin.itemManager != null ? plugin.itemManager.canonicalize(event.getItemId()) : event.getItemId();
				plugin.recentOpenIntents.put(openId, tick);
				log.debug("Open/loot intent on inventory item '{}' (id {}), recording", target, openId);
			}
		}
		else if (option.toLowerCase(Locale.ROOT).startsWith("collect")
			&& (plugin.interfaceTracker.isTrackingSuppressed() || target.toLowerCase(Locale.ROOT).contains("grand exchange")))
		{
			plugin.interfaceTracker.setNeedsRebaseline(true);
			plugin.rebaselineGraceTicks = 3;
			log.debug("Collect action clicked ('{}' on '{}'), scheduling rebaseline", option, target);
		}
		else if (option.toLowerCase(Locale.ROOT).startsWith("store") || option.toLowerCase(Locale.ROOT).startsWith("deposit"))
		{
			if (plugin.client != null && plugin.client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1)
			{
				ItemContainer inv = plugin.client.getItemContainer(InventoryID.INV);
				if (inv != null && plugin.hasLootingBag(inv))
				{
					plugin.lastLootingBagDepositTick = tick;
					plugin.lastLootingBagDepositItemId = event.getItemId();
					plugin.lastLootingBagDepositItemName = target;
					log.debug("Looting bag deposit intent via Store/Deposit: {} on {} (id {})", option, target, event.getItemId());
				}
			}
		}
		else if ("note".equalsIgnoreCase(option) || "un-note".equalsIgnoreCase(option))
		{
			plugin.lastNotingServiceTick = tick;
		}
		else if (plugin.lastLootingBagDepositTick > 0 && tick - plugin.lastLootingBagDepositTick <= 15
			&& ("one".equalsIgnoreCase(option) || "five".equalsIgnoreCase(option) || "all".equalsIgnoreCase(option) || "x".equalsIgnoreCase(option)))
		{
			plugin.lastLootingBagDepositTick = tick;
			log.debug("Looting bag deposit amount selected: {}", option);
		}
		else if ("Light".equalsIgnoreCase(option) || "Burn".equalsIgnoreCase(option))
		{
			plugin.lastTinderboxActionTick = tick;
		}
		else if ("Bury".equalsIgnoreCase(option) || "Scatter".equalsIgnoreCase(option))
		{
			plugin.lastSkillXpTicks.put(Skill.PRAYER, tick);
		}
		else if ("Plant".equalsIgnoreCase(option) || "Treat".equalsIgnoreCase(option) || "Cure".equalsIgnoreCase(option)
			|| "Harvest".equalsIgnoreCase(option) || "Pick".equalsIgnoreCase(option) || "Rake".equalsIgnoreCase(option)
			|| "Clear".equalsIgnoreCase(option) || "Prune".equalsIgnoreCase(option) || "Check-health".equalsIgnoreCase(option)
			|| ActionClassifiers.isFarmingPatchAction(target))
		{
			plugin.lastFarmingActionTick = tick;
			plugin.lastSkillXpTicks.put(Skill.FARMING, tick);
		}
		else if ("Build".equalsIgnoreCase(option))
		{
			plugin.lastSkillXpTicks.put(Skill.CONSTRUCTION, tick);
		}
		else if ("Reanimate".equalsIgnoreCase(option) || ("Cast".equalsIgnoreCase(option) && target.contains("ensouled")))
		{
			plugin.lastSkillXpTicks.put(Skill.PRAYER, tick);
			plugin.lastSkillXpTicks.put(Skill.MAGIC, tick);
		}
		else if ("Cast".equalsIgnoreCase(option) && target.contains("alchemy"))
		{
			plugin.lastAlchActionTick = tick;
		}
		else if (option.toLowerCase(Locale.ROOT).contains("alchemy"))
		{
			plugin.lastAlchActionTick = tick;
		}
		else if (option.toLowerCase(Locale.ROOT).startsWith("craft"))
		{
			plugin.lastSkillXpTicks.put(Skill.RUNECRAFT, tick);
			plugin.lastSkillXpTicks.put(Skill.CRAFTING, tick);
		}
		else if ("Set-trap".equalsIgnoreCase(option) || "Lay".equalsIgnoreCase(option))
		{
			plugin.lastSkillXpTicks.put(Skill.HUNTER, tick);
		}
	}
}

package com.coinflow;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;

/**
 * Quarantine rules for minigames that issue temporary items or replace the
 * player's inventory. Two kinds of entries:
 *
 * <ul>
 *   <li>{@link #MINIGAME_ONLY_ITEMS} — item ids that cannot legally exist
 *   outside their minigame (Castle Wars supplies, Barbarian Assault eggs,
 *   NMZ potions, GOTR cells, ...). Any inventory diff containing one is
 *   definitionally non-economic, so it is stripped before reconciliation —
 *   both the grant and the exit strip disappear. Persistent reward items
 *   (fighter torso, Castle Wars tickets/decorative armour, Soul Wars spoils,
 *   guardian essence) are deliberately excluded.</li>
 *   <li>{@link #MINIGAME_HUD_COMPONENTS} — interface components whose HUD is only
 *   visible while inside a minigame that sits on the normal overworld map
 *   (where region suppression's ~2-region load halo would blind nearby
 *   players' tracking). Evaluated by live widget visibility at diff time,
 *   not by WidgetLoaded/Closed events, so groups that stay loaded-but-hidden
 *   cannot wedge tracking off permanently.</li>
 * </ul>
 *
 * If Jagex ever reuses one of these item ids for a real item, that item
 * silently stops being tracked — the ids are minigame-scoped, so this is a
 * low but nonzero risk.
 */
public final class MinigameQuarantine
{
	private MinigameQuarantine() {}

	// ── Minigame-only item ids ─────────────────────────────────────────
	// Anything here is invisible to tracking in every context.
	static final Set<Integer> MINIGAME_ONLY_ITEMS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		// Castle Wars — table supplies, flags, and catapult kit. NOT the
		// tickets, cloaks, or decorative armour (real rewards).
		ItemID.CASTLEWARS_BANDAGES,
		ItemID.CASTLEWARS_BARRICADE,
		ItemID.CASTLEWARS_TOOLKIT,
		ItemID.CASTLEWARS_CATAPULT_ROCK,
		ItemID.CASTLEWARS_EXPLOSIVES_POTION,
		ItemID.CASTLEWARS_CLIMBING_ROPE,
		ItemID.CASTLEWARS_CATAPULT,
		ItemID.CASTLEWARS_SARADOMIN_BANNER,
		ItemID.CASTLEWARS_ZAMORAK_BANNER,
		ItemID.CASTLEWARS_MANUAL, // TODO verify — may persist outside the arena
		// "Castlewars brew" (respawn-room potion) — the gameval constant is
		// misleadingly named *_SKILL_POTION. All four doses.
		ItemID._4DOSE_CASTLEWARS_SKILL_POTION,
		ItemID._3DOSE_CASTLEWARS_SKILL_POTION,
		ItemID._2DOSE_CASTLEWARS_SKILL_POTION,
		ItemID._1DOSE_CASTLEWARS_SKILL_POTION,
		// Temporary "Rune pouch" issued on entry (Poll 83 update) — provides
		// free runes in-arena and is stripped on exit.
		ItemID.CASTLEWARS_RUNE_REPLACEMENT,
		// Arena ammunition (tables/issue) — CW-only variants of arrows/bolts.
		ItemID.CASTLEWARS_ARROW,
		ItemID.CASTLEWARS_BOLT,
		ItemID.CASTLEWARS_ARROWS2,
		ItemID.CASTLEWARS_ARROWS3,
		ItemID.CASTLEWARS_ARROWS4,
		ItemID.CASTLEWARS_ARROWS5,
		ItemID.CASTLEWARS_BOLTS2,
		ItemID.CASTLEWARS_BOLTS3,
		ItemID.CASTLEWARS_BOLTS4,
		ItemID.CASTLEWARS_BOLTS5,
		ItemID.CASTLEWARS_NO0,
		ItemID.CASTLEWARS_NO1,
		ItemID.CASTLEWARS_NO2,
		ItemID.CASTLEWARS_NO3,
		ItemID.CASTLEWARS_NO4,
		ItemID.CASTLEWARS_NO5,
		ItemID.CASTLEWARS_NO6,
		ItemID.CASTLEWARS_NO7,
		ItemID.CASTLEWARS_NO8,
		ItemID.CASTLEWARS_NO9,

		// Soul Wars — bandages, buff potions, barricades, explosives, team
		// capes (worn, which is why the WORN diff is filtered too), and the
		// tutorial-side items. NOT spoils of war (real reward crates).
