		ItemID.BARBASSAULT_POISION_01,
		ItemID.BARBASSAULT_POISION_02,
		ItemID.BARBASSAULT_POISION_03,
		ItemID.BARBASSAULT_VIAL_04_FULL,
		ItemID.BARBASSAULT_VIAL_04_3Q,
		ItemID.BARBASSAULT_VIAL_04_HALF,
		ItemID.BARBASSAULT_VIAL_04_1Q,
		ItemID.BARBASSAULT_VIAL_04_EMPTY,
		ItemID.BARBASSAULT_SPIKES,
		ItemID.BARBASSAULT_SCROLL, // TODO verify — may persist outside the waves
		ItemID.BARBASSAULT_QUEEN_GUIDEBOOK, // TODO verify — may persist outside the waves

		// Guardians of the Rift — cells crumble when leaving the Temple of
		// the Eye. Guardian essence persists and stays tracked.
		ItemID.GOTR_CELL_UNCHARGED,
		ItemID.GOTR_CELL_TIER1,
		ItemID.GOTR_CELL_TIER2,
		ItemID.GOTR_CELL_TIER3,
		ItemID.GOTR_CELL_TIER4,

		// Nightmare Zone — rumble potions usable only inside a dream.
		ItemID.NZONE1DOSEOVERLOADPOTION,
		ItemID.NZONE2DOSEOVERLOADPOTION,
		ItemID.NZONE3DOSEOVERLOADPOTION,
		ItemID.NZONE4DOSEOVERLOADPOTION,
		ItemID.NZONE1DOSEABSORPTIONPOTION,
		ItemID.NZONE2DOSEABSORPTIONPOTION,
		ItemID.NZONE3DOSEABSORPTIONPOTION,
		ItemID.NZONE4DOSEABSORPTIONPOTION,

		// Tithe Farm — provided seeds, fruit, and fertiliser never leave the
		// instance. Reward gear (TITHE_REWARD_*) stays tracked.
		ItemID.HOSIDIUS_TITHE_SEED_A,
		ItemID.HOSIDIUS_TITHE_SEED_B,
		ItemID.HOSIDIUS_TITHE_SEED_C,
		ItemID.HOSIDIUS_TITHE_FRUIT_A,
		ItemID.HOSIDIUS_TITHE_FRUIT_B,
		ItemID.HOSIDIUS_TITHE_FRUIT_C,
		ItemID.HOSIDIUS_TITHE_FERTILISER // TODO verify — may persist outside
	)));

	// ── Minigame HUD interface components ──────────────────────────────
	// Packed component ids (each interface's UNIVERSE/UNIVERSAL child) so
	// lookups use the single-arg component-based getWidget. While one of
	// these is visible the player is inside an overworld-area minigame
	// where region suppression would bleed onto neighbours.
	// TODO verify each group only shows while actually inside the minigame
	// (watch for "Interface opened" debug lines appearing at login — that
	// would mean the group is persistently loaded and cannot be trusted even
	// with the visibility check, since isHidden() may report stale state).
	static final Set<Integer> MINIGAME_HUD_COMPONENTS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		// Tempoross — tools are real item ids, so only a HUD/region signal
		// can quarantine them; the cove shares map space with Unkah's docks.
		InterfaceID.TemporossHud.UNIVERSE,
		InterfaceID.TemporossLobbyHud.UNIVERSE,
		// The Gauntlet — belt-and-suspenders alongside the region entry; the
		// HUD is what actually quarantines if the seeded region id is wrong.
		InterfaceID.GauntletOverlay.UNIVERSE,
		InterfaceID.GauntletMap.UNIVERSE,
		// Last Man Standing — BR_LOBBYOVERLAY is the lobby panel, BR_OVERLAY
		// the in-match HUD. Verified in game: the lobby HUD latches on every
		// lobby login and suppression persists through the whole match. This
		// is the primary LMS coverage — the lobby's region halo shares real
		// Ferox Enclave chunks, and matches rotate between several arena
		// maps, so neither end can be fully covered by region ids.
		InterfaceID.BrLobbyoverlay.UNIVERSE,
		InterfaceID.BrOverlay.UNIVERSAL
		// Candidates pending in-game capture: SOUL_WARS_GAME (375),
		// BARBASSAULT_OVER_* (485-488), CASTLEWARS_STATUS_OVERLAY_* (58/59).
		// Those minigames are already covered by the item denylist, so HUD
		// suppression adds little — enable only if gaps appear.
	)));

	static boolean isMinigameOnlyItem(int canonicalId)
	{
		return MINIGAME_ONLY_ITEMS.contains(canonicalId);
	}
}

package com.coinflow;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.QuantityFormatter;

/**
 * Applies reconciliation output to the session: prices raw gains, reprices
 * supply expenses against FIFO cost basis, publishes the new
 * {@link CoinFlowSession}, fires gold-drop notifications, evaluates goal
 * completion, and owns the ignored-items filter set.
 */
@Slf4j
final class SessionApplier
{
	private final CoinFlowPlugin plugin;

	SessionApplier(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	/**
	 * Applies GE settlement entries to the session and pops a gold drop for the
	 * realized net delta (flip margin, drift correction) when positive.
	 */
	void applyGeLedger(GrandExchangeTracker.GeLedger ledger, int soldItemId)
	{
		if (ledger.isEmpty() || plugin.session == null)
		{
			return;
		}

		Map<Integer, CoinFlowSession.TrackedItem> expenses =
			(plugin.config != null && !plugin.config.trackSpent()) ? Collections.emptyMap() : ledger.expenses;
		plugin.session = plugin.session.withGainsLossesAndExpenses(ledger.gains, ledger.deductions, expenses);

		if (plugin.config != null && plugin.config.showGoldDrops() && plugin.goldDropOverlay != null
			&& ledger.netDelta > 0 && ledger.netDelta >= plugin.config.goldDropMinThreshold())
		{
			String dropText = "+" + QuantityFormatter.quantityToStackSize(ledger.netDelta) + " gp";
			plugin.goldDropOverlay.addDrop(dropText, soldItemId, 0);
		}
	}

	void processGains(Map<Integer, Integer> rawGains)
	{
		processGainsLossesAndExpenses(rawGains, Collections.emptyMap(), Collections.emptyMap(), -1);
	}

	/**
	 * Processes raw item gains and supply expenses atomically:
	 * looks up prices, updates the session, and triggers gold drops for positive gains.
	 */
	void processGainsAndExpenses(Map<Integer, Integer> rawGains, Map<Integer, CoinFlowSession.TrackedItem> supplyExpenses)
	{
		processGainsLossesAndExpenses(rawGains, Collections.emptyMap(), supplyExpenses, -1);
	}

	/**
	 * Processes raw item gains, dropped item deductions, and supply expenses atomically:
	 * looks up prices, updates the session, and triggers gold drops for positive gains.
	 */
	void processGainsLossesAndExpenses(
		Map<Integer, Integer> rawGains,
		Map<Integer, CoinFlowSession.TrackedItem> droppedGainsDeductions,
		Map<Integer, CoinFlowSession.TrackedItem> supplyExpenses)
	{
		processGainsLossesAndExpenses(rawGains, droppedGainsDeductions, supplyExpenses, -1);
	}

	void processGainsLossesAndExpenses(
		Map<Integer, Integer> rawGains,
		Map<Integer, CoinFlowSession.TrackedItem> droppedGainsDeductions,
		Map<Integer, CoinFlowSession.TrackedItem> supplyExpenses,
		int alchedDropItemId)
	{
		processGainsLossesAndExpenses(rawGains, droppedGainsDeductions, supplyExpenses, alchedDropItemId, Collections.emptySet());
	}

	void processGainsLossesAndExpenses(
		Map<Integer, Integer> rawGains,
		Map<Integer, CoinFlowSession.TrackedItem> droppedGainsDeductions,
		Map<Integer, CoinFlowSession.TrackedItem> supplyExpenses,
		int alchedDropItemId,
		Set<Integer> exemptProductIds)
	{
		processGainsLossesAndExpenses(rawGains, droppedGainsDeductions, supplyExpenses, alchedDropItemId,
			exemptProductIds, Collections.emptySet());
	}

	/**
	 * Processes raw item gains, dropped item deductions, and supply expenses atomically:
	 * looks up prices, updates the session, and triggers gold drops for positive gains,
	 * skipping generic coins gold drop if an alchemy drop was already displayed.
	 *
	 * @param fractionalExpenseIds expense ids excluded from whole-item cost basis
	 *        repricing: dose/portion expenses and drop expenses
	 */
	void processGainsLossesAndExpenses(
		Map<Integer, Integer> rawGains,
		Map<Integer, CoinFlowSession.TrackedItem> droppedGainsDeductions,
		Map<Integer, CoinFlowSession.TrackedItem> supplyExpenses,
		int alchedDropItemId,
		Set<Integer> exemptProductIds,
		Set<Integer> fractionalExpenseIds)
	{
		Map<Integer, CoinFlowSession.TrackedItem> trackedGains = new HashMap<>();

		for (Map.Entry<Integer, Integer> entry : rawGains.entrySet())
		{
			int rawItemId = entry.getKey();
			int quantity = entry.getValue();

			// Canonicalize: resolve noted items, placeholders, and worn items to base ID (Fixes Bug 6)
			int itemId = plugin.itemManager.canonicalize(rawItemId);

			// Check ignored items list
			String itemName = plugin.getItemName(itemId);
			if (isIgnored(itemName))
			{
				continue;
			}

			// Skip trash / empty byproduct containers (e.g. pie dish, bowl, empty vial), unless intentionally produced
			if (ConsumableRegistry.isByproduct(itemName) && (exemptProductIds == null || !exemptProductIds.contains(itemId)))
			{
				continue;
			}

			// Look up price (Fixes Bug 7: coins and platinum tokens)
			long price = ItemPricing.priceOf(itemId, plugin.itemManager);

			CoinFlowSession.TrackedItem trackedItem =
				new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price);
			trackedGains.merge(itemId, trackedItem,
				(existing, added) -> existing.merge(added));

			log.debug("Gained: {} x{} @ {} gp each = {} gp",
				itemName, quantity, price, (long) quantity * price);
		}

		// Drain basis even when spent tracking is off or the expense is ignored so
		// lots never outlive the items they priced.
		Map<Integer, CoinFlowSession.TrackedItem> repricedExpenses =
			plugin.grandExchangeTracker.repriceFromBasis(supplyExpenses, fractionalExpenseIds);
		Map<Integer, CoinFlowSession.TrackedItem> effectiveExpenses =
			(plugin.config != null && !plugin.config.trackSpent()) ? Collections.emptyMap()
				: filterIgnoredExpenses(repricedExpenses);

		if (!trackedGains.isEmpty() || !droppedGainsDeductions.isEmpty() || !effectiveExpenses.isEmpty())
		{
			plugin.session = plugin.session.withGainsLossesAndExpenses(trackedGains, droppedGainsDeductions, effectiveExpenses);

			// Gold drops are kept purely for positive income to prevent screen clutter
			if (plugin.config.showGoldDrops() && plugin.goldDropOverlay != null && !trackedGains.isEmpty())
			{
				int stackIndex = 0;
				for (CoinFlowSession.TrackedItem item : trackedGains.values())
				{
					// If a gold drop was already displayed specifically for an alched item, skip showing coins for it
					if (alchedDropItemId != -1 && item.getItemId() == ItemID.COINS)
					{
						continue;
					}

					long value = item.getTotalValue();
					if (value >= plugin.config.goldDropMinThreshold())
					{
						String dropText = "+" + QuantityFormatter.quantityToStackSize(value) + " gp";
						plugin.goldDropOverlay.addDrop(dropText, item.getItemId(), stackIndex * 18);
						stackIndex++;
					}
				}
			}
		}
	}

	/**
	 * Drops ignored items from a supply-expense batch. Synthetic GP rows
	 * ("Death", "GE Tax", "Blast Furnace coffer" — see
	 * {@link CoinFlowSession#isSyntheticRowId}) are exempt by id — their
	 * backing item names ("Skull", coin piles) are real items a player may
	 * legitimately ignore without wanting to hide bookkeeping rows.
	 */
	private Map<Integer, CoinFlowSession.TrackedItem> filterIgnoredExpenses(
		Map<Integer, CoinFlowSession.TrackedItem> expenses)
	{
		if (plugin.ignoredItemNames == null || plugin.ignoredItemNames.isEmpty() || expenses.isEmpty())
		{
			return expenses;
		}
		Map<Integer, CoinFlowSession.TrackedItem> filtered = new HashMap<>();
		for (Map.Entry<Integer, CoinFlowSession.TrackedItem> entry : expenses.entrySet())
		{
			int itemId = entry.getKey();
			CoinFlowSession.TrackedItem expense = entry.getValue();
			if (!CoinFlowSession.isSyntheticRowId(itemId)
				&& (isIgnored(expense.getName()) || isIgnored(plugin.getItemName(itemId))))
			{
				continue;
			}
			filtered.put(itemId, expense);
		}
		return filtered;
	}

	/**
	 * Checks if an item name is in the user's ignored items list.
	 */
	boolean isIgnored(String itemName)
	{
		return ConsumableRegistry.isIgnoredName(itemName, plugin.ignoredItemNames);
	}

	/**
	 * Rebuilds the ignored items list from config.
	 */
	void rebuildFilterSet()
	{
		String ignored = plugin.config.ignoredItems();
		if (ignored == null || ignored.trim().isEmpty())
		{
			plugin.ignoredItemNames = new HashSet<>();
		}
		else
		{
			plugin.ignoredItemNames = new HashSet<>();
			for (String name : ignored.split(","))
			{
				String trimmed = name.trim().toLowerCase();
				if (!trimmed.isEmpty())
				{
					plugin.ignoredItemNames.add(trimmed);
				}
			}
		}
	}

	/**
	 * Checks if an active goal was reached and triggers a single notification.
	 */
	void checkGoalNotification()
	{
		long goalAmount = CoinFlowSession.parseGoalAmount(plugin.config.goalAmount());
		if (goalAmount <= 0)
		{
			plugin.goalCompletedNotified = false;
			return;
		}

		long currentProfit = (plugin.session != null && plugin.config != null && !plugin.config.trackSpent())
			? plugin.session.getGrossProfit()
			: (plugin.session != null ? plugin.session.getTotalProfit() : 0L);

		if (plugin.session != null && currentProfit >= goalAmount)
		{
			if (!plugin.goalCompletedNotified)
			{
				plugin.goalCompletedNotified = true;
				if (plugin.config.notifyOnGoal())
				{
					String label = CoinFlowSession.cleanGoalName(plugin.config.goalName());
					String goalTitle = label.isEmpty() ? "Target GP" : label;
					plugin.notifier.notify("Coin Flow: Goal reached for " + goalTitle + " (" + QuantityFormatter.quantityToStackSize(goalAmount) + " gp)!");
				}
			}
		}
	}
}

package com.coinflow;

import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Skill;
import net.runelite.client.events.ConfigChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.events.OverlayMenuClicked;

/**
 * Session lifecycle: login/logout transitions, baselining, session resets,
 * transient-state clears, and config-change sanitization. All mutations run
 * on the client thread (resetSession marshals itself there when called from
 * the Swing EDT).
 */
@Slf4j
final class SessionLifecycleManager
{
	private final CoinFlowPlugin plugin;

	SessionLifecycleManager(CoinFlowPlugin plugin)
	{
		this.plugin = plugin;
	}

	void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		plugin.interfaceTracker.onGameStateChanged(state, plugin.snapshotInitialized);
		plugin.blastFurnaceTracker.onGameStateChanged(state);

		if (state == GameState.LOGGED_IN)
		{
			checkAccount();
			if (plugin.session != null)
			{
				plugin.session = plugin.session.withResumedState();
			}
			if (plugin.interfaceTracker.isNeedsRebaseline() && plugin.client != null && plugin.clientThread != null)
			{
				plugin.clientThread.invokeLater(() ->
				{
					plugin.takeBaseline();
					plugin.interfaceTracker.setNeedsRebaseline(false);
				});
			}
		}
		else if (state != GameState.LOADING)
		{
			plugin.snapshotInitialized = false;
			plugin.lootingBagInitialized = false;
			// Logout/hop while a death is still settling: discard the pending
			// capture rather than risk mispricing the loss. The recovery
			// ledger survives — reclaiming often happens after a relog.
			plugin.deathTracker.discardPending();
			// Charge any accrued coffer drain while the session is still
			// alive, then drop the coffer baseline — the next read after
			// relog only re-baselines.
			plugin.blastFurnaceTracker.onLeftLoggedIn();
			resetTransientTrackingState();
		}
	}

	/**
	 * Sessions, GE cost basis and the death recovery ledger belong to one
	 * account. A different account logging in resets everything so account
	 * A's observations can never book fills or recoveries for account B.
	 * Called from the account-hash event, on LOGGED_IN, and at the top of
	 * {@link CoinFlowPlugin#onGrandExchangeOfferChanged} — offer events can
	 * arrive before the game-state transition finishes. Idempotent; a hash
	 * of -1 (logout / not yet identified) is ignored.
	 */
	void checkAccount()
	{
		if (plugin.client == null)
		{
			return;
		}
		long hash = plugin.client.getAccountHash();
		if (hash == -1)
		{
			return;
		}
		if (plugin.lastAccountHash != -1 && hash != plugin.lastAccountHash)
		{
			log.info("Account switched, resetting Coin Flow session");
			resetSession();
		}
		plugin.lastAccountHash = hash;
	}

	void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(CoinFlowConfig.CONFIG_GROUP))
		{
			if ("goldDropMinThreshold".equals(event.getKey()))
			{
				String val = event.getNewValue();
				if (val != null)
				{
					String sanitized = val.replaceAll(CoinFlowInputFilter.DIGITS_ONLY, "");
					if (!sanitized.equals(val))
					{
						int safeVal = 0;
						if (!sanitized.isEmpty())
						{
							try
							{
								safeVal = (int) Math.min(Integer.MAX_VALUE, Math.max(0, Long.parseLong(sanitized)));
							}
							catch (NumberFormatException ignored)
							{
								safeVal = 0;
							}
						}
						plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "goldDropMinThreshold", safeVal);
					}
				}
			}
			else if ("idleTimeoutMinutes".equals(event.getKey()))
			{
				String val = event.getNewValue();
				if (val != null)
				{
					String sanitized = val.replaceAll(CoinFlowInputFilter.DIGITS_ONLY, "");
					if (!sanitized.equals(val))
					{
						int safeVal = 2;
						if (!sanitized.isEmpty())
						{
							try
							{
								safeVal = (int) Math.max(1, Math.min(60, Long.parseLong(sanitized)));
							}
							catch (NumberFormatException ignored)
							{
								safeVal = 2;
							}
						}
						plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "idleTimeoutMinutes", safeVal);
					}
				}
			}
			else if ("goalAmount".equals(event.getKey()))
			{
				plugin.goalCompletedNotified = false;
				String val = event.getNewValue();
				if (val != null)
				{
					String sanitized = val.replaceAll(CoinFlowInputFilter.TARGET_GP, "");
					if (!sanitized.equals(val))
					{
						plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "goalAmount", sanitized);
					}
				}
			}
			else if ("goalName".equals(event.getKey()))
			{
				String val = event.getNewValue();
				if (val != null)
				{
					String sanitized = val.replaceAll(CoinFlowInputFilter.GOAL_NAME, "");
					if (!sanitized.equals(val))
					{
						plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "goalName", sanitized);
					}
				}
			}
			else if ("ignoredItems".equals(event.getKey()))
			{
				String val = event.getNewValue();
				if (val != null)
				{
					String sanitized = val.replaceAll(CoinFlowInputFilter.IGNORED_ITEMS, "");
					if (!sanitized.equals(val))
					{
						plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "ignoredItems", sanitized);
					}
				}
			}

			if ("showGoldDrops".equals(event.getKey()) && !plugin.config.showGoldDrops() && plugin.goldDropOverlay != null)
			{
				plugin.goldDropOverlay.clear();
			}
			plugin.rebuildFilterSet();
			if (plugin.panel != null)
			{
				plugin.panel.onConfigChanged();
			}
			log.debug("Config changed for {}, reloaded ignored items", CoinFlowConfig.CONFIG_GROUP);
		}
	}

	/**
	 * Takes a baseline snapshot of the current inventory without triggering a diff.
	 */
	void takeBaseline()
	{
		if (plugin.client == null || plugin.client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		ItemContainer invContainer = plugin.client.getItemContainer(InventoryID.INV);
		if (invContainer != null)
		{
			ItemContainer bagContainer = plugin.client.getItemContainer(net.runelite.api.gameval.InventoryID.LOOTING_BAG);
			if (bagContainer != null)
			{
				Map<Integer, Integer> bagItems = new HashMap<>();
				if (bagContainer.getItems() != null)
				{
					for (Item item : bagContainer.getItems())
					{
						if (item != null && item.getId() > 0 && item.getQuantity() > 0)
						{
							bagItems.merge(item.getId(), item.getQuantity(), Integer::sum);
						}
					}
				}
				plugin.getSnapshotService().setLootingBagContents(bagItems);
				plugin.lootingBagInitialized = true;
			}

			ItemContainer quiverContainer = plugin.client.getItemContainer(InventoryID.DIZANAS_QUIVER_AMMO);
			if (quiverContainer != null)
			{
				Map<Integer, Integer> quiverItems = new HashMap<>();
				if (quiverContainer.getItems() != null)
				{
					for (Item item : quiverContainer.getItems())
					{
						if (item != null && item.getId() > 0 && item.getQuantity() > 0)
						{
							quiverItems.merge(item.getId(), item.getQuantity(), Integer::sum);
						}
					}
				}
				plugin.getSnapshotService().setQuiverAmmoContents(quiverItems);
			}

			plugin.previousInventorySnapshot = plugin.takeInventorySnapshot(invContainer);
			plugin.snapshotInitialized = true;
			log.debug("Baseline taken on startup ({} items)", plugin.previousInventorySnapshot.getItems().size());
		}

		ItemContainer equipContainer = plugin.client.getItemContainer(InventoryID.WORN);
		if (equipContainer != null)
		{
			plugin.previousEquipmentSnapshot = plugin.takeSnapshot(equipContainer);
		}
		plugin.pendingWornAmmoExpenses.clear();
		plugin.recentlyUnequippedItems.clear();
		plugin.recentlyEquippedItems.clear();
		plugin.gearSwapItemTicks.clear();

		for (Skill skill : Skill.values())
		{
			try
			{
				int xp = plugin.client.getSkillExperience(skill);
				plugin.previousSkillXp.put(skill, xp);
			}
			catch (Exception ignored)
			{
			}
		}
	}

	/**
	 * Clears all transient tracking buffers, pending container pickups, click intents, and activity timers.
	 */
	void resetTransientTrackingState()
	{
		plugin.recentlyUnequippedItems.clear();
		plugin.recentlyEquippedItems.clear();
		plugin.gearSwapItemTicks.clear();
		plugin.recentlyDroppedItems.clear();
		plugin.recentlyDroppedOwnedItems.clear();
		plugin.recentlyExpensedDrops.clear();
		plugin.droppedItemTicks.clear();
		plugin.containerPickupTracker.resetTransient();
		plugin.matchedUnequipsThisTick.clear();
		plugin.pendingWornAmmoExpenses.clear();
		plugin.weaponChargeTracker.reset();
		plugin.lastSkillingGemId = -1;
		plugin.lastSkillingGemTick = -100;
		if (plugin.getSnapshotService() != null)
		{
			plugin.getSnapshotService().clearLootingBagPendingItems();
			plugin.getSnapshotService().clearQuiverAmmoContents();
		}
		plugin.activityMonitor.reset();
		plugin.lastTinderboxActionTick = -100;
		plugin.lastFiremakingChatTick = -100;
		plugin.lastAlchActionTick = -100;
		plugin.lastFarmingActionTick = -100;
		plugin.lastFarmingChatTick = -100;
		plugin.lastLootingBagDepositTick = -100;
		plugin.lastLootingBagDepositItemId = -1;
		plugin.lastLootingBagDepositItemName = null;
		plugin.lastNotingServiceTick = -100;
		plugin.recentDropIntents.clear();
		plugin.recentOpenIntents.clear();
		// The deployed-cannon ledger survives logout (a deployed cannon does
		// too — reclaimable from Nulodion), but the loaded-balls estimate does
		// not: ball state on relog is unknown, so fewer reversals are safer
		// than phantom ones.
		plugin.cannonTracker.clearLoadedBalls();
		// Held coffer coins and dispenser-rescue entries never survive a
		// boundary — a held loss expiring after relog would book as spend.
		plugin.blastFurnaceTracker.clearTransient();
		plugin.rebaselineGraceTicks = 0;
		plugin.minigameHudVisible = false;
		plugin.minigameHudGraceTicks = 0;
		if (plugin.goldDropOverlay != null)
		{
			plugin.goldDropOverlay.clear();
		}
	}

	/**
	 * Resets the current session. Called from the panel or keybind — possibly on
	 * the Swing EDT — so the state mutation is marshalled onto the client
	 * thread, where all other session/track bookkeeping runs.
	 */
	void resetSession()
	{
		if (plugin.clientThread != null && (plugin.client == null || !plugin.client.isClientThread()))
		{
			plugin.clientThread.invokeLater(this::resetSessionOnClientThread);
			return;
		}
		resetSessionOnClientThread();
	}

	private void resetSessionOnClientThread()
	{
		if (log.isDebugEnabled() && plugin.session != null)
		{
			log.debug("Session reset: active={}s total={}s gross={} spent={} idle={}",
				plugin.session.getActiveTime().getSeconds(), plugin.session.getTotalInGameTime().getSeconds(),
				plugin.session.getGrossProfit(), plugin.session.getTotalExpenses(), plugin.session.isIdle());
		}
		plugin.session = CoinFlowSession.createNew();
		plugin.goalCompletedNotified = false;
		plugin.grandExchangeTracker.reset();
		plugin.deathTracker.reset();
		plugin.cannonTracker.reset();
		plugin.blastFurnaceTracker.resetSession();
		if (plugin.client != null && plugin.client.getGameState() == GameState.LOGGED_IN)
		{
			plugin.grandExchangeTracker.seed(plugin.client.getGrandExchangeOffers());
		}
		plugin.lootingBagInitialized = false;
		resetTransientTrackingState();
		// Invalidate the baseline immediately: any inventory event before the deferred
		// takeBaseline() runs must rebaseline rather than diff against the stale pre-reset snapshot.
		plugin.snapshotInitialized = false;
		plugin.previousInventorySnapshot = null;
		plugin.previousEquipmentSnapshot = null;
		if (plugin.client != null && plugin.client.getGameState() == GameState.LOGGED_IN)
		{
			// Already on the client thread by now — re-baseline immediately.
			takeBaseline();
		}
		if (plugin.panel != null)
		{
			plugin.panel.updateSession(plugin.session);
		}
		log.info("Coin Flow session reset");
	}

	/**
	 * Removes a tracked row from the active session (a gain or an expense).
	 * Called from the item-row context menu on the Swing EDT, so the session
	 * mutation is marshalled onto the client thread like {@link #resetSession}.
	 */
	void removeSessionItem(int itemId, boolean isExpense)
	{
		if (plugin.clientThread != null && (plugin.client == null || !plugin.client.isClientThread()))
		{
			plugin.clientThread.invokeLater(() -> removeSessionItemOnClientThread(itemId, isExpense));
			return;
		}
		removeSessionItemOnClientThread(itemId, isExpense);
	}

	/**
	 * Removes a tracked row from both ledgers — used by "Ignore", where the
	 * same item may appear as both loot and a supply expense.
	 */
	private void removeSessionItemCompletely(int itemId)
	{
		if (plugin.session == null)
		{
			return;
		}
		plugin.session = plugin.session.withoutItem(itemId);
		afterSessionItemRemoval(itemId);
	}

	private void removeSessionItemOnClientThread(int itemId, boolean isExpense)
	{
		if (plugin.session == null)
		{
			return;
		}
		plugin.session = plugin.session.withoutItem(itemId, isExpense);
		afterSessionItemRemoval(itemId);
	}

	/**
	 * Post-removal bookkeeping: drop stale pending-drop ledgers for the item
	 * (a pickup of a removed row must never reverse an expense or restore a
	 * deduction that no longer exists), re-arm the goal notification if the
	 * removal dropped profit below the target, and refresh the panel.
	 */
	private void afterSessionItemRemoval(int itemId)
	{
		plugin.recentlyDroppedItems.remove(itemId);
		plugin.recentlyDroppedOwnedItems.remove(itemId);
		plugin.recentlyExpensedDrops.remove(itemId);

		long goalAmount = CoinFlowSession.parseGoalAmount(plugin.config != null ? plugin.config.goalAmount() : null);
		if (goalAmount > 0 && plugin.session != null)
		{
			long currentProfit = (plugin.config != null && !plugin.config.trackSpent())
				? plugin.session.getGrossProfit() : plugin.session.getTotalProfit();
			if (currentProfit < goalAmount)
			{
				plugin.goalCompletedNotified = false;
			}
		}

		if (plugin.panel != null)
		{
			plugin.panel.updateSession(plugin.session);
		}
	}

	/**
	 * Adds an item to the ignored-items config and removes it from the active
	 * session. Fractional expense rows (" (dose)" / " (portion)") are
	 * normalized to their base item name first so ignoring a dose row ignores
	 * the underlying potion. Called from the item-row context menu on the
	 * Swing EDT; config writes are EDT-safe, the session removal marshals to
	 * the client thread.
	 */
	void ignoreItem(int itemId, String itemName)
	{
		String clean = ConsumableRegistry.canonicalIgnoreName(itemName)
			.replaceAll(CoinFlowInputFilter.IGNORED_ITEMS, "").trim();
		if (!clean.isEmpty() && plugin.configManager != null)
		{
			String existing = plugin.config != null ? plugin.config.ignoredItems() : null;
			boolean alreadyListed = false;
			if (existing != null && !existing.trim().isEmpty())
			{
				for (String name : existing.split(","))
				{
					if (name.trim().equalsIgnoreCase(clean))
					{
						alreadyListed = true;
						break;
					}
				}
			}
			if (!alreadyListed)
			{
				String updated = (existing == null || existing.trim().isEmpty())
					? clean
					: existing.trim() + ", " + clean;
				plugin.configManager.setConfiguration(CoinFlowConfig.CONFIG_GROUP, "ignoredItems", updated);
				plugin.rebuildFilterSet();
				log.debug("Added '{}' to ignored items", clean);
			}
		}

		if (plugin.clientThread != null && (plugin.client == null || !plugin.client.isClientThread()))
		{
			plugin.clientThread.invokeLater(() -> removeSessionItemCompletely(itemId));
		}
		else
		{
			removeSessionItemCompletely(itemId);
		}
	}

	/**
	 * Handles right-click menu actions on the Coin Flow HUD overlay. Only
	 * custom {@link MenuAction#RUNELITE_OVERLAY} entries are handled here —
	 * RUNELITE_OVERLAY_CONFIG ("Configure") is consumed by the client itself,
	 * which {@link CoinFlowPlugin#openConfiguration()} also relies on.
	 */
	void onOverlayMenuClicked(OverlayMenuClicked event)
	{
		if (plugin.overlay == null || event.getOverlay() != plugin.overlay || event.getEntry() == null
			|| event.getEntry().getMenuAction() != MenuAction.RUNELITE_OVERLAY)
		{
			return;
		}
		String option = event.getEntry().getOption();
		if (CoinFlowOverlay.MENU_RESET.equals(option))
		{
			resetSession();
		}
		else if (CoinFlowOverlay.MENU_VIEW_SUMMARY.equals(option))
		{
			CoinFlowSession session = plugin.session;
			if (plugin.panel != null && session != null)
			{
				plugin.panel.openSessionSummary(session);
			}
		}
	}
}

