		Assert.assertTrue(plugin.ignoredItemNames.contains("coal"));
		Assert.assertTrue(plugin.getSession().getTrackedItems().isEmpty());
		Assert.assertTrue(plugin.getSession().getTrackedExpenses().isEmpty());
