		plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV,
			mockContainer(InventoryID.INV, ItemID.COINS, net)));

		Assert.assertEquals(-HELM_TAX, plugin.getSession().getTotalProfit());
