	 */
	@Test
	public void wornMinigameItem_isIgnored()
	{
		fireInv(ItemID.COINS, 50_000);
		fireWorn(SW_CAPE, 1);
		fireWorn();

		Assert.assertEquals(0L, plugin.session.getTotalProfit());
		Assert.assertEquals(0L, plugin.session.getTotalExpenses());
