package com.coinflow;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

import static com.coinflow.TestHelpers.gains;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for {@link ShopTracker}: coin-delta detection of shop buys/sells,
 * cost-basis recording on buys, carried-value settlement on sells, and
 * suppression of non-coin diffs while a shop is open.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class ShopTrackerTest
{
	private static final int SHARK = 385;
	private static final int HELM = 11497;
	private static final int NOTED_SHARK = 386;
	private static final int BOOK = 9003;

	private GrandExchangeTracker tradeTracker;
	private ShopTracker shopTracker;
	private ItemManager itemManager;
	private CoinFlowSession session;

	@Before
	public void setUp()
	{
		tradeTracker = new GrandExchangeTracker();
		shopTracker = new ShopTracker(tradeTracker);
		session = CoinFlowSession.createNew();
		itemManager = mock(ItemManager.class);
		when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
	}

	private GrandExchangeTracker.GeLedger reconcile(Map<Integer, Integer> gains, Map<Integer, Integer> losses)
	{
		return shopTracker.reconcileDiff(gains, losses, session, itemManager, Collections.<String>emptySet(), false);
	}

	private GrandExchangeTracker.GeLedger reconcileAsIncome(Map<Integer, Integer> gains, Map<Integer, Integer> losses)
	{
		return shopTracker.reconcileDiff(gains, losses, session, itemManager, Collections.<String>emptySet(), true);
	}

	private static Map<Integer, Integer> map(int... idQtyPairs)
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < idQtyPairs.length; i += 2)
		{
			map.put(idQtyPairs[i], idQtyPairs[i + 1]);
		}
		return map;
	}

	private static CoinFlowSession.TrackedItem coins(Map<Integer, CoinFlowSession.TrackedItem> m)
	{
		return m.get(ItemID.COINS);
	}

	// ── Buys ────────────────────────────────────────────────────────────

	@Test
	public void buy_recordsCostBasisAndNoSessionEntries()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(SHARK, 10), map(ItemID.COINS, 5000));

		Assert.assertTrue(ledger.isEmpty());
		Assert.assertEquals(10, tradeTracker.basisQuantity(SHARK));
	}

	@Test
	public void buy_multipleItemTypes_recordsBasisForEach()
	{
		reconcile(
			map(SHARK, 10, HELM, 2), map(ItemID.COINS, 120000));

		Assert.assertEquals(10, tradeTracker.basisQuantity(SHARK));
		Assert.assertEquals(2, tradeTracker.basisQuantity(HELM));
	}

	@Test
	public void coinLossWithoutItemGain_recordsNothing()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			Collections.<Integer, Integer>emptyMap(), map(ItemID.COINS, 5000));

		Assert.assertTrue(ledger.isEmpty());
		Assert.assertEquals(0, tradeTracker.basisQuantity(SHARK));
	}

	@Test
	public void buy_untradeableItem_expensesInsteadOfBasis()
	{
		ItemComposition bookComp = mock(ItemComposition.class);
		when(bookComp.isTradeable()).thenReturn(false);
		when(bookComp.getName()).thenReturn("Security book");
		when(itemManager.getItemComposition(BOOK)).thenReturn(bookComp);

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(BOOK, 1), map(ItemID.COINS, 2));

		Assert.assertEquals(0, tradeTracker.basisQuantity(BOOK));
		Assert.assertEquals(2, ledger.expenses.get(BOOK).getTotalValue());
		Assert.assertEquals(-2L, ledger.netDelta);
	}

	@Test
	public void buy_mixedBasket_onlyUntradeableExpensed()
	{
		ItemComposition bookComp = mock(ItemComposition.class);
		when(bookComp.isTradeable()).thenReturn(false);
		when(bookComp.getName()).thenReturn("Security book");
		when(itemManager.getItemComposition(BOOK)).thenReturn(bookComp);
		ItemComposition sharkComp = mock(ItemComposition.class);
		when(sharkComp.isTradeable()).thenReturn(true);
		when(itemManager.getItemComposition(SHARK)).thenReturn(sharkComp);

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(SHARK, 10, BOOK, 1), map(ItemID.COINS, 1100));

		// Weighted split (prices unstubbed -> weight = qty): shark 1000, book 100
		Assert.assertEquals(10, tradeTracker.basisQuantity(SHARK));
		Assert.assertEquals(0, tradeTracker.basisQuantity(BOOK));
		Assert.assertEquals(100, ledger.expenses.get(BOOK).getTotalValue());
		Assert.assertEquals(-100L, ledger.netDelta);
	}

	@Test
	public void buy_nullComposition_keepsBasis()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(BOOK, 1), map(ItemID.COINS, 2));

		Assert.assertTrue(ledger.isEmpty());
		Assert.assertEquals(1, tradeTracker.basisQuantity(BOOK));
	}

	@Test
	public void buy_zeroCostShare_noExpenseRow()
	{
		ItemComposition bookComp = mock(ItemComposition.class);
		when(bookComp.isTradeable()).thenReturn(false);
		when(itemManager.getItemComposition(BOOK)).thenReturn(bookComp);
		when(itemManager.getItemPrice(SHARK)).thenReturn(10000L);
		ItemComposition sharkComp = mock(ItemComposition.class);
		when(sharkComp.isTradeable()).thenReturn(true);
		when(itemManager.getItemComposition(SHARK)).thenReturn(sharkComp);

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(SHARK, 10, BOOK, 1), map(ItemID.COINS, 100));

		// Book's pro-rata share rounds to 0: no expense row, no basis lot
		Assert.assertNull(ledger.expenses.get(BOOK));
		Assert.assertEquals(0, tradeTracker.basisQuantity(BOOK));
	}

	// ── Sells ───────────────────────────────────────────────────────────

	@Test
	public void sell_trackedItem_realizesActualProceeds()
	{
		session = session.withGains(gains(SHARK, "Shark", 10, 1000));

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 6000), map(SHARK, 10));

		Assert.assertEquals(6000, coins(ledger.gains).getQuantity());
		Assert.assertEquals(10, ledger.deductions.get(SHARK).getQuantity());
		Assert.assertEquals(1000, ledger.deductions.get(SHARK).getPriceEach());
		Assert.assertEquals(-4000L, ledger.netDelta);
	}

	@Test
	public void sell_basisItem_realizesMargin()
	{
		tradeTracker.addBasis(SHARK, 10, 8000);

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 9000), map(SHARK, 10));

		Assert.assertEquals(0, tradeTracker.basisQuantity(SHARK));
		Assert.assertEquals(1000, coins(ledger.gains).getQuantity());
		Assert.assertEquals(1000L, ledger.netDelta);
	}

	@Test
	public void sell_basisItemBelowCost_realizesLoss()
	{
		tradeTracker.addBasis(SHARK, 10, 8000);

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 5000), map(SHARK, 10));

		Assert.assertEquals(3000, coins(ledger.expenses).getQuantity());
		Assert.assertEquals(-3000L, ledger.netDelta);
	}

	@Test
	public void sell_untrackedItem_recordsNothing()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 4000), map(HELM, 1));

		Assert.assertTrue(ledger.isEmpty());
	}

	// ── Stock sales as income ───────────────────────────────────────────

	@Test
	public void sell_untrackedItemAsIncome_recordsProceedsAsGain()
	{
		GrandExchangeTracker.GeLedger ledger = reconcileAsIncome(
			map(ItemID.COINS, 4000), map(HELM, 1));

		Assert.assertEquals(4000, coins(ledger.gains).getQuantity());
		Assert.assertEquals(4000L, ledger.netDelta);
	}

	@Test
	public void sellAsIncome_basisAndUntracked_marginPlusIncome()
	{
		tradeTracker.addBasis(SHARK, 5, 4000);

		GrandExchangeTracker.GeLedger ledger = reconcileAsIncome(
			map(ItemID.COINS, 10000), map(SHARK, 10));

		// 5 basis: 5000 net - 4000 cost = 1000 gain; 5 untracked: 5000 income
		Assert.assertEquals(0, tradeTracker.basisQuantity(SHARK));
		Assert.assertEquals(6000, coins(ledger.gains).getQuantity());
		Assert.assertEquals(6000L, ledger.netDelta);
	}

	@Test
	public void sellAsIncome_trackedItem_unchanged()
	{
		session = session.withGains(gains(SHARK, "Shark", 10, 1000));

		GrandExchangeTracker.GeLedger ledger = reconcileAsIncome(
			map(ItemID.COINS, 6000), map(SHARK, 10));

		Assert.assertEquals(6000, coins(ledger.gains).getQuantity());
		Assert.assertEquals(10, ledger.deductions.get(SHARK).getQuantity());
		Assert.assertEquals(1000, ledger.deductions.get(SHARK).getPriceEach());
		Assert.assertEquals(-4000L, ledger.netDelta);
	}

	@Test
	public void coinGainWithoutItemLoss_recordsNothing()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 4000), Collections.<Integer, Integer>emptyMap());

		Assert.assertTrue(ledger.isEmpty());
	}

	// ── Non-coin diffs are suppressed ───────────────────────────────────

	@Test
	public void nonCoinDiff_suppressed()
	{
		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(SHARK, 5), map(HELM, 1));

		Assert.assertTrue(ledger.isEmpty());
		Assert.assertEquals(0, tradeTracker.basisQuantity(SHARK));
	}

	// ── Canonicalization ────────────────────────────────────────────────

	@Test
	public void sell_notedItem_canonicalizesToBaseId()
	{
		when(itemManager.canonicalize(NOTED_SHARK)).thenReturn(SHARK);
		session = session.withGains(gains(SHARK, "Shark", 5, 1000));

		GrandExchangeTracker.GeLedger ledger = reconcile(
			map(ItemID.COINS, 2500), map(NOTED_SHARK, 5));

		Assert.assertEquals(2500, coins(ledger.gains).getQuantity());
		Assert.assertEquals(5, ledger.deductions.get(SHARK).getQuantity());
	}
}

package com.coinflow;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Shared utilities for CoinFlow unit tests.
 */
public final class TestHelpers
{
	private TestHelpers() {}

	/**
	 * Builds an InventorySnapshot from interleaved (itemId, qty) pairs.
	 * <pre>snapshot(1234, 5, 5678, 10)</pre> produces {1234→5, 5678→10}.
	 * The varargs length must be even.
	 */
	public static InventorySnapshot snapshot(int... idQtyPairs)
	{
		if (idQtyPairs.length % 2 != 0)
		{
			throw new IllegalArgumentException("Arguments must be interleaved id/qty pairs");
		}
		int len = idQtyPairs.length / 2;
		int[] ids = new int[len];
		int[] qtys = new int[len];
		for (int i = 0; i < idQtyPairs.length; i += 2)
		{
			ids[i / 2] = idQtyPairs[i];
			qtys[i / 2] = idQtyPairs[i + 1];
		}
		return InventorySnapshot.fromArrays(ids, qtys);
	}

	/**
	 * Builds a single-entry gains map suitable for passing to
	 * {@link CoinFlowSession#withGains(Map)}.
	 */
	public static Map<Integer, CoinFlowSession.TrackedItem> gains(
		int id, String name, int qty, long priceEach)
	{
		return Collections.singletonMap(
			id, new CoinFlowSession.TrackedItem(id, name, qty, priceEach));
	}

	/**
	 * Builds a multi-entry gains map from interleaved
	 * (id, qty, priceEach) triples.
	 */
	public static Map<Integer, CoinFlowSession.TrackedItem> gainsMulti(
		String name, long... idQtyPriceTuples)
	{
		if (idQtyPriceTuples.length % 3 != 0)
		{
			throw new IllegalArgumentException("Arguments must be interleaved id/qty/price triples");
		}
		Map<Integer, CoinFlowSession.TrackedItem> map = new HashMap<>();
		for (int i = 0; i < idQtyPriceTuples.length; i += 3)
		{
			int id = (int) idQtyPriceTuples[i];
			int qty = (int) idQtyPriceTuples[i + 1];
			long price = idQtyPriceTuples[i + 2];
			map.put(id, new CoinFlowSession.TrackedItem(id, name, qty, price));
		}
		return map;
	}

	/**
	 * Simulates {@code ticks} game ticks on the session, each spaced by the
	 * real elapsed wall clock time between calls. Use a small number of ticks
	 * to verify structural behavior (idle flag, field invariants) without
	 * requiring precise timing.
	 */
	public static CoinFlowSession simulateTicks(
		CoinFlowSession session, int ticks, int idleTimeoutMinutes)
	{
		for (int i = 0; i < ticks; i++)
		{
			session = session.tick(idleTimeoutMinutes);
		}
		return session;
	}

	/**
	 * Returns the total value sum across all tracked items.
	 * Used to verify the invariant: sum(TrackedItem.totalValue) == session.totalProfit
	 * when all gains come from the same price point.
	 */
	public static long sumBreakdownValues(CoinFlowSession session)
	{
		long sum = 0;
		for (CoinFlowSession.TrackedItem item : session.getTrackedItems().values())
		{
			sum += item.getTotalValue();
		}
		return sum;
	}
}

package com.coinflow;

import org.junit.Assert;
import org.junit.Test;

public class VersionTest
{
	@Test
	public void testVersionNotNull()
	{
		String version = Version.getVersion();
		Assert.assertNotNull("Version should not be null", version);
		Assert.assertFalse("Version should not be empty", version.isEmpty());
		Assert.assertFalse("Version should not contain unresolved placeholder", version.contains("${"));
	}

	@Test
	public void testFormattedVersion()
	{
		String formatted = Version.getFormattedVersion();
		Assert.assertNotNull("Formatted version should not be null", formatted);
		Assert.assertTrue("Formatted version should start with 'v'", formatted.startsWith("v"));
	}
}

package com.coinflow;

import java.util.Map;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Assert;
import org.junit.Test;

public class WeaponChargeTrackerTest
{
	private static void seed(WeaponChargeTracker tracker, int varbitId, int initialCharges)
	{
		tracker.onVarbitChanged(varbitId, initialCharges, false, 0);
	}

	// ---- Attack-triggered weapons ----

	@Test
	public void tridentCast_recordsRunesAndCoins()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackGraphic(1251, "Trident of the seas", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.CHAOSRUNE).intValue());
		Assert.assertEquals(1, spent.get(ItemID.DEATHRUNE).intValue());
		Assert.assertEquals(5, spent.get(ItemID.FIRERUNE).intValue());
		Assert.assertEquals(10, spent.get(ItemID.COINS).intValue());
	}

	@Test
	public void swampTridentCast_consumesZulrahsScaleNotCoins()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackGraphic(665, "Trident of the swamp", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.CHAOSRUNE).intValue());
		Assert.assertEquals(1, spent.get(ItemID.DEATHRUNE).intValue());
		Assert.assertEquals(5, spent.get(ItemID.FIRERUNE).intValue());
		Assert.assertEquals(1, spent.get(ItemID.SNAKEBOSS_SCALE).intValue());
		Assert.assertNull(spent.get(ItemID.COINS));
	}

	@Test
	public void seasGraphic_doesNotTriggerForSwamp()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackGraphic(1251, "Trident of the swamp", 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void shadowCast_recordsChaosAndSoul()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackGraphic(2125, "Tumeken's shadow", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(5, spent.get(ItemID.CHAOSRUNE).intValue());
		Assert.assertEquals(2, spent.get(ItemID.SOULRUNE).intValue());
	}

	@Test
	public void sanguinestiCast_recordsBloodRunesViaCastAnimation()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackAnimation(AnimationID.HUMAN_CASTWAVE_STAFF, "Sanguinesti staff", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(3, spent.get(ItemID.BLOODRUNE).intValue());
	}

	@Test
	public void crawsBowShot_recordsEtherViaBowAnimation()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackAnimation(AnimationID.HUMAN_BOW, "Craw's bow", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void scytheAttack_recordsBloodRunesAndFractionalVial()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		for (int i = 0; i < 100; i++)
		{
			tracker.onAttackAnimation(AnimationID.SCYTHE_OF_VITUR_ATTACK, "Scythe of vitur", i);
		}

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(200, spent.get(ItemID.BLOODRUNE).intValue());
		Assert.assertEquals(1, spent.get(ItemID.VIAL_BLOOD).intValue());
	}

	@Test
	public void scytheAnimationWithUnrelatedWeapon_recordsNothing()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackAnimation(AnimationID.SCYTHE_OF_VITUR_ATTACK, "Dragon scimitar", 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void chainmaceAttack_recordsEtherViaChainmaceAnimation()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackAnimation(AnimationID.WILD_CAVE_CHAINMACE_CRUSH, "Viggora's chainmace", 1);
		tracker.onAttackAnimation(AnimationID.WILD_CAVE_CHAINMACE_STAB, "Ursine chainmace", 2);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void chainmaceVarbitDelta_matchingAttack_isNotDoubleCounted()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);

		tracker.onAttackAnimation(AnimationID.WILD_CAVE_CHAINMACE_CRUSH, "Ursine chainmace", 5);
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 99, true, 6);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void bowAnimationWithUnrelatedWeapon_recordsNothing()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackAnimation(AnimationID.HUMAN_BOW, "Magic shortbow", 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void attackGraphicWithNoWeapon_recordsNothing()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onAttackGraphic(1251, null, 1);
		tracker.onAttackGraphic(1251, "", 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void bowfaShots_accumulateIntoWholeShards()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		for (int i = 0; i < 150; i++)
		{
			tracker.onAttackGraphic(1888, "Bow of faerdhinen", i);
		}

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.PRIF_CRYSTAL_SHARD).intValue());
	}

	@Test
	public void blowpipe_recordsScalesAndLastLoadedDartType()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("Rune dart");

		for (int i = 0; i < 30; i++)
		{
			tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", i);
		}

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(20, spent.get(ItemID.SNAKEBOSS_SCALE).intValue());
		Assert.assertEquals(30, spent.get(ItemID.RUNE_DART).intValue());
	}

	@Test
	public void blowpipeDartRecovery_reducesDartSpend()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("Dragon dart");
		tracker.setDartRecoveryRate(0.80);

		for (int i = 0; i < 10; i++)
		{
			tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", i);
		}

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.DRAGON_DART).intValue());
	}

	@Test
	public void blowpipeWithoutLoadedDart_recordsScalesOnly()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		for (int i = 0; i < 3; i++)
		{
			tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", i);
		}

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.SNAKEBOSS_SCALE).intValue());
		Assert.assertEquals(1, spent.size());
	}

	@Test
	public void recordUseSource_ignoresNonDarts()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("Rune dart");
		tracker.recordUseSource("Chaos rune");
		tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", 1);

		Assert.assertTrue(tracker.drain().containsKey(ItemID.RUNE_DART));
	}

	@Test
	public void recordUseSource_stripsUseMenuPrefix()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("use rune dart");
		tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", 1);

		Assert.assertTrue(tracker.drain().containsKey(ItemID.RUNE_DART));
	}

	// ---- Attack/varbit deduplication ----

	@Test
	public void varbitDeltaMatchingRecentAttack_isNotDoubleCounted()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);

		// Attack fires, then the same charge drop arrives via the varbit next tick
		tracker.onAttackAnimation(AnimationID.HUMAN_BOW, "Craw's bow", 5);
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 99, true, 6);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void varbitDeltaLargerThanRecentAttacks_countsRemainder()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);

		tracker.onAttackAnimation(AnimationID.HUMAN_BOW, "Craw's bow", 5);
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 97, true, 6);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(3, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void staleAttackDedupe_doesNotSuppressLaterVarbitDelta()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);

		tracker.onAttackAnimation(AnimationID.HUMAN_BOW, "Craw's bow", 5);
		// Varbit drop long after the attack was expensed -> counts fully
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 99, true, 20);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void tridentVarbitAlone_recordsCastCost()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_TRIDENT_OF_THE_SEAS_QUANTITY, 500);

		tracker.onVarbitChanged(VarbitID.CHARGES_TRIDENT_OF_THE_SEAS_QUANTITY, 498, true, 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.CHAOSRUNE).intValue());
		Assert.assertEquals(20, spent.get(ItemID.COINS).intValue());
	}

	// ---- Varbit-tracked items ----

	@Test
	public void wildernessWeaponVarbit_recordsEther()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);

		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 93, true, 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(7, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void ringOfSufferingFractional_convertsToRecoilRings()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_RING_OF_SUFFERING_QUANTITY, 400);

		tracker.onVarbitChanged(VarbitID.CHARGES_RING_OF_SUFFERING_QUANTITY, 320, true, 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(2, spent.get(ItemID.RING_OF_RECOIL).intValue());
	}

	@Test
	public void chargeIncrease_isRechargeNotExpense()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_TOME_OF_FIRE_QUANTITY, 100);

		tracker.onVarbitChanged(VarbitID.CHARGES_TOME_OF_FIRE_QUANTITY, 2600, true, 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void firstObservation_establishesBaselineOnly()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onVarbitChanged(VarbitID.CHARGES_BONECRUSHER_QUANTITY, 50, true, 1);

		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void suppressedTracking_baselinesWithoutExpense()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 2500);

		// Uncharge while suppressed: varbit drops to 0 but no expense is recorded
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 0, false, 1);
		Assert.assertTrue(tracker.drain().isEmpty());

		// A fresh deposit baselines again; only consumption after it counts
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 2500, false, 2);
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 2499, true, 3);
		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertEquals(1, spent.get(ItemID.WILD_CAVE_SHARD).intValue());
	}

	@Test
	public void reset_clearsBaselinesAndPendingSpend()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		seed(tracker, VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 100);
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 97, true, 1);

		tracker.reset();

		// Next observation is a baseline again, not a diff against the stale value
		tracker.onVarbitChanged(VarbitID.CHARGES_WILDERNESS_WEAPON_QUANTITY, 3, true, 2);
		Assert.assertTrue(tracker.drain().isEmpty());
	}

	@Test
	public void reset_preservesLoadedDartType()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("Rune dart");
		tracker.reset();

		tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", 1);

		Assert.assertTrue(tracker.drain().containsKey(ItemID.RUNE_DART));
	}

	@Test
	public void clearLoadedDarts_stopsDartAccounting()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();
		tracker.recordUseSource("Rune dart");
		tracker.clearLoadedDarts();

		tracker.onAttackAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, "Toxic blowpipe", 1);

		Map<Integer, Integer> spent = tracker.drain();
		Assert.assertNull(spent.get(ItemID.RUNE_DART));
	}

	@Test
	public void untrackedVarbit_isIgnored()
	{
		WeaponChargeTracker tracker = new WeaponChargeTracker();

		tracker.onVarbitChanged(12345, 100, true, 1);
		tracker.onVarbitChanged(12345, 0, true, 2);

		Assert.assertTrue(tracker.drain().isEmpty());
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowConfig;
import com.coinflow.CoinFlowSession;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;

/**
 * Tests for {@link BlastFurnaceHandler}: belt-load ore/coal losses are
 * stripped (not expensed as owned drops), and collected bars are charged
 * their per-bar Blast Furnace recipe.
 */
@RunWith(MockitoJUnitRunner.class)
public class BlastFurnaceHandlerTest
{
	@Mock
	private ItemManager itemManager;

	@Mock
	private CoinFlowConfig config;

	private BlastFurnaceHandler handler;

	@Before
	public void setUp()
	{
		handler = new BlastFurnaceHandler();
		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));

		stubItem(ItemID.IRON_ORE, "Iron ore", 100L);
		stubItem(ItemID.COAL, "Coal", 200L);
		stubItem(ItemID.RUNITE_ORE, "Runite ore", 11_000L);
		stubItem(ItemID.MITHRIL_ORE, "Mithril ore", 160L);
		stubItem(ItemID.STEEL_BAR, "Steel bar", 800L);
		stubItem(ItemID.MITHRIL_BAR, "Mithril bar", 1_000L);
		stubItem(ItemID.RUNITE_BAR, "Runite bar", 12_000L);
	}

	private void stubItem(int id, String name, long price)
	{
		ItemComposition comp = mock(ItemComposition.class);
		lenient().when(comp.getName()).thenReturn(name);
		lenient().when(itemManager.getItemComposition(id)).thenReturn(comp);
		lenient().when(itemManager.getItemPrice(id)).thenReturn(price);
	}

	private ReconciliationContext context(Map<Integer, Integer> gains, Map<Integer, Integer> losses,
		boolean active)
	{
		ReconciliationContext ctx = new ReconciliationContext(
			gains,
			losses,
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			null,
			null,
			CoinFlowSession.createNew(),
			itemManager,
			config,
			null
		);
		ctx.setBlastFurnaceActive(active);
		return ctx;
	}

	private ReconciliationContext context(Map<Integer, Integer> gains, Map<Integer, Integer> losses,
		boolean active, CoinFlowSession session, java.util.Set<String> ignored)
	{
		ReconciliationContext ctx = new ReconciliationContext(
			gains,
			losses,
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			null,
			null,
			session,
			itemManager,
			config,
			ignored
		);
		ctx.setBlastFurnaceActive(active);
		return ctx;
	}

	private static Map<Integer, Integer> mapOf(int... idQtyPairs)
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < idQtyPairs.length; i += 2)
		{
			map.put(idQtyPairs[i], idQtyPairs[i + 1]);
		}
		return map;
	}

	// ── Belt-load losses ─────────────────────────────────────────────────

	@Test
	public void oreLoss_atFurnace_strippedNotExpensed()
	{
		Map<Integer, Integer> losses = mapOf(ItemID.IRON_ORE, 27);
		ReconciliationContext ctx = context(new HashMap<>(), losses, true);
		handler.reconcile(ctx);

		Assert.assertFalse("Belt-loaded ore must be stripped from the diff",
			ctx.getRawLosses().containsKey(ItemID.IRON_ORE));
		Assert.assertTrue("Belt-loaded ore must not book as a supply expense",
			ctx.getSupplyExpenses().isEmpty());
	}

	@Test
	public void oreLoss_notAtFurnace_untouched()
	{
		Map<Integer, Integer> losses = mapOf(ItemID.IRON_ORE, 27);
		ReconciliationContext ctx = context(new HashMap<>(), losses, false);
		handler.reconcile(ctx);

		Assert.assertEquals("Away from the furnace the loss stays for the normal path",
			27, (int) ctx.getRawLosses().get(ItemID.IRON_ORE));
	}

	@Test
	public void oreLoss_withDropIntent_kept()
	{
		Map<Integer, Integer> losses = mapOf(ItemID.IRON_ORE, 5);
		ReconciliationContext ctx = context(new HashMap<>(), losses, true);
		ctx.getDropIntentIds().add(ItemID.IRON_ORE);
		handler.reconcile(ctx);

		Assert.assertEquals("A Drop-clicked ore stays on the own-drop path",
			5, (int) ctx.getRawLosses().get(ItemID.IRON_ORE));
	}

	@Test
	public void notedOreLoss_kept()
	{
		int notedIronOre = 999_001;
		lenient().when(itemManager.canonicalize(notedIronOre)).thenReturn(ItemID.IRON_ORE);

		Map<Integer, Integer> losses = mapOf(notedIronOre, 27);
		ReconciliationContext ctx = context(new HashMap<>(), losses, true);
		handler.reconcile(ctx);

		Assert.assertTrue("Noted ore is bank business, not a belt load",
			ctx.getRawLosses().containsKey(notedIronOre));
	}

	@Test
	public void sessionOreGain_retiredOnBeltLoad()
	{
		Map<Integer, CoinFlowSession.TrackedItem> gains = new HashMap<>();
		gains.put(ItemID.IRON_ORE,
			new CoinFlowSession.TrackedItem(ItemID.IRON_ORE, "Iron ore", 27, 100L));
		CoinFlowSession session = CoinFlowSession.createNew()
			.withGainsLossesAndExpenses(gains, Collections.emptyMap(), Collections.emptyMap());

		Map<Integer, Integer> losses = mapOf(ItemID.IRON_ORE, 27);
		ReconciliationContext ctx = context(new HashMap<>(), losses, true, session, null);
		handler.reconcile(ctx);

		Assert.assertEquals("Session-mined ore loaded onto the belt is marked consumed",
			27L, (long) ctx.getConsumedSessionQuantities().getOrDefault(ItemID.IRON_ORE, 0L));
	}

	// ── Bar collection expenses ──────────────────────────────────────────

	@Test
	public void steelBarsCollected_chargesIronAndCoal()
	{
		Map<Integer, Integer> gains = mapOf(ItemID.STEEL_BAR, 27);
		ReconciliationContext ctx = context(gains, new HashMap<>(), true);
		handler.reconcile(ctx);

		CoinFlowSession.TrackedItem iron = ctx.getSupplyExpenses().get(ItemID.IRON_ORE);
		CoinFlowSession.TrackedItem coal = ctx.getSupplyExpenses().get(ItemID.COAL);
		Assert.assertNotNull("Iron ore input must be expensed", iron);
		Assert.assertNotNull("Coal input must be expensed", coal);
		Assert.assertEquals(27L, iron.getQuantity());
		Assert.assertEquals(27L, coal.getQuantity());
		Assert.assertEquals(100L, iron.getPriceEach());
		Assert.assertEquals(200L, coal.getPriceEach());
		Assert.assertTrue("The bar gain itself is left for the normal gain path",
			ctx.getRawGains().containsKey(ItemID.STEEL_BAR));
	}

	@Test
	public void runiteBarsCollected_chargesFourCoalPerBar()
	{
		Map<Integer, Integer> gains = mapOf(ItemID.RUNITE_BAR, 5);
		ReconciliationContext ctx = context(gains, new HashMap<>(), true);
		handler.reconcile(ctx);

		Assert.assertEquals(5L, ctx.getSupplyExpenses().get(ItemID.RUNITE_ORE).getQuantity());
		Assert.assertEquals("Runite costs 4 coal per bar at the Blast Furnace",
			20L, ctx.getSupplyExpenses().get(ItemID.COAL).getQuantity());
	}

	@Test
	public void mixedBars_mergesCoalExpense()
	{
		Map<Integer, Integer> gains = mapOf(ItemID.STEEL_BAR, 1, ItemID.MITHRIL_BAR, 1);
		ReconciliationContext ctx = context(gains, new HashMap<>(), true);
		handler.reconcile(ctx);

		Assert.assertEquals("1 (steel) + 2 (mithril) coal merge into one expense row",
			3L, ctx.getSupplyExpenses().get(ItemID.COAL).getQuantity());
		Assert.assertEquals(1L, ctx.getSupplyExpenses().get(ItemID.IRON_ORE).getQuantity());
		Assert.assertEquals(1L, ctx.getSupplyExpenses().get(ItemID.MITHRIL_ORE).getQuantity());
	}

