	private ReconciliationContext createContext(Map<Integer, Integer> rawLosses)
	{
		return new ReconciliationContext(
			new HashMap<>(),
			rawLosses,
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			InventorySnapshot.empty(),
			null,
			CoinFlowSession.createNew(),
			itemManager,
			config,
			Collections.emptySet()
		);
	}
